INSERT INTO "categories_domain" VALUES(1,'AI_DATA','[AI/Data] 인공지능 · 빅데이터 · 통계','LLM, RAG(Advanced/Modular), Agentic/Physical AI, MoE, GNN, MLOps, 파인튜닝/RLHF/RAFT, 추정/검정/다중공선성/잭나이프');
INSERT INTO "categories_domain" VALUES(2,'SW_ARCH','[SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트','MSA, 무중단 배포, ATAM/CBAM, ISO/IEC 25010, 맥케이브 순환복잡도, 뮤테이션/동적 테스트, 리팩토링/역공학, DevSecOps');
INSERT INTO "categories_domain" VALUES(3,'SEC','[Sec] 정보보안 · 암호 · 개인정보보호','제로트러스트, 국가망보안체계(N2SF), CTEM, 비인간 신원(NHI), 프롬프트 인젝션/MCP 보안, 동형/양자/타원곡선 암호, PET/가명처리, 포렌식/BPFdoor');
INSERT INTO "categories_domain" VALUES(4,'DB','[DB] 데이터베이스 · 데이터모델링 · 분산데이터','분산 DB 투명성/분할, 트랜잭션 격리수준/병행제어, 제4정규형/반정규화, NoSQL, 벡터DB(HNSW/IVF)/하이브리드 검색, 데이터 거버넌스/관측가능성');
