INSERT INTO "categories_domain" VALUES(6,'CA_OS','[CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅','GPU vs TPU 아키텍처, CXL, 캐시 메모리 쓰기 정책, OS 메모리 구조(Code/Data/Heap/Stack), 좀비 프로세스/세그먼테이션 오류, 은행가 알고리즘/세마포어, QML');
