INSERT INTO "questions" VALUES(120,137,3,4,4,'개념/정의형','데이터베이스트랜잭션격리수준(TransactionIsolationLevel)과관련하여아래사항을 설명하시오.','["가. 데이터베이스 트랜잭션 격리 수준4가지", "나. 데이터베이스 트랜잭션 격리 수준에 따라 발생할 수 있는이상 현상"]','["1. 리드문: 데이터베이스트랜잭션격리수준(TransactionIsolationLevel)과관련하여아래사항의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터베이스트랜잭션격리수준(TransactionIsolationLevel)과관련하여아래사항 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터베이스 트랜잭션 격리 수준4가지 및 데이터베이스 트랜잭션 격리 수준에 따라 발생할 수 있는이상 현상 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','TransactionIsolationLevel, 데이터베이스트랜잭션격리, 수준, 과관련하여아래사항, 데이터베이스, 트랜잭션, 격리, 따라','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 데이터베이스 트랜잭션 격리 수준4가지", "데이터베이스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 데이터베이스 트랜잭션 격리 수준에 따라 발생할 수 있는이상 현상", "데이터베이스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제137회 3교시 4번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''데이터베이스트랜잭션격리수준(TransactionIsolationLevel)과관련하여아래사항''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터베이스 트랜잭션 격리 수준4가지 · 데이터베이스 트랜잭션 격리 수준에 따라 발생할 수 있는이상 현상)을 필수 키워드(TransactionIsolationLevel, 데이터베이스트랜잭션격리, 수준, 과관련하여아래사항)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제137회 3교시 #4 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(121,137,3,5,5,'법제도/거버넌스형','통신 프로토콜에 대하여 각 항목을 설명하시오.','["가. 오류 제어, 혼잡제어", "나. 슬라이딩윈도우(Sliding Window) 기법", "다. 프로토콜 설계시 고려 사항"]','["1. 리드문: 통신 프로토콜에 대하여 각 항목의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 통신 프로토콜에 대하여 각 항목 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 오류 제어, 혼잡제어 및 슬라이딩윈도우(Sliding Window) 기법 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Sliding Window, 통신, 프로토콜, 항목, 오류, 제어, 혼잡제어, 슬라이딩윈도우','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 오류 제어, 혼잡제어", "오류 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 슬라이딩윈도우(Sliding Window) 기법", "Sliding Window 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 프로토콜 설계시 고려 사항", "프로토콜 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제137회 3교시 5번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''통신 프로토콜에 대하여 각 항목''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(오류 제어, 혼잡제어 · 슬라이딩윈도우(Sliding Window) 기법 · 프로토콜 설계시 고려 사항)을 필수 키워드(Sliding Window, 통신, 프로토콜, 항목)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제137회 3교시 #5 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(122,137,3,6,3,'개념/법제도보안형','국가 망 보안체계(N²SF, National Network Security Framework) 추진 배경과 구현 방안','["가. 기존 획일적 망분리 정책의 한계와 N2SF 전환 배경", "나. 업무 중요도에 따른 3단계 등급 분류(기밀 Class, 민감 Sensitive, 공개 Open) 및 차등 보안 통제", "다. 클라우드·생성형 AI 활용을 위한 CDS(영역 간 보안연계) 및 제로트러스트 결합 방안"]','["1. 리드문: 획일적 물리 망분리에서 데이터 중요도 기반 다층보안체계(N2SF)로의 전환", "2. N2SF 3등급(C: 기밀 / S: 민감 / O: 공개) 분류 및 영역 간 데이터 유통(CDS) 구조도", "3. 기존 망분리 정책 vs 국가 망 보안체계(N2SF) 비교표", "4. 공공·금융 부문 SaaS 및 생성형 AI 안전 활용을 위한 단계별 전환 로드맵"]','망분리 개선, N2SF(국가망보안체계), C/S/O 등급 분류(Classified/Sensitive/Open), 차등 보안통제, CDS(Cross Domain Solution), 제로트러스트','{"headers": ["비교 항목", "기존 물리적/논리적 망분리", "국가 망 보안체계 (N²SF)"], "rows": [["보안 패러다임", "업무망·인터넷망 이분법적 경계 차단 중심", "업무·정보 중요도(기밀 C / 민감 S / 공개 O)에 따른 차등적 보안 통제"], ["신기술 활용성", "외부 클라우드(SaaS) 및 생성형 AI(LLM) 연계 극히 제한적", "민감(S)·공개(O) 등급에서 보안통제 하에 외부 AI·SaaS 적극 활용 가능"], ["핵심 기술 요소", "망연계 솔루션, VDI/SBC", "데이터 등급 분류, CDS(Cross Domain Solution), 제로트러스트(ICAM, PEP/PDP)"]]}','국가 망 보안체계(N²SF)는 공공기관의 클라우드·생성형 AI 활용을 가로막던 획일적 망분리 규제를 개선하여, 취급하는 업무와 데이터의 중요도를 기밀(Classified), 민감(Sensitive), 공개(Open)의 3등급으로 분류하고 등급별로 차등화된 보안통제 항목을 적용하는 신보안 프레임워크다.','공공·금융 보안 최대 이슈로 제로트러스트와 함께 지속 출제 유력','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(123,137,4,1,3,'비교/대조분석형','BPFdoor(Berkeley Packet Filter door) 악성코드와 관련하여 다음을 설명하시오.','["가. BPFdoor의개념 및 기존 백도어 방식과의 차이점", "나. BPFdoor의위협요소와 기업 시스템에 미치는 영향", "다. BPFdoor의위협에대응하기 위한기술적, 관리적 방안 제시"]','["1. 리드문: BPFdoor(Berkeley Packet Filter door) 악성코드의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: BPFdoor(Berkeley Packet Filter door) 악성코드 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: BPFdoor의개념 및 기존 백도어 방식과의 차이점 및 BPFdoor의위협요소와 기업 시스템에 미치는 영향 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','BPFdoor, Berkeley Packet Filter door, 악성코드, 의개념, 기존, 백도어, 방식과, 의위협요소','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. BPFdoor의개념 및 기존 백도어 방식과의 차이점", "BPFdoor 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. BPFdoor의위협요소와 기업 시스템에 미치는 영향", "BPFdoor 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. BPFdoor의위협에대응하기 위한기술적, 관리적 방안 제시", "BPFdoor 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제137회 4교시 1번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''BPFdoor(Berkeley Packet Filter door) 악성코드''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(BPFdoor의개념 및 기존 백도어 방식과의 차이점 · BPFdoor의위협요소와 기업 시스템에 미치는 영향 · BPFdoor의위협에대응하기 위한기술적, 관리적 방안 제시)을 필수 키워드(BPFdoor, Berkeley Packet Filter door, 악성코드, 의개념)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제137회 4교시 #1 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(124,137,4,2,4,'비교/알고리즘형','벡터 데이터베이스(Vector DB)의 효율적 검색을 위한 HNSW와 IVF 인덱싱 기법 비교','["가. 고차원 임베딩 공간에서 근사 최근접 이웃(ANN, Approximate Nearest Neighbor) 검색의 필요성", "나. 그래프 기반 HNSW와 군집 기반 IVF(Inverted File Index)의 동작 원리 및 장단점 비교", "다. 대규모 RAG 시스템에서 PQ(Product Quantization) 결합을 통한 메모리·성능 최적화 방안"]','["1. 리드문: 고차원 벡터 검색의 차원의 저주 극복을 위한 ANN 인덱싱 정의", "2. HNSW(다층 스킵리스트 그래프 탐색) vs IVF(보로노이 셀 군집 탐색) 구조도", "3. Flat(전수조사) vs IVF vs HNSW vs PQ 결합 비교표", "4. 실시간 업데이트 빈도와 메모리 제약에 따른 엔터프라이즈 Vector DB 인덱스 선정 기준"]','ANN(근사 최근접 이웃), HNSW(Hierarchical Navigable Small World), IVF(Inverted File Index), PQ(Product Quantization), Recall@K vs QPS','{"headers": ["인덱스 기법", "동작 원리", "검색 속도 / 재현율(Recall)", "메모리 사용량 및 특징"], "rows": [["IVF (역파일 인덱스)", "K-Means로 벡터 공간을 보로노이 셀로 군집화 후 인접 중심점(nprobe) 셀만 탐색", "빠름 / nprobe 설정에 비례", "메모리 효율 우수, 경계면(Edge) 근처 벡터 누락 방지 위해 nprobe 튜닝 필요"], ["HNSW (계층적 소세계 그래프)", "Skip-list와 NSW 그래프를 결합하여 상위 희소 계층에서 하위 밀집 계층으로 고속 이동", "매우 빠름(최고 QPS) / 매우 높음", "그래프 간선(M) 저장으로 메모리(RAM) 소모가 매우 큼"], ["IVF-PQ / HNSW-PQ", "고차원 벡터를 서브벡터로 쪼개어 코드북 ID로 양자화 압축(Product Quantization)", "초고속 연산(비대칭 거리계산) / 약간의 정밀도 손실", "메모리 사용량을 1/4 ~ 1/16로 대폭 압축하여 수억 건 규모 서빙에 필수"]]}','고차원 벡터 데이터베이스에서 전수 조사(Flat KNN)는 연산량이 폭증하므로 약간의 정확도를 트레이드오프하여 속도를 극대화하는 ANN(Approximate Nearest Neighbor) 인덱싱이 필수적이다. HNSW는 다층 소세계 그래프를 통해 최고 수준의 검색 속도와 재현율(Recall)을 제공하나 메모리 소모가 크며, IVF는 K-Means 클러스터링 기반으로 메모리 효율이 좋아 PQ(곱 양자화)와 결합해 대규모 벡터 서빙에 활용된다.','RAG 인프라의 핵심 기술 기출','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(125,137,4,3,5,'개념/정의형','쿠버네티스(Kubernetes)에 대하여 다음을 설명하시오.','["가. 쿠버네티스의 개념및 특징", "나. 쿠버네티스의 주요컴포넌트", "다. HPA(HorizontalPod Autoscaler)"]','["1. 리드문: 쿠버네티스(Kubernetes)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 쿠버네티스(Kubernetes) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 쿠버네티스의 개념및 특징 및 쿠버네티스의 주요컴포넌트 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Kubernetes, HPA, HorizontalPod Autoscaler, 쿠버네티스, 개념및, 주요컴포넌트, 프로토콜 스택','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 쿠버네티스의 개념및 특징", "쿠버네티스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 쿠버네티스의 주요컴포넌트", "쿠버네티스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. HPA(HorizontalPod Autoscaler)", "HPA 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제137회 4교시 3번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''쿠버네티스(Kubernetes)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(쿠버네티스의 개념및 특징 · 쿠버네티스의 주요컴포넌트 · HPA(HorizontalPod Autoscaler))을 필수 키워드(Kubernetes, HPA, HorizontalPod Autoscaler, 쿠버네티스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제137회 4교시 #3 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(126,137,4,4,2,'절차/설계구현형','UML(UnifiedModelingLanguage)에서사용하는행위 다이어그램(BehaviorDiagram) 인 활동다이어그램(ActivityDiagram), 상태 다이어그램(StateDiagram), 그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여 각각 설명하시오.','["1. 그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','UML, UnifiedModelingLanguage, BehaviorDiagram, ActivityDiagram, StateDiagram, Use-Case Diagram, 에서사용하는행위, 다이어그램','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제137회 4교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(그리고유스케이스 다이어그램(Use-Case Diagram)에 대하여의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(UML, UnifiedModelingLanguage, BehaviorDiagram, ActivityDiagram)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제137회 4교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(127,137,4,5,1,'법제도/거버넌스형','유전 알고리즘(Genetic Algorithm)에 대하여 설명하시오.','["가. 유전 알고리즘의개념 및 절차", "나. 유전 알고리즘의최적화방법"]','["1. 리드문: 유전 알고리즘(Genetic Algorithm)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 유전 알고리즘(Genetic Algorithm)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 유전 알고리즘의개념 및 절차 및 유전 알고리즘의최적화방법 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Genetic Algorithm, 유전, 알고리즘, 알고리즘의개념, 알고리즘의최적화방법, 아키텍처, 성능지표','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 유전 알고리즘의개념 및 절차", "유전 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 유전 알고리즘의최적화방법", "유전 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제137회 4교시 5번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''유전 알고리즘(Genetic Algorithm)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(유전 알고리즘의개념 및 절차 · 유전 알고리즘의최적화방법)을 필수 키워드(Genetic Algorithm, 유전, 알고리즘, 알고리즘의개념)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제137회 4교시 #5 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
