INSERT INTO "questions" VALUES(131,136,1,3,1,'개념/아키텍처형','에이전틱 AI(Agentic AI)의 개념 및 핵심 구성요소','["1. 수동적 생성형 AI(Generative AI)와 자율적 에이전틱 AI의 차이점", "2. 에이전틱 AI 4대 핵심 구성요소(Planning, Memory, Tool Use, Action/Reflection)"]','["1. 리드문: 프롬프트 응답에서 목표 지향 자율 실행으로 진화한 Agentic AI", "2. Agentic AI 아키텍처(Perception - Brain/Planning - Memory - Tool/MCP Action) 구조도", "3. 전통 RPA vs 생성형 AI(Copilot) vs 에이전틱 AI(Autonomous Agent) 비교", "4. Multi-Agent 오케스트레이션(A2A/MCP) 및 무한 루프·권한 통제(HITL) 제언"]','Autonomous Agent, Planning(ReAct, CoT, ToT), 단기/장기 메모리, Tool Use(Function Calling, MCP), Self-Reflection, Multi-Agent','{"headers": ["구분", "생성형 AI (Generative AI / Copilot)", "에이전틱 AI (Agentic AI)"], "rows": [["주도권 및 작동 방식", "인간 프롬프트 입력 시 단일 턴(Single-turn) 콘텐츠 생성 (수동적)", "최종 목표 부여 시 스스로 하위 과업 분해·도구 호출·검증 수행 (자율적)"], ["핵심 메커니즘", "Next-Token Prediction, In-context Learning", "계획(Planning) + 기억(Memory) + 도구 사용(Tool/MCP) + 성찰(Reflection)"], ["주요 리스크", "환각(Hallucination), 부적절한 텍스트 생성", "비인가 API 실행, 에이전트 간 루프, 비인간 신원(NHI) 권한 오남용"]]}','에이전틱 AI(Agentic AI)는 사용자의 세부 지시 없이도 상위 목표를 달성하기 위해 스스로 계획을 수립(Planning)하고, 외부 도구·API(MCP)를 호출하며, 실행 결과를 스스로 점검(Self-Reflection)하여 다단계 과업을 완수하는 자율형 인공지능 시스템이다.','136회 1교시 출제 후 137회 MCP, 140회 AI-BPR/NHI로 파생 확장','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(132,136,1,4,4,'개념/데이터모델링형','데이터베이스 제4정규형(4NF)과 다치 종속(Multi-valued Dependency)','["1. 다치 종속(MVD, A ->> B)의 개념과 발생 조건", "2. 제4정규형(4NF)의 정의 및 정규화 수행 사례"]','["1. 리드문: BCNF 이후 이상현상 제거를 위한 다치 종속(MVD)과 제4정규형 정의", "2. 하나의 릴레이션에 두 개 이상의 독립적인 1:N 다치 속성이 공존할 때의 카티션 곱 중복 구조도", "3. BCNF vs 제4정규형(4NF) vs 제5정규형(5NF) 비교표", "4. 실무 대용량 DB에서의 정규화 및 조회 성능 고려 반정규화 기준"]','다치 종속(MVD, A ->> B), 자명한 다치 종속, 슈퍼키(Super Key), 제4정규형(4NF), 카티션 곱 중복 제거, 5NF(조인 종속)','{"headers": ["정규화 단계", "제거 대상 종속성", "핵심 성립 조건"], "rows": [["BCNF (보이스-코드 정규형)", "결정자가 후보키가 아닌 함수 종속(FD) 제거", "모든 결정자(Determinant)가 후보키(Super Key)일 것"], ["제4정규형 (4NF)", "비자명 다치 종속(Multi-valued Dependency, A ->> B) 제거", "한 테이블에 독립적인 1:N 다치 속성이 2개 이상 함께 존재하지 않도록 분해"], ["제5정규형 (5NF, PJNF)", "후보키를 통하지 않는 조인 종속(Join Dependency) 제거", "무손실 조인 분해 시 모든 조인 종속이 후보키에 의해서만 성립할 것"]]}','제4정규형(4NF)은 보이스-코드 정규형(BCNF)을 만족하면서, 자명하지 않은 다치 종속(Multi-valued Dependency, A ->> B)이 존재할 때 모든 결정자 A가 슈퍼키이도록 독립된 릴레이션으로 분해한 상태다. 예를 들어 사원 테이블에 독립적인 다치 속성인 [자격증]과 [어학능력]이 함께 있으면 불필요한 조합 중복이 발생하므로 두 테이블로 분리해야 4NF를 만족한다.','DB 정규화 이론 핵심 빈출','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(133,136,1,5,2,'개념/정의형','프록시(Proxy) 디자인 패턴','["1. 프록시(Proxy) 디자인 패턴의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 프록시(Proxy) 디자인 패턴의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 프록시(Proxy) 디자인 패턴 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 프록시(Proxy) 디자인 패턴 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Proxy, 프록시, 디자인, 패턴, 품질속성, 유지보수성, 설계원칙','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "프록시(Proxy) 디자인 패턴의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "프록시(Proxy) 디자인 패턴의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "프록시(Proxy) 디자인 패턴의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "프록시(Proxy) 디자인 패턴 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 1교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''프록시(Proxy) 디자인 패턴''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(프록시(Proxy) 디자인 패턴의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Proxy, 프록시, 디자인, 패턴)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 1교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(134,136,1,6,2,'개념/정의형','DevOps 장점과 단점','["1. DevOps 장점과 단점의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: DevOps 장점과 단점의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: DevOps 장점과 단점 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: DevOps 장점과 단점 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','DevOps, 장점, 단점, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "DevOps 장점과 단점의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "DevOps 장점과 단점의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "DevOps 장점과 단점의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "DevOps 장점과 단점 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 1교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''DevOps 장점과 단점''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(DevOps 장점과 단점의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(DevOps, 장점, 단점, 품질속성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 1교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(135,136,1,7,6,'개념/정의형','세그먼테이션 오류(Segmentation Fault)','["1. 세그먼테이션 오류(Segmentation Fault)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 세그먼테이션 오류(Segmentation Fault)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 세그먼테이션 오류(Segmentation Fault) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 세그먼테이션 오류(Segmentation Fault) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','Segmentation Fault, 세그먼테이션, 오류, 자원스케줄링, 메모리 계층, 동기화·일관성, 성능병목','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "세그먼테이션 오류(Segmentation Fault)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "세그먼테이션 오류(Segmentation Fault)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "세그먼테이션 오류(Segmentation Fault)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "세그먼테이션 오류(Segmentation Fault) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 1교시 7번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''세그먼테이션 오류(Segmentation Fault)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(세그먼테이션 오류(Segmentation Fault)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Segmentation Fault, 세그먼테이션, 오류, 자원스케줄링)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 1교시 #7 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(136,136,1,8,6,'개념/컴퓨터구조형','CXL(Compute Express Link) 인터커넥트 기술','["1. PCIe 기반 CXL 프로토콜의 등장 배경과 메모리 벽(Memory Wall) 문제", "2. 3가지 세부 프로토콜(CXL.io, CXL.cache, CXL.mem) 및 메모리 풀링(Memory Pooling)·공유 구조"]','["1. 리드문: 이기종 컴퓨팅 메모리 확장 및 캐시 일관성을 위한 CXL 정의", "2. CXL 3대 프로토콜(CXL.io / CXL.cache / CXL.mem) 및 스위치 기반 메모리 풀링 구조도", "3. 기존 서버 고정 할당 메모리 vs CXL 메모리 확장·풀링(CXL 1.1 / 2.0 / 3.0) 비교", "4. 초거대 AI 추론 서버의 GPU VRAM 한계 극복을 위한 CXL-PNM/CMS 활용 방안"]','Memory Wall, PCIe 5.0/6.0 물리계층, CXL.io, CXL.cache, CXL.mem, 캐시 일관성(Cache Coherency), Memory Pooling(메모리 풀링)','{"headers": ["CXL 프로토콜", "핵심 역할", "적용 시나리오"], "rows": [["CXL.io", "PCIe 기반 장치 탐색, 초기화, 설정, DMA 및 인터럽트 처리 (필수 기본 프로토콜)", "모든 CXL 디바이스의 기본 I/O 제어"], ["CXL.cache", "가속기(GPU/FPGA/NIC)가 호스트 CPU 메모리에 저지연 캐시 일관성으로 접근", "스마트NIC, AI 가속기가 CPU 메모리를 직접 참조"], ["CXL.mem", "호스트 CPU가 CXL 장치에 장착된 확장 메모리(DRAM/PMEM)를 자신의 메모리 공간처럼 로드/스토어", "CXL 메모리 확장기(Type 3) 및 다중 서버 간 동적 메모리 풀링"]]}','CXL(Compute Express Link)은 PCIe 5.0/6.0 물리 계층 위에서 CPU와 GPU·가속기·메모리 확장 장치 간 초저지연 캐시 일관성(Cache Coherency)과 메모리 공유(Memory Pooling)를 제공하는 개방형 인터커넥트 표준이다. CXL.io, CXL.cache, CXL.mem 3가지 프로토콜을 통해 서버 간 유휴 메모리를 동적으로 할당하고 AI 추론의 메모리 병목(Memory Wall)을 해소한다.','138회 GPU/TPU, 137회 캐시 메모리와 함께 컴퓨터구조 3대 축','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(137,136,1,9,5,'개념/정의형','서버리스 컴퓨팅(Serverless Computing)','["1. 서버리스 컴퓨팅(Serverless Computing)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 서버리스 컴퓨팅(Serverless Computing)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 서버리스 컴퓨팅(Serverless Computing) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 서버리스 컴퓨팅(Serverless Computing) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Serverless Computing, 서버리스, 컴퓨팅, 프로토콜 스택, 대역폭·지연시간, 고가용성, 트래픽 제어','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "서버리스 컴퓨팅(Serverless Computing)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "서버리스 컴퓨팅(Serverless Computing)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "서버리스 컴퓨팅(Serverless Computing)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "서버리스 컴퓨팅(Serverless Computing) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 1교시 9번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''서버리스 컴퓨팅(Serverless Computing)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(서버리스 컴퓨팅(Serverless Computing)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Serverless Computing, 서버리스, 컴퓨팅, 프로토콜 스택)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 1교시 #9 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(138,136,1,10,8,'비교/법제도형','개인정보 안심구역과 데이터 안심구역 비교','["1. 안전한 데이터 결합·분석을 위한 안심구역 제도의 취지", "2. 개인정보보호법상 개인정보 안심구역과 데이터산업법상 데이터 안심구역의 차이점 비교"]','["1. 리드문: 민감·미개방 데이터의 안전한 AI 학습·분석을 위한 안심구역 제도", "2. 제로트러스트·물리/논리 폐쇄망 기반 안심구역 분석 및 반출 심의 구조도", "3. 개인정보 안심구역 vs 데이터 안심구역 비교표 (소관부처, 근거법령, 취급대상, 핵심특례)", "4. 합성데이터 및 연합학습 연계 안심구역 고도화 제언"]','개인정보보호위원회(개인정보보호법), 과기정통부(데이터산업법), 가명정보 결합·샘플링, 미개방 원본 데이터, 반출심의위원회','{"headers": ["비교 항목", "개인정보 안심구역", "데이터 안심구역"], "rows": [["소관 부처 / 근거 법령", "개인정보보호위원회 / 개인정보 보호법(고시)", "과학기술정보통신부·국토부 등 / 데이터 산업진흥 및 이용촉진 기본법"], ["주요 취급 데이터", "높은 수준의 가명정보, 장기 시계열 결합 가명정보, AI 학습용 비정형 가명정보", "유출 시 위험이 큰 미개방 원천 데이터(금융, 교통, 의료, 기업 비밀 데이터 등)"], ["핵심 허용 특례", "사전 적정성 검토 간소화, 표본 추출(샘플링)·반복 결합 및 장기 보관 허용", "폐쇄된 보안 환경 내에서 미개방 데이터 분석 후 통계·AI 모델 가중치만 심사 후 반출"]]}','개인정보 안심구역은 개인정보보호위원회가 지정하여 제3자 제공 시 재식별 위험이 있는 고가치 가명정보의 유연한 샘플링·장기 시계열 분석·AI 학습을 허용하는 공간이며, 데이터 안심구역은 과기정통부 등이 데이터산업법에 의거하여 외부에 공개하기 어려운 미개방 원천 데이터를 물리·기술적으로 통제된 공간에서 분석하고 결과물(AI 모델 등)만 반출하도록 지원하는 제도다.','135회 1교시 개인정보 안심구역 → 136회 1교시 데이터 안심구역과의 비교로 연속 출제!','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(139,136,1,11,3,'개념/정의형','CC(Common Criteria)','["1. CC(Common Criteria)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: CC(Common Criteria)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: CC(Common Criteria) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: CC(Common Criteria) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','CC, Common Criteria, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "CC(Common Criteria)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "CC(Common Criteria)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "CC(Common Criteria)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "CC(Common Criteria) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 1교시 11번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''CC(Common Criteria)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(CC(Common Criteria)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(CC, Common Criteria, 기밀성·무결성, 보안통제)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 1교시 #11 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(140,136,1,12,3,'개념/정의형','타원곡선 암호(ECC, Elliptic Curve Cryptography)','["1. 타원곡선 암호(ECC, Elliptic Curve Cryptography)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 타원곡선 암호(ECC, Elliptic Curve Cryptography)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 타원곡선 암호(ECC, Elliptic Curve Cryptography) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 타원곡선 암호(ECC, Elliptic Curve Cryptography) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','ECC, Elliptic Curve Cryptography, 타원곡선, 암호, 기밀성·무결성, 보안통제, 위협모델링','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "타원곡선 암호(ECC, Elliptic Curve Cryptography)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "타원곡선 암호(ECC, Elliptic Curve Cryptography)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "타원곡선 암호(ECC, Elliptic Curve Cryptography)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "타원곡선 암호(ECC, Elliptic Curve Cryptography) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 1교시 12번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''타원곡선 암호(ECC, Elliptic Curve Cryptography)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(타원곡선 암호(ECC, Elliptic Curve Cryptography)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(ECC, Elliptic Curve Cryptography, 타원곡선, 암호)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 1교시 #12 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(141,136,1,13,2,'개념/정의형','MCP(Model Context Protocol)','["1. MCP(Model Context Protocol)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: MCP(Model Context Protocol)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: MCP(Model Context Protocol) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: MCP(Model Context Protocol) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','MCP, Model Context Protocol, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "MCP(Model Context Protocol)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "MCP(Model Context Protocol)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "MCP(Model Context Protocol)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "MCP(Model Context Protocol) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 1교시 13번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''MCP(Model Context Protocol)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(MCP(Model Context Protocol)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(MCP, Model Context Protocol, 품질속성, 유지보수성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 1교시 #13 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(142,136,2,1,7,'개념/정의형','공급망관리(SCM, Supply Chain Management)에 대하여 다음을 설명하시오.','["가. 공급망관리의 정의와 배경", "나. 공급망관리에서 효과성과 효율성"]','["1. 리드문: 공급망관리(SCM, Supply Chain Management)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 공급망관리(SCM, Supply Chain Management) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 공급망관리의 정의와 배경 및 공급망관리에서 효과성과 효율성 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','SCM, Supply Chain Management, 공급망관리, 효과성, 효율성, 거버넌스, ROI·성과지표','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 공급망관리의 정의와 배경", "공급망관리 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 공급망관리에서 효과성과 효율성", "공급망관리 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 2교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''공급망관리(SCM, Supply Chain Management)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(공급망관리의 정의와 배경 · 공급망관리에서 효과성과 효율성)을 필수 키워드(SCM, Supply Chain Management, 공급망관리, 효과성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 2교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(143,136,2,2,5,'비교/클라우드형','서버리스 컴퓨팅(Serverless Computing: FaaS + BaaS) 아키텍처의 특징과 Cold Start(콜드 스타트) 발생 원인 및 완화 기법','["가. 서버 프로비저닝 없는 이벤트 기반 FaaS(AWS Lambda 등)의 동작 원리와 장단점", "나. 컨테이너 초기화·런타임 로딩으로 인한 Cold Start 지연 분석 및 Provisioned Concurrency/SnapStart/Wasm 완화 전략"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','서버리스 컴퓨팅, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["가. 서버 프로비저닝 없는 이벤트 기반 FaaS(AWS Lambda 등)의 동작 원리와 장단점", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["나. 컨테이너 초기화·런타임 로딩으로 인한 Cold Start 지연 분석 및 Provisioned Concurrency/SnapStart/Wasm 완화 전략", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','서버리스 컴퓨팅(Serverless Computing: FaaS + BaaS) 아키텍처의 특징과 Cold Start(콜드 스타트) 발생 원인 및 완화 기법 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 가. 서버 프로비저닝 없는 이벤트 기반 FaaS(AWS Lambda 등)의 동작 원리와 장단점 및 나. 컨테이너 초기화·런타임 로딩으로 인한 Cold Start 지연 분석 및 Provisioned Concurrency/SnapStart/Wasm 완화 전략을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제136회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(144,136,2,2,7,'비교/대조분석형','정보시스템구축사업의성공적인수행을위해정보시스템감리와PMO(전자정부사업관리 위탁)를 활용하여 사업관리를 수행하고 있다.이와 관련하여 다음을 설명하시오.','["가. 정보시스템 감리의 법적 근거", "나. PMO의 정의와 역할", "다. PMO 대상 사업의 범위", "라. PMO와 상주감리의 비교"]','["1. 리드문: 정보시스템구축사업의성공적인수행을위해정보시스템감리와PMO(전자정부사업관리 위탁)를 활용하여 사업관리를 수행하고 있다.이의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보시스템구축사업의성공적인수행을위해정보시스템감리와PMO(전자정부사업관리 위탁)를 활용하여 사업관리를 수행하고 있다.이 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보시스템 감리의 법적 근거 및 PMO의 정의와 역할 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','PMO, 정보시스템구축사업의성공, 적인수행을위해정보시스템, 감리, 전자정부사업관리, 위탁, 활용하여, 사업관리','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 정보시스템 감리의 법적 근거", "정보시스템 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. PMO의 정의와 역할", "PMO 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. PMO 대상 사업의 범위", "PMO 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. PMO와 상주감리의 비교", "PMO 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 2교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''정보시스템구축사업의성공적인수행을위해정보시스템감리와PMO(전자정부사업관리 위탁)를 활용하여 사업관리를 수행하고 있다.이''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보시스템 감리의 법적 근거 · PMO의 정의와 역할 · PMO 대상 사업의 범위)을 필수 키워드(PMO, 정보시스템구축사업의성공, 적인수행을위해정보시스템, 감리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 2교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(145,136,2,3,3,'원인분석/대응전략형','AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안을 설명하시오.','["1. AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','AI, LLM, Large Language Model, 소프트웨어, 개발, 도입할, 고려해야, 보안','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 2교시 3번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(AI 기반 소프트웨어 개발에서 LLM(Large Language Model)을 도입할 때 고려해야 할 보안 위험을 3가지 이상 쓰고 각 대응 방안의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(AI, LLM, Large Language Model, 소프트웨어)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 2교시 #3 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(146,136,2,4,2,'법제도/거버넌스형','소프트웨어 개발방법론 중 하나인 제품계열(Product Line) 방법론에 대하여 다음을 설명하시오.','["가. 개념과 특징", "나. 활용 기술과 고려사항"]','["1. 리드문: 소프트웨어 개발방법론 중 하나인 제품계열(Product Line) 방법론의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 개발방법론 중 하나인 제품계열(Product Line) 방법론 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개념과 특징 및 활용 기술과 고려사항 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Product Line, 소프트웨어, 개발방법론, 하나인, 제품계열, 방법론, 기술','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 개념과 특징", "품질속성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 활용 기술과 고려사항", "기술 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 2교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 개발방법론 중 하나인 제품계열(Product Line) 방법론''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개념과 특징 · 활용 기술과 고려사항)을 필수 키워드(Product Line, 소프트웨어, 개발방법론, 하나인)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 2교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(147,136,2,5,4,'비교/대조분석형','데이터베이스 인덱스(Index)를 설명하고, 클러스터드 인덱스(Clustered Index)와 논클러스터드 인덱스(Non-Clustered Index)를 비교하여 설명하시오.','["1. 클러스터드 인덱스(Clustered Index)와 논클러스터드 인덱스(Non-Clustered Index)의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 클러스터드 인덱스(Clustered Index)와 논클러스터드 인덱스(Non-Clustered Index)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 클러스터드 인덱스(Clustered Index)와 논클러스터드 인덱스(Non-Clustered Index) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 클러스터드 인덱스(Clustered Index)와 논클러스터드 인덱스(Non-Clustered Index) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','Index, Clustered Index, Non-Clustered Index, 데이터베이스, 인덱스, 설명하고, 클러스터드, 논클러스터드','{"headers": ["비교 항목", "클러스터드 인덱스(Clustered Index)", "논클러스터드 인덱스(Non-Clustered Index)"], "rows": [["핵심 개념·목적", "클러스터드 인덱스(Clustered Inde의 고유 목적 및 적용 영역 정의", "논클러스터드 인덱스(Non-Clustered의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제136회 2교시 5번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''클러스터드 인덱스(Clustered Index)와 논클러스터드 인덱스(Non-Clustered Index)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(클러스터드 인덱스(Clustered Index)와 논클러스터드 인덱스(Non-Clustered Index)의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Index, Clustered Index, Non-Clustered Index, 데이터베이스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 2교시 #5 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(148,136,2,6,3,'원인분석/대응전략형','인터넷통신에서보안성강화를위해 활용되는TLS(TransportLayerSecurity)1.2에 대한취약점이발견되어TLS1.3사용을권고하고있다.이와관련하여다음을 설명하시오.','["가. TLS 프로토콜 구조와 핸드셰이크(Handshake) 과정", "나. TLS 1.2 보안 취약점과 TLS 1.3 개선 사항"]','["1. 리드문: 인터넷통신에서보안성강화를위해 활용되는TLS(TransportLayerSecurity)1.2에 대한취약점이발견되어TLS1.3사용을권고하고있다.이와관련하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인터넷통신에서보안성강화를위해 활용되는TLS(TransportLayerSecurity)1.2에 대한취약점이발견되어TLS1.3사용을권고하고있다.이와관련하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: TLS 프로토콜 구조와 핸드셰이크(Handshake) 과정 및 TLS 1.2 보안 취약점과 TLS 1.3 개선 사항 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','TLS, TransportLayerSecurity, TLS1, Handshake, TLS 1, 인터넷통신에서보안성강화, 를위해, 활용되','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. TLS 프로토콜 구조와 핸드셰이크(Handshake) 과정", "TLS 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. TLS 1.2 보안 취약점과 TLS 1.3 개선 사항", "TLS 1 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 2교시 6번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''인터넷통신에서보안성강화를위해 활용되는TLS(TransportLayerSecurity)1.2에 대한취약점이발견되어TLS1.3사용을권고하고있다.이와관련하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(TLS 프로토콜 구조와 핸드셰이크(Handshake) 과정 · TLS 1.2 보안 취약점과 TLS 1.3 개선 사항)을 필수 키워드(TLS, TransportLayerSecurity, TLS1, Handshake)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 2교시 #6 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(149,136,3,1,7,'원인분석/대응전략형','IT프로젝트수행시PM은프로젝트내·외부의다양한갈등을관리하고해소하여야한다. PM의 입장에서 다음을 설명하시오.','["가. 갈등과 프로젝트 성과의 관계", "나. 갈등의 요인과 해결 전략", "다. 터크만(Tuckman)의 팀 발달 5단계 모델"]','["1. 리드문: PM의 입장에서의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: PM의 입장에서 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 갈등과 프로젝트 성과의 관계 및 갈등의 요인과 해결 전략 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IT, PM, Tuckman, 프로젝트수행시, 은프로젝트내, 외부의다양한갈등을관리하, 고해소하여야한다, 입장','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 갈등과 프로젝트 성과의 관계", "갈등 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 갈등의 요인과 해결 전략", "갈등 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 터크만(Tuckman)의 팀 발달 5단계 모델", "Tuckman 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 3교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''PM의 입장에서''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(갈등과 프로젝트 성과의 관계 · 갈등의 요인과 해결 전략 · 터크만(Tuckman)의 팀 발달 5단계 모델)을 필수 키워드(IT, PM, Tuckman, 프로젝트수행시)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 3교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(150,136,3,2,1,'원인분석/대응전략형','최근 인공지능(AI)을 활용한 기업의 디지털 전환(AX, AI Transformation)이 다양한 산업 분야에서 빠르게 진행되고 있다. 이와 관련하여 다음을 설명하시오.','["가. 기업에서 AX가 중요한 이유", "나. 기업에서 AX를 성공적으로 추진하기 위한 전략적 추진 절차와 고려사항", "다. 기업이 AX를 추진할 때 발생 가능한 장애 요인 3가지 이상과 각 대응방안"]','["1. 리드문: 최근 인공지능(AI)을 활용한 기업의 디지털 전환(AX, AI Transformation)이 다양한 산업 분야에서 빠르게 진행되고 있다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 최근 인공지능(AI)을 활용한 기업의 디지털 전환(AX, AI Transformation)이 다양한 산업 분야에서 빠르게 진행되고 있다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 기업에서 AX가 중요한 이유 및 기업에서 AX를 성공적으로 추진하기 위한 전략적 추진 절차와 고려사항 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','AI, AX, AI Transformation, 인공지능, 활용한, 디지털, 전환, 다양한','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 기업에서 AX가 중요한 이유", "AX 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 기업에서 AX를 성공적으로 추진하기 위한 전략적 추진 절차와 고려사항", "AX 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 기업이 AX를 추진할 때 발생 가능한 장애 요인 3가지 이상과 각 대응방안", "AX 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 3교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''최근 인공지능(AI)을 활용한 기업의 디지털 전환(AX, AI Transformation)이 다양한 산업 분야에서 빠르게 진행되고 있다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(기업에서 AX가 중요한 이유 · 기업에서 AX를 성공적으로 추진하기 위한 전략적 추진 절차와 고려사항 · 기업이 AX를 추진할 때 발생 가능한 장애 요인 3가지 이상과 각 대응방안)을 필수 키워드(AI, AX, AI Transformation, 인공지능)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 3교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(151,136,3,3,2,'개념/정의형','소프트웨어 품질의 의미 (소프트웨어 품질보증과 관련하여 다음을 설명하시오)','["가. 소프트웨어 품질의 의미", "나. 소프트웨어 품질보증의 목적과 기능", "다. 인스펙션(Inspection)과 인스펙션 프로세스(Inspection Process)"]','["1. 리드문: 소프트웨어 품질의 의미 (소프트웨어 품질보증과 관련하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 품질의 의미 (소프트웨어 품질보증과 관련하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 품질의 의미 및 소프트웨어 품질보증의 목적과 기능 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Inspection, Inspection Process, 소프트웨어, 품질보증, 품질, 의미, 인스펙션, 프로세스','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 소프트웨어 품질의 의미", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 소프트웨어 품질보증의 목적과 기능", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 인스펙션(Inspection)과 인스펙션 프로세스(Inspection Process)", "Inspection 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 3교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 품질의 의미 (소프트웨어 품질보증과 관련하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 품질의 의미 · 소프트웨어 품질보증의 목적과 기능 · 인스펙션(Inspection)과 인스펙션 프로세스(Inspection Process))을 필수 키워드(Inspection, Inspection Process, 소프트웨어, 품질보증)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 3교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(152,136,3,4,1,'비교/대조분석형','데이터 분석 시 아웃라이어(Outlier)에 대하여 다음을 설명하시오.','["가. 아웃라이어의 개념", "나. 아웃라이어와 노이즈(Noise)의 차이점", "다. 아웃라이어의 3가지 유형인 전역, 맥락, 군집"]','["1. 리드문: 데이터 분석 시 아웃라이어(Outlier)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 분석 시 아웃라이어(Outlier) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 아웃라이어의 개념 및 아웃라이어와 노이즈(Noise)의 차이점 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Outlier, Noise, 데이터, 분석, 아웃라이어, 노이즈, 유형인, 전역','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 아웃라이어의 개념", "아웃라이어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 아웃라이어와 노이즈(Noise)의 차이점", "Noise 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 아웃라이어의 3가지 유형인 전역, 맥락, 군집", "아웃라이어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 3교시 4번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''데이터 분석 시 아웃라이어(Outlier)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(아웃라이어의 개념 · 아웃라이어와 노이즈(Noise)의 차이점 · 아웃라이어의 3가지 유형인 전역, 맥락, 군집)을 필수 키워드(Outlier, Noise, 데이터, 분석)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 3교시 #4 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(153,136,3,5,1,'절차/설계구현형','혼동행렬(Confusion Matrix) 결과를 참고하여 다음을 계산하고 설명하시오.','["결과: True Positive(TP)=100, False Positive(FP)=5, False Negative(FN)=7, True Negative(TN)=9", "(단, 계산 결과는 %로 표시하고 소수점은 버린다.)", "가. 혼동행렬을 사용한 모델의 성능 평가 원리", "나. 정확도, 정밀도, 재현율 계산 결과와 해석", "다. F1-score 계산 결과와 해석"]','["1. 리드문: 혼동행렬(Confusion Matrix) 결과를 참고하여 다음을 계산하고의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 혼동행렬(Confusion Matrix) 결과를 참고하여 다음을 계산하고 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 결과: True Positive(TP)=100, False Posit 및 (단, 계산 결과는 %로 표시하고 소수점은 버린다.) 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Confusion Matrix, True Positive, TP, False Positive, FP, False Negative, FN, True Negative','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["결과: True Positive(TP)=100, False Positive(FP)=5, False Negative(FN)=7, True", "True Positive 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["(단, 계산 결과는 %로 표시하고 소수점은 버린다.)", "계산 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["가. 혼동행렬을 사용한 모델의 성능 평가 원리", "혼동행렬 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 정확도, 정밀도, 재현율 계산 결과와 해석", "정확 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 3교시 5번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''혼동행렬(Confusion Matrix) 결과를 참고하여 다음을 계산하고''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(결과: True Positive(TP)=100, False Positive(FP)=5, False Negative(FN)=7, True Negative(TN)=9 · (단, 계산 결과는 %로 표시하고 소수점은 버린다.) · 혼동행렬을 사용한 모델의 성능 평가 원리)을 필수 키워드(Confusion Matrix, True Positive, TP, False Positive)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 3교시 #5 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(154,136,3,6,6,'법제도/거버넌스형','메모리 관리 기법 중 동적 메모리 할당과 관련하여 다음을 설명하시오.','["가. 동적 메모리 할당의 필요성", "나. 메모리 누수(Memory Leak)로 인한 문제", "다. 프로그래밍 언어(Java, Python 등)에서 지원하는 메모리 누수 해결방안"]','["1. 리드문: 메모리 관리 기법 중 동적 메모리 할당의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 메모리 관리 기법 중 동적 메모리 할당 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 동적 메모리 할당의 필요성 및 메모리 누수(Memory Leak)로 인한 문제 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','Memory Leak, Java, Python, 메모리, 관리, 동적, 할당, 누수','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 동적 메모리 할당의 필요성", "동적 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 메모리 누수(Memory Leak)로 인한 문제", "Memory Leak 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 프로그래밍 언어(Java, Python 등)에서 지원하는 메모리 누수 해결방안", "Java 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 3교시 6번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''메모리 관리 기법 중 동적 메모리 할당''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(동적 메모리 할당의 필요성 · 메모리 누수(Memory Leak)로 인한 문제 · 프로그래밍 언어(Java, Python 등)에서 지원하는 메모리 누수 해결방안)을 필수 키워드(Memory Leak, Java, Python, 메모리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 3교시 #6 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(155,136,4,1,8,'법제도/거버넌스형','국내 인공지능(AI) 윤리기준과 생성형 AI에 대하여 다음을 설명하시오.','["가. 3대 기본원칙과 10대 핵심요건(과기정통부 인공지능 윤리기준)", "나. 인공지능 윤리 관점에서 생성형 AI의 역기능 요소"]','["1. 리드문: 국내 인공지능(AI) 윤리기준과 생성형 AI의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 국내 인공지능(AI) 윤리기준과 생성형 AI 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 3대 기본원칙과 10대 핵심요건(과기정통부 인공지능 윤리기준) 및 인공지능 윤리 관점에서 생성형 AI의 역기능 요소 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','AI, 국내, 인공지능, 윤리기준, 생성형, 기본원칙, 핵심요건, 과기정통부','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 3대 기본원칙과 10대 핵심요건(과기정통부 인공지능 윤리기준)", "기본원칙 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 인공지능 윤리 관점에서 생성형 AI의 역기능 요소", "AI 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 4교시 1번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''국내 인공지능(AI) 윤리기준과 생성형 AI''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(3대 기본원칙과 10대 핵심요건(과기정통부 인공지능 윤리기준) · 인공지능 윤리 관점에서 생성형 AI의 역기능 요소)을 필수 키워드(AI, 국내, 인공지능, 윤리기준)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 4교시 #1 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(156,136,4,2,6,'법제도/거버넌스형','프로세스간 통신을위해사용되는IPC(InterProcessCommunication)에 대하여다음을 설명하시오.','["가. IPC의 개념과 목적", "나. IPC 주요기법 3가지", "다. 공유 자원의 충돌이나 일관성 문제를 해결하기 위한 동기화 기법"]','["1. 리드문: 프로세스간 통신을위해사용되는IPC(InterProcessCommunication)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 프로세스간 통신을위해사용되는IPC(InterProcessCommunication) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: IPC의 개념과 목적 및 IPC 주요기법 3가지 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','IPC, InterProcessCommunication, 프로세스간, 통신을위해사용되, 대하여다음, 주요기법, 공유, 자원','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. IPC의 개념과 목적", "IPC 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. IPC 주요기법 3가지", "IPC 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 공유 자원의 충돌이나 일관성 문제를 해결하기 위한 동기화 기법", "공유 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 4교시 2번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''프로세스간 통신을위해사용되는IPC(InterProcessCommunication)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(IPC의 개념과 목적 · IPC 주요기법 3가지 · 공유 자원의 충돌이나 일관성 문제를 해결하기 위한 동기화 기법)을 필수 키워드(IPC, InterProcessCommunication, 프로세스간, 통신을위해사용되)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 4교시 #2 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(157,136,4,3,8,'법제도/거버넌스형','대규모 중요 소프트웨어 사업 평가의 전문성을 높이고 수요기관의 전문성을 보완해 공정한 경쟁을 유도하기 위하여 ''조달청 협상에 의한 계약 제안서평가 세부기준''이 2024년9월개정·시행되었다. 이와 관련하여 다음을 설명하시오.','["가. 계약 제안서평가 세부기준 개정 주요 내용", "나. 대형소프트웨어 사업 전문평가제도"]','["1. 리드문: 대규모 중요 소프트웨어 사업 평가의 전문성을 높이고 수요기관의 전문성을 보완해 공정한 경쟁을 유도하기 위하여 ''조달청 협상에 의한 계약 제안서평가 세부기준''이 2024년9월개정·시행되었다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 대규모 중요 소프트웨어 사업 평가의 전문성을 높이고 수요기관의 전문성을 보완해 공정한 경쟁을 유도하기 위하여 ''조달청 협상에 의한 계약 제안서평가 세부기준''이 2024년9월개정·시행되었다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 계약 제안서평가 세부기준 개정 주요 내용 및 대형소프트웨어 사업 전문평가제도 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','대규모, 중요, 소프트웨어, 사업, 평가, 전문성, 높이고, 수요기관','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 계약 제안서평가 세부기준 개정 주요 내용", "계약 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 대형소프트웨어 사업 전문평가제도", "대형소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 4교시 3번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''대규모 중요 소프트웨어 사업 평가의 전문성을 높이고 수요기관의 전문성을 보완해 공정한 경쟁을 유도하기 위하여 ''조달청 협상에 의한 계약 제안서평가 세부기준''이 2024년9월개정·시행되었다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(계약 제안서평가 세부기준 개정 주요 내용 · 대형소프트웨어 사업 전문평가제도)을 필수 키워드(대규모, 중요, 소프트웨어, 사업)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 4교시 #3 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(158,136,4,4,3,'원인분석/대응전략형','공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처를 설명하시오.','["1. 공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: 공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Supply Chain Security, Zero Trust, 공급망, 보안, 설명하고, 제로트러스트, 아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제136회 4교시 4번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(공급망 보안(Supply Chain Security)을 설명하고, 제로트러스트(Zero Trust) 기반 공급망 보안 아키텍처의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(Supply Chain Security, Zero Trust, 공급망, 보안)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 4교시 #4 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(159,136,4,5,3,'원인분석/대응전략형','대형언어모델(LLM, LargeLanguageModel)의활용이급격히증가함에따라그와관련된 보안위협이새롭게대두되고있다.OWASP에서는2025년버전의LLM애플리케이션을 위한 Top 10 보안 위협 목록(OWASP LLM, OWASP Top 10 for LLM Application 2025)을발표하여LLM기반시스템의안전한개발과운영을위한 기준을제시하고있다. 이와 관련하여 다음을 설명하시오.','["가. OWASP LLM이 제시된배경과 주요 특징", "나. OWASP LLM에서 제시된 주요 보안 위협", "다. 기업이LLM애플리케이션을설계, 운영할때OWASPLLM을활용한보안대응방안"]','["1. 리드문: 대형언어모델(LLM, LargeLanguageModel)의활용이급격히증가함에따라그와관련된 보안위협이새롭게대두되고있다.OWASP에서는2025년버전의LLM애플리케이션을 위한 Top 10 보안 위협 목록(OWASP LLM, OWASP Top 10 for LLM Application 2025)을발표하여LLM기반시스템의안전한개발과운영을위한 기준을제시하고있다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 대형언어모델(LLM, LargeLanguageModel)의활용이급격히증가함에따라그와관련된 보안위협이새롭게대두되고있다.OWASP에서는2025년버전의LLM애플리케이션을 위한 Top 10 보안 위협 목록(OWASP LLM, OWASP Top 10 for LLM Application 2025)을발표하여LLM기반시스템의안전한개발과운영을위한 기준을제시하고있다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: OWASP LLM이 제시된배경과 주요 특징 및 OWASP LLM에서 제시된 주요 보안 위협 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','LLM, LargeLanguageModel, OWASP, Top 10, OWASP LLM, OWASP Top 10 for LLM Application 2025, OWASPLLM, 대형언어모델','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. OWASP LLM이 제시된배경과 주요 특징", "OWASP LLM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. OWASP LLM에서 제시된 주요 보안 위협", "OWASP LLM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 기업이LLM애플리케이션을설계, 운영할때OWASPLLM을활용한보안대응방안", "LLM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 4교시 5번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''대형언어모델(LLM, LargeLanguageModel)의활용이급격히증가함에따라그와관련된 보안위협이새롭게대두되고있다.OWASP에서는2025년버전의LLM애플리케이션을 위한 Top 10 보안 위협 목록(OWASP LLM, OWASP Top 10 for LLM Application 2025)을발표하여LLM기반시스템의안전한개발과운영을위한 기준을제시하고있다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(OWASP LLM이 제시된배경과 주요 특징 · OWASP LLM에서 제시된 주요 보안 위협 · 기업이LLM애플리케이션을설계, 운영할때OWASPLLM을활용한보안대응방안)을 필수 키워드(LLM, LargeLanguageModel, OWASP, Top 10)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 4교시 #5 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(160,136,4,6,2,'원인분석/대응전략형','소프트웨어 품질 속성 중 보안 품질에 대하여 다음을 설명하시오.','["가. 소프트웨어 보안 품질의 정의와 중요성", "나. 보안 품질 확보를 위한 자동화 기술과 도구", "다. 소프트웨어 라이프사이클 관점에서 보안 자동화 구현방안", "라. 기대 효과와 시사점"]','["1. 리드문: 소프트웨어 품질 속성 중 보안 품질의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 품질 속성 중 보안 품질 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 보안 품질의 정의와 중요성 및 보안 품질 확보를 위한 자동화 기술과 도구 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','소프트웨어, 품질, 속성, 보안, 확보, 자동화, 기술, 도구','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 소프트웨어 보안 품질의 정의와 중요성", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 보안 품질 확보를 위한 자동화 기술과 도구", "보안 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 소프트웨어 라이프사이클 관점에서 보안 자동화 구현방안", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 기대 효과와 시사점", "기대 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제136회 4교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 품질 속성 중 보안 품질''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 보안 품질의 정의와 중요성 · 보안 품질 확보를 위한 자동화 기술과 도구 · 소프트웨어 라이프사이클 관점에서 보안 자동화 구현방안)을 필수 키워드(소프트웨어, 품질, 속성, 보안)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제136회 4교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(161,135,1,1,1,'비교/모델평가형','분류 모델 성능 평가를 위한 PR 곡선(Precision-Recall Curve)과 ROC 곡선 비교','["1. 혼동 행렬(Confusion Matrix) 기반 정밀도, 재현율, 민감도, 특이도 정의", "2. 클래스 불균형(Class Imbalance) 데이터셋에서 PR 곡선과 ROC 곡선의 특성 비교"]','["1. 리드문: 이진 분류기의 임계값(Threshold) 변화에 따른 성능 평가 곡선", "2. 혼동 행렬(TP, FP, FN, TN) 및 PR Curve vs ROC Curve(AUC) 그래프 구조도", "3. PR 곡선(Precision-Recall) vs ROC 곡선(TPR-FPR) 비교표", "4. 신용카드 사기 탐지(FDS)·희귀 질환 진단 등 극단적 불균형 데이터 평가 기준"]','Confusion Matrix, Precision(정밀도), Recall(재현율=TPR), FPR(1-특이도), AUC, 클래스 불균형(Class Imbalance)','{"headers": ["비교 항목", "ROC 곡선 (Receiver Operating Characteristic)", "PR 곡선 (Precision-Recall Curve)"], "rows": [["X축 / Y축 지표", "X축: FPR = FP / (FP + TN), Y축: TPR(Recall) = TP / (TP + FN)", "X축: Recall = TP / (TP + FN), Y축: Precision = TP / (TP + FP)"], ["TN(진음성) 포함 여부", "FPR 계산에 TN(정상 데이터를 정상으로 분류한 수)이 분모에 포함됨", "TN을 전혀 사용하지 않고 양성(Positive) 예측과 실제 양성만 집중 평가"], ["불균형 데이터 적합성", "정상(TN)이 압도적으로 많으면 FPR이 항상 작게 나와 성능이 과대평가됨", "소수 클래스(이상거래, 불량, 암 환자) 탐지 성능을 왜곡 없이 민감하게 반영"]]}','ROC 곡선은 임계값 변화에 따른 FPR(위양성률) 대비 TPR(재현율)을 나타내어 전반적인 분류기 판별력을 평가하며, PR 곡선은 Recall(재현율) 대비 Precision(정밀도)을 나타낸다. 이상거래 탐지처럼 음성(TN) 샘플이 압도적으로 많은 클래스 불균형 데이터셋에서는 ROC-AUC가 낙관적으로 왜곡되므로 TN을 배제하는 PR-AUC(Average Precision)를 사용하는 것이 타당하다.','머신러닝 모델 평가 지표 대표 기출','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(162,135,1,2,1,'개념/정의형','Multimodal LLM(Large Language Model)','["1. Multimodal LLM(Large Language Model)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: Multimodal LLM(Large Language Model)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: Multimodal LLM(Large Language Model) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: Multimodal LLM(Large Language Model) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Multimodal LLM, Large Language Model, 아키텍처, 성능지표, 학습·추론 최적화, 신뢰성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "Multimodal LLM(Large Language Model)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "Multimodal LLM(Large Language Model)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "Multimodal LLM(Large Language Model)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "Multimodal LLM(Large Language Model) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 1교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''Multimodal LLM(Large Language Model)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(Multimodal LLM(Large Language Model)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Multimodal LLM, Large Language Model, 아키텍처, 성능지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 1교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(163,135,1,3,2,'개념/요구사항형','소프트웨어 공학에서 요구사항 추적표(RTM, Requirements Traceability Matrix)의 양방향 추적성과 활용','["1. 정방향 추적(요구사항 → 설계 → 코드 → 테스트)과 역방향 추적(산출물 → 요구사항: Gold Plating 방지) 구조", "2. 범위 누락 방지, 변경 영향도 분석 및 감리/검수 단계에서의 RTM 핵심 검증 역할"]','["1. 리드문: 핵심 개념 정의 및 출제 배경", "2. 아키텍처 및 동작 메커니즘 개념도", "3. 핵심 요소 및 대안 기술 비교표", "4. 실무 적용 고려사항 및 기술사적 제언"]','소프트웨어 공학에서 요구사항 추적표, 메커니즘, 비교분석, 트레이드오프, 실무거버넌스','{"headers": ["비교/구분 항목", "핵심 원리 및 구성요소", "실무 적용 및 검증 기준"], "rows": [["1. 정방향 추적(요구사항 → 설계 → 코드 → 테스트)과 역방향 추적(산출물 → 요구사항: Gold Plating 방지) 구조", "표준 메커니즘 및 핵심 구조 정의", "정합성·성능·보안 요구사항 검증"], ["2. 범위 누락 방지, 변경 영향도 분석 및 감리/검수 단계에서의 RTM 핵심 검증 역할", "대안 기법과의 정량·정성적 트레이드오프 비교", "엔터프라이즈 운영 거버넌스 확립"]]}','소프트웨어 공학에서 요구사항 추적표(RTM, Requirements Traceability Matrix)의 양방향 추적성과 활용 토픽은 정보관리기술사 핵심 기출 문항으로, (1) 정의와 필요성을 리드문으로 선언하고, (2) 메커니즘 구조도를 도식화한 뒤, (3) 1. 정방향 추적(요구사항 → 설계 → 코드 → 테스트)과 역방향 추적(산출물 → 요구사항: Gold Plating 방지) 구조 및 2. 범위 누락 방지, 변경 영향도 분석 및 감리/검수 단계에서의 RTM 핵심 검증 역할를 대조표로 구조화하고, (4) 실무 적용 시 한계점과 극복 제언을 제시해야 한다.','제135회 주요 기출 및 도메인 순환 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(164,135,1,4,5,'개념/네트워크자동화형','의도 기반 네트워킹 IBN(Intent-Based Networking)의 4단계(변환-활성화-보증-자가치유) 아키텍처와 SDN 비교','["1. 관리자의 비즈니스 의도(What)를 선언하면 AI·자동화 엔진이 네트워크 설정(How)으로 변환·검증하는 IBN 정의", "2. 명령형 제어 중심의 SDN에서 폐루프 보증(Closed-loop Assurance)을 결합한 IBN으로의 진화"]','["1. 리드문: 핵심 개념 정의 및 출제 배경", "2. 아키텍처 및 동작 메커니즘 개념도", "3. 핵심 요소 및 대안 기술 비교표", "4. 실무 적용 고려사항 및 기술사적 제언"]','의도 기반 네트워킹 IBN, 메커니즘, 비교분석, 트레이드오프, 실무거버넌스','{"headers": ["비교/구분 항목", "핵심 원리 및 구성요소", "실무 적용 및 검증 기준"], "rows": [["1. 관리자의 비즈니스 의도(What)를 선언하면 AI·자동화 엔진이 네트워크 설정(How)으로 변환·검증하는 IBN 정의", "표준 메커니즘 및 핵심 구조 정의", "정합성·성능·보안 요구사항 검증"], ["2. 명령형 제어 중심의 SDN에서 폐루프 보증(Closed-loop Assurance)을 결합한 IBN으로의 진화", "대안 기법과의 정량·정성적 트레이드오프 비교", "엔터프라이즈 운영 거버넌스 확립"]]}','의도 기반 네트워킹 IBN(Intent-Based Networking)의 4단계(변환-활성화-보증-자가치유) 아키텍처와 SDN 비교 토픽은 정보관리기술사 핵심 기출 문항으로, (1) 정의와 필요성을 리드문으로 선언하고, (2) 메커니즘 구조도를 도식화한 뒤, (3) 1. 관리자의 비즈니스 의도(What)를 선언하면 AI·자동화 엔진이 네트워크 설정(How)으로 변환·검증하는 IBN 정의 및 2. 명령형 제어 중심의 SDN에서 폐루프 보증(Closed-loop Assurance)을 결합한 IBN으로의 진화를 대조표로 구조화하고, (4) 실무 적용 시 한계점과 극복 제언을 제시해야 한다.','제135회 주요 기출 및 도메인 순환 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(165,135,1,5,3,'비교/보안관제형','SIEM(Security Information and Event Management)과 SOAR(Security Orchestration, Automation and Response) 비교','["1. 차세대 보안관제센터(SOC)에서 SIEM과 SOAR의 역할", "2. 빅데이터 상관분석 중심의 SIEM과 플레이북 자동 대응 중심의 SOAR 비교"]','["1. 리드문: 지능화되는 사이버 위협과 관제 인력 피로도(Alert Fatigue) 해소를 위한 SIEM & SOAR", "2. 로그 수집·상관분석(SIEM) → 플레이북 기반 오케스트레이션·자동 차단(SOAR) 연계 구조도", "3. ESM vs SIEM vs SOAR 비교표 (핵심 기능, 분석 대상, 대응 방식, MTTR 단축)", "4. XDR 및 AI SOC(자율형 보안관제)로의 진화 방향"]','SOC(보안관제센터), 빅데이터 상관분석, Alert Fatigue(경보 피로도), Playbook(표준대응절차), Orchestration, MTTR(평균대응시간) 단축','{"headers": ["비교 항목", "SIEM (보안 정보 및 이벤트 관리)", "SOAR (보안 오케스트레이션·자동화 및 대응)"], "rows": [["핵심 목적", "이기종 보안장비·시스템 로그 통합 수집 및 상관분석을 통한 위협 탐지", "탐지된 위협에 대해 표준 플레이북(Playbook)에 따라 분석·차단·대응을 자동화"], ["주요 기능", "빅데이터 인덱싱, 실시간/장기 상관분석 규칙, 위협 인텔리전스(TI) 연동 경보", "외부 방화벽/EDR API 연동 오케스트레이션, 반복 티켓 자동 처리, 케이스 관리"], ["한계 및 상호보완", "경보만 발생시키고 실제 차단은 분석가 수동 개입 필요(Alert Fatigue)", "SIEM의 탐지 이벤트를 입력받아 MTTR(평균 대응 시간)을 수 시간에서 수 초로 단축"]]}','SIEM은 기업 내 방화벽, IDS/IPS, 서버 등에서 발생하는 대규모 보안 로그를 수집하고 빅데이터 상관분석을 통해 이상 징후를 탐지·경보하는 시스템이며, SOAR는 SIEM 등에서 발생한 수많은 보안 경보에 대해 사전 정의된 플레이북(Playbook)을 기반으로 위협 검증과 방화벽 차단 등 사고 대응 과정을 오케스트레이션·자동화하여 평균 대응 시간(MTTR)을 획기적으로 단축하는 솔루션이다.','보안관제 아키텍처 핵심 비교 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(166,135,1,6,1,'개념/정의형','실루엣 계수(Silhouette Coefficient)','["1. 실루엣 계수(Silhouette Coefficient)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 실루엣 계수(Silhouette Coefficient)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 실루엣 계수(Silhouette Coefficient) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 실루엣 계수(Silhouette Coefficient) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Silhouette Coefficient, 실루엣, 계수, 아키텍처, 성능지표, 학습·추론 최적화, 신뢰성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "실루엣 계수(Silhouette Coefficient)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "실루엣 계수(Silhouette Coefficient)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "실루엣 계수(Silhouette Coefficient)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "실루엣 계수(Silhouette Coefficient) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 1교시 6번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''실루엣 계수(Silhouette Coefficient)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(실루엣 계수(Silhouette Coefficient)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Silhouette Coefficient, 실루엣, 계수, 아키텍처)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 1교시 #6 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(167,135,1,7,8,'개념/정의형','개인정보 안심구역','["1. 개인정보 안심구역의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 개인정보 안심구역의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개인정보 안심구역 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개인정보 안심구역 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','개인정보, 안심구역, 법적 근거, 컴플라이언스, 관리체계, 공공정책','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "개인정보 안심구역의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "개인정보 안심구역의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "개인정보 안심구역의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "개인정보 안심구역 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 1교시 7번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''개인정보 안심구역''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개인정보 안심구역의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(개인정보, 안심구역, 법적 근거, 컴플라이언스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 1교시 #7 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(168,135,1,8,1,'개념/정의형','불편추정량(Unbiased Estimator)','["1. 불편추정량(Unbiased Estimator)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 불편추정량(Unbiased Estimator)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 불편추정량(Unbiased Estimator) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 불편추정량(Unbiased Estimator) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Unbiased Estimator, 불편추정량, 아키텍처, 성능지표, 학습·추론 최적화, 신뢰성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "불편추정량(Unbiased Estimator)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "불편추정량(Unbiased Estimator)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "불편추정량(Unbiased Estimator)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "불편추정량(Unbiased Estimator) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 1교시 8번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''불편추정량(Unbiased Estimator)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(불편추정량(Unbiased Estimator)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Unbiased Estimator, 불편추정량, 아키텍처, 성능지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 1교시 #8 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
