INSERT INTO "questions" VALUES(173,135,1,13,1,'개념/정의형','AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성','["1. AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','AGI, ArtificialGeneralIntelligence, ANI, ArtificialNarrowIntelligence, 의필요성, 아키텍처, 성능지표','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 1교시 13번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(AGI(ArtificialGeneralIntelligence) 측면에서ANI(ArtificialNarrowIntelligence)의필요성의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(AGI, ArtificialGeneralIntelligence, ANI, ArtificialNarrowIntelligence)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 1교시 #13 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(174,135,2,1,4,'절차/데이터모델링형','물리 데이터 모델링에서 반정규화(De-normalization)의 개념, 적용 절차 및 기법(테이블/컬럼/관계) 설명','["가. 반정규화의 정의와 비정규화(Un-normalized)와의 차이점", "나. 반정규화 적용 전 선행 검토 사항(뷰, 클러스터링, 인덱스, 파티셔닝) 및 수행 절차", "다. 대상별 반정규화 기법(테이블 병합/분할/추가, 중복 컬럼 추가, 중복 관계 추가)과 데이터 무결성 보장 방안"]','["1. 리드문: 정규화 완료 후 조인 성능 극대화를 위한 의도적 설계 기법 반정규화", "2. 반정규화 4단계(대상조사 → 다른 방법 유도 검토 → 반정규화 적용 → 무결성 통제) 절차도", "3. 테이블·컬럼·관계 반정규화 세부 기법 분류표", "4. 트리거·배치·애플리케이션 트랜잭션 기반 중복 데이터 정합성 유지 방안"]','De-normalization, 선행 대안 검토(인덱스·파티셔닝·클러스터링), 테이블 병합/분할(수직·수평), 파생/중복 컬럼, 이력 테이블, 데이터 무결성','{"headers": ["반정규화 대상", "세부 적용 기법", "적용 시나리오 및 주의사항"], "rows": [["테이블 반정규화", "1:1 / 1:M 테이블 병합, 수평/수직 분할, 통계·이력·중복 테이블 추가", "대량 조인 발생 시 병합, 특정 컬럼 집중 조회 시 수직 분할"], ["컬럼 반정규화", "중복 컬럼 추가, 파생 컬럼(계산값) 추가, 이력 테이블 기능 컬럼(최신여부) 추가", "주문금액 합계 등 실시간 연산 부하 감소, 단 갱신 시 동기화 필수"], ["관계 반정규화", "중복 관계(Direct Relationship) 추가", "A→B→C 다단계 조인을 A→C 직접 외래키 관계 추가로 경로 단축 (데이터 중복 없이 성능 개선)"]]}','반정규화(De-normalization)는 정규화를 충실히 수행한 데이터 모델에서 디스크 I/O가 많거나 다중 조인으로 인해 조회 성능이 저하될 때, 인덱스 튜닝·파티셔닝·클러스터링 등 다른 대안을 먼저 검토한 뒤 제한적으로 데이터 중복이나 구조 변경을 허용하는 물리 모델링 기법이다. 중복으로 인한 정합성 훼손을 막기 위해 트리거(Trigger)나 애플리케이션 트랜잭션 동기화 설계가 반드시 수반되어야 한다.','DB 모델링 서술형 정통 기출','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(175,135,2,2,2,'개념/정의형','CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여 설명하시오.','["1. CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','CI/CD, Continuous Integration/Continuous Del, ivery or Continuous Deployment, DevSecOps, 파이프라인, 적용방안, 품질속성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 2교시 2번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(CI/CD(Continuous Integration/Continuous Delivery or Continuous Deployment) 파이프라인에서 DevSecOps 적용방안에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(CI/CD, Continuous Integration/Continuous Del, ivery or Continuous Deployment, DevSecOps)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 2교시 #2 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(176,135,2,3,1,'개념/정의형','회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여 설명하시오.','["1. 회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Homoscedasticity, Multicollinearity, 회귀모형, 오차, 등분산성, 다중공선성, 아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 2교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(회귀모형에서 오차의 등분산성(Homoscedasticity)과 다중공선성(Multicollinearity)에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Homoscedasticity, Multicollinearity, 회귀모형, 오차)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 2교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(177,135,2,4,2,'개념/정의형','서비스 특징 (6G 이동통신기술에 대하여 다음을 설명하시오)','["가. 서비스 특징", "나. 성능 요구사항", "다. 주파수 동향"]','["1. 리드문: 서비스 특징 (6G 이동통신기술에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 서비스 특징 (6G 이동통신기술에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 서비스 특징 및 성능 요구사항 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','이동통신기술, 서비스, 성능, 요구사항, 주파수, 품질속성, 유지보수성','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 서비스 특징", "서비스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 성능 요구사항", "성능 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 주파수 동향", "주파수 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제135회 2교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''서비스 특징 (6G 이동통신기술에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(서비스 특징 · 성능 요구사항 · 주파수 동향)을 필수 키워드(이동통신기술, 서비스, 성능, 요구사항)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 2교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(178,135,2,5,1,'절차/설계구현형','최근 많은 공공기관에서 거대 언어 모델(Large Language Model)의 적용을 준비하고 있다.다음에 대하여 설명하시오.','["가. 거대 언어 모델 적용을 위한 5가지 고려사항", "나. 현재 구현 가능한 5가지 거대 언어 모델 아키텍처"]','["1. 리드문: 최근 많은 공공기관에서 거대 언어 모델(Large Language Model)의 적용을 준비하고 있다.다음에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 최근 많은 공공기관에서 거대 언어 모델(Large Language Model)의 적용을 준비하고 있다.다음에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 거대 언어 모델 적용을 위한 5가지 고려사항 및 현재 구현 가능한 5가지 거대 언어 모델 아키텍처 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Large Language Model, 공공기관, 거대, 언어, 모델, 준비하고, 현재, 구현','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 거대 언어 모델 적용을 위한 5가지 고려사항", "거대 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 현재 구현 가능한 5가지 거대 언어 모델 아키텍처", "현재 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제135회 2교시 5번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''최근 많은 공공기관에서 거대 언어 모델(Large Language Model)의 적용을 준비하고 있다.다음에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(거대 언어 모델 적용을 위한 5가지 고려사항 · 현재 구현 가능한 5가지 거대 언어 모델 아키텍처)을 필수 키워드(Large Language Model, 공공기관, 거대, 언어)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 2교시 #5 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(179,135,2,6,8,'개념/정의형','개념 및 특징 (AI 디지털교과서에 대하여 다음을 설명하시오)','["가. 개념 및 특징", "나. 플랫폼 구조", "다. 기능 및 핵심 서비스"]','["1. 리드문: 개념 및 특징 (AI 디지털교과서에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개념 및 특징 (AI 디지털교과서에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개념 및 특징 및 플랫폼 구조 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','AI, 디지털교과서, 플랫폼, 서비스, 법적 근거, 컴플라이언스, 관리체계','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 개념 및 특징", "법적 근거 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 플랫폼 구조", "플랫폼 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 기능 및 핵심 서비스", "서비스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제135회 2교시 6번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''개념 및 특징 (AI 디지털교과서에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개념 및 특징 · 플랫폼 구조 · 기능 및 핵심 서비스)을 필수 키워드(AI, 디지털교과서, 플랫폼, 서비스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 2교시 #6 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(180,135,3,1,7,'비교/대조분석형','IT 프로젝트 관리 (IT 프로젝트 관리에 대하여 다음을 설명하시오)','["가. IT 프로젝트 관리의 개념", "나. IT 프로젝트 관리 프로세스", "다. IT 프로젝트 관리, 프로그램 관리, 포트폴리오 관리의 비교"]','["1. 리드문: IT 프로젝트 관리 (IT 프로젝트 관리에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: IT 프로젝트 관리 (IT 프로젝트 관리에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: IT 프로젝트 관리의 개념 및 IT 프로젝트 관리 프로세스 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IT, 프로젝트, 관리, 프로세스, 프로그램, 포트폴리오, 거버넌스','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. IT 프로젝트 관리의 개념", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. IT 프로젝트 관리 프로세스", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. IT 프로젝트 관리, 프로그램 관리, 포트폴리오 관리의 비교", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제135회 3교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''IT 프로젝트 관리 (IT 프로젝트 관리에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(IT 프로젝트 관리의 개념 · IT 프로젝트 관리 프로세스 · IT 프로젝트 관리, 프로그램 관리, 포트폴리오 관리의 비교)을 필수 키워드(IT, 프로젝트, 관리, 프로세스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 3교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
INSERT INTO "questions" VALUES(181,135,3,2,1,'개념/정의형','프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여 설명하시오.','["1. 프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Prompt Engineering, 프롬프트, 엔지니어링, 기술, 아키텍처, 성능지표, 학습·추론 최적화','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제135회 3교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(프롬프트 엔지니어링(Prompt Engineering)의 기술 요소와 활용 방안에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Prompt Engineering, 프롬프트, 엔지니어링, 기술)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제135회 3교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (Q-Net 공식 기출 PDF)','Q-Net 공식 기출 PDF');
