INSERT INTO "questions" VALUES(197,134,1,6,1,'법제도/거버넌스형','이미지 데이터 어노테이션(Data Annotation) 유형과 기법','["1. 이미지 데이터 어노테이션(Data Annotation) 유형과 기법의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 이미지 데이터 어노테이션(Data Annotation) 유형과 기법의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이미지 데이터 어노테이션(Data Annotation) 유형과 기법 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 이미지 데이터 어노테이션(Data Annotation) 유형과 기법 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Data Annotation, 이미지, 데이터, 어노테이션, 아키텍처, 성능지표, 학습·추론 최적화','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "이미지 데이터 어노테이션(Data Annotation) 유형과 기법의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "이미지 데이터 어노테이션(Data Annotation) 유형과 기법의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "이미지 데이터 어노테이션(Data Annotation) 유형과 기법의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "이미지 데이터 어노테이션(Data Annotation) 유형과 기법 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 1교시 6번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''이미지 데이터 어노테이션(Data Annotation) 유형과 기법''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(이미지 데이터 어노테이션(Data Annotation) 유형과 기법의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Data Annotation, 이미지, 데이터, 어노테이션)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 1교시 #6 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(198,134,1,7,4,'비교/대조분석형','정적 SQL(Static SQL)과 동적 SQL(Dynamic SQL) 비교','["1. 정적 SQL(Static SQL)과 동적 SQL(Dynamic SQL) 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 정적 SQL(Static SQL)과 동적 SQL(Dynamic SQL) 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정적 SQL(Static SQL)과 동적 SQL(Dynamic SQL) 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정적 SQL(Static SQL)과 동적 SQL(Dynamic SQL) 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','SQL, Static SQL, Dynamic SQL, 정적, 동적, 데이터 정합성, 성능·확장성','{"headers": ["비교 항목", "정적 SQL(Static SQL)", "동적 SQL(Dynamic SQL)"], "rows": [["핵심 개념·목적", "정적 SQL(Static SQL)의 고유 목적 및 적용 영역 정의", "동적 SQL(Dynamic SQL)의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제134회 1교시 7번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''정적 SQL(Static SQL)과 동적 SQL(Dynamic SQL) 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정적 SQL(Static SQL)과 동적 SQL(Dynamic SQL) 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(SQL, Static SQL, Dynamic SQL, 정적)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 1교시 #7 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(199,134,1,8,5,'비교/대조분석형','RIP(Routing Information Protocol)과 OSPF(Open Shortest Path First) 비교','["1. RIP(Routing Information Protocol)과 OSPF(Open Shortest Path First) 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: RIP(Routing Information Protocol)과 OSPF(Open Shortest Path First) 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: RIP(Routing Information Protocol)과 OSPF(Open Shortest Path First) 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: RIP(Routing Information Protocol)과 OSPF(Open Shortest Path First) 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','RIP, Routing Information Protocol, OSPF, Open Shortest Path First, 프로토콜 스택, 대역폭·지연시간, 고가용성','{"headers": ["비교 항목", "RIP(Routing Information Protocol)", "OSPF(Open Shortest Path First)"], "rows": [["핵심 개념·목적", "RIP(Routing Information 의 고유 목적 및 적용 영역 정의", "OSPF(Open Shortest Path 의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제134회 1교시 8번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''RIP(Routing Information Protocol)과 OSPF(Open Shortest Path First) 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(RIP(Routing Information Protocol)과 OSPF(Open Shortest Path First) 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(RIP, Routing Information Protocol, OSPF, Open Shortest Path First)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 1교시 #8 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(200,134,1,9,6,'개념/정의형','인터미턴트 컴퓨팅(Intermittent Computing)','["1. 인터미턴트 컴퓨팅(Intermittent Computing)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 인터미턴트 컴퓨팅(Intermittent Computing)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인터미턴트 컴퓨팅(Intermittent Computing) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인터미턴트 컴퓨팅(Intermittent Computing) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','Intermittent Computing, 인터미턴트, 컴퓨팅, 자원스케줄링, 메모리 계층, 동기화·일관성, 성능병목','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "인터미턴트 컴퓨팅(Intermittent Computing)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "인터미턴트 컴퓨팅(Intermittent Computing)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "인터미턴트 컴퓨팅(Intermittent Computing)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "인터미턴트 컴퓨팅(Intermittent Computing) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 1교시 9번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''인터미턴트 컴퓨팅(Intermittent Computing)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인터미턴트 컴퓨팅(Intermittent Computing)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Intermittent Computing, 인터미턴트, 컴퓨팅, 자원스케줄링)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 1교시 #9 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(201,134,1,10,5,'개념/정의형','스토리지 가상화(Storage Virtualization) 유형별 특징','["1. 스토리지 가상화(Storage Virtualization) 유형별 특징의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 스토리지 가상화(Storage Virtualization) 유형별 특징의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 스토리지 가상화(Storage Virtualization) 유형별 특징 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 스토리지 가상화(Storage Virtualization) 유형별 특징 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Storage Virtualization, 스토리지, 가상화, 유형별, 프로토콜 스택, 대역폭·지연시간, 고가용성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "스토리지 가상화(Storage Virtualization) 유형별 특징의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "스토리지 가상화(Storage Virtualization) 유형별 특징의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "스토리지 가상화(Storage Virtualization) 유형별 특징의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "스토리지 가상화(Storage Virtualization) 유형별 특징 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 1교시 10번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''스토리지 가상화(Storage Virtualization) 유형별 특징''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(스토리지 가상화(Storage Virtualization) 유형별 특징의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Storage Virtualization, 스토리지, 가상화, 유형별)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 1교시 #10 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
