INSERT INTO "questions" VALUES(203,134,1,12,6,'개념/정의형','고대역 초고속 메모리(High Bandwidth Memory)','["1. 고대역 초고속 메모리(High Bandwidth Memory)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 고대역 초고속 메모리(High Bandwidth Memory)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 고대역 초고속 메모리(High Bandwidth Memory) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 고대역 초고속 메모리(High Bandwidth Memory) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','High Bandwidth Memory, 고대역, 초고속, 메모리, 자원스케줄링, 메모리 계층, 동기화·일관성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "고대역 초고속 메모리(High Bandwidth Memory)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "고대역 초고속 메모리(High Bandwidth Memory)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "고대역 초고속 메모리(High Bandwidth Memory)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "고대역 초고속 메모리(High Bandwidth Memory) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 1교시 12번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''고대역 초고속 메모리(High Bandwidth Memory)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(고대역 초고속 메모리(High Bandwidth Memory)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(High Bandwidth Memory, 고대역, 초고속, 메모리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 1교시 #12 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(204,134,1,13,1,'개념/정의형','RAG(Retrieval Augmented Generation)','["1. RAG(Retrieval Augmented Generation)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: RAG(Retrieval Augmented Generation)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: RAG(Retrieval Augmented Generation) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: RAG(Retrieval Augmented Generation) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','RAG, Retrieval Augmented Generation, 아키텍처, 성능지표, 학습·추론 최적화, 신뢰성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "RAG(Retrieval Augmented Generation)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "RAG(Retrieval Augmented Generation)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "RAG(Retrieval Augmented Generation)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "RAG(Retrieval Augmented Generation) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 1교시 13번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''RAG(Retrieval Augmented Generation)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(RAG(Retrieval Augmented Generation)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(RAG, Retrieval Augmented Generation, 아키텍처, 성능지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 1교시 #13 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(205,134,2,1,4,'비교/아키텍처형','전사 데이터 아키텍처로서 데이터 패브릭(Data Fabric)과 데이터 메시(Data Mesh) 비교','["가. 중앙집중형 데이터 레이크의 병목 한계", "나. 메타데이터·AI 자동화 중심의 데이터 패브릭과 도메인 주도 분산 소유권 중심의 데이터 메시 비교", "다. 조직 성숙도에 따른 하이브리드 도입 전략"]','["1. 리드문: 데이터 사일로 해소와 민첩한 데이터 활용을 위한 차세대 데이터 아키텍처", "2. 데이터 패브릭(Active Metadata + 지식그래프 중앙 오케스트레이션) vs 데이터 메시(도메인별 Data as a Product) 구조도", "3. 데이터 웨어하우스/레이크 vs 데이터 패브릭 vs 데이터 메시 비교표", "4. 기술 기반 자동화(Fabric)와 조직·거버넌스 혁신(Mesh)의 상호보완적 결합 방안"]','Data Silo, Active Metadata, 지식그래프, 데이터 가상화, Data Mesh, 도메인 주도 설계(DDD), Data as a Product, 연합 거버넌스','{"headers": ["비교 항목", "데이터 패브릭 (Data Fabric)", "데이터 메시 (Data Mesh)"], "rows": [["접근 관점", "기술·아키텍처 중심 (메타데이터 및 AI 기반 통합 자동화)", "조직·프로세스·거버넌스 중심 (도메인 팀 분산 소유권)"], ["핵심 메커니즘", "액티브 메타데이터, 지식 그래프, 데이터 가상화·카탈로그 자동화", "4대 원칙: 도메인 소유권, 데이터 제품화(Data as a Product), 셀프서비스 플랫폼, 연합 거버넌스"], ["적합한 조직", "이기종 멀티클라우드 데이터 소스가 복잡하게 얽힌 기술 중심 기업", "비즈니스 도메인이 명확히 분리되고 도메인 팀의 역량이 높은 대규모 조직"]]}','데이터 패브릭은 액티브 메타데이터와 지식 그래프, AI 자동화를 활용해 분산된 이기종 데이터 소스를 가상화·통합하는 기술 중심 아키텍처이며, 데이터 메시는 중앙 데이터 팀의 병목을 해결하기 위해 비즈니스 도메인 팀이 데이터를 제품(Data as a Product)으로 직접 소유·제공하고 연합 거버넌스로 표준을 맞추는 조직·아키텍처 패러다임이다.','데이터 아키텍처 대표 비교 논술','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(206,134,2,1,8,'법제도/거버넌스형','국가기관, 지방자치단체 및 공공기관이 안전하고 효율적으로 Saas(Software as a Service)를 이용하기 위해 공공부문 Saas 이용 가이드라인을 발표하였다. 다음에 대하여 설명하시오.','["가. 클라우드 서비스 위험 관리 원칙 및 기준", "나. 보안대책 수립 및 보안성 검토", "다. 서비스 수준 협약."]','["1. 리드문: 다음에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 다음에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 클라우드 서비스 위험 관리 원칙 및 기준 및 보안대책 수립 및 보안성 검토 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','Saas, Software as a Service, 국가기관, 지방자치단체, 공공기관, 안전하고, 효율적, 이용하기','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 클라우드 서비스 위험 관리 원칙 및 기준", "클라우드 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 보안대책 수립 및 보안성 검토", "보안대책 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 서비스 수준 협약.", "서비스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 2교시 1번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''다음에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(클라우드 서비스 위험 관리 원칙 및 기준 · 보안대책 수립 및 보안성 검토 · 서비스 수준 협약.)을 필수 키워드(Saas, Software as a Service, 국가기관, 지방자치단체)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 2교시 #1 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(207,134,2,2,2,'원인분석/대응전략형','소비자를 기만하여 이익을 편취하고자 하는 다크패턴(Dark Pattern)이 발생하고 있다. 이와 관련하여 다크패턴의 세부 유형 및 대응 방안을 설명하시오.','["1. 이와 관련하여 다크패턴의 세부 유형 및 대응 방안의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: 이와 관련하여 다크패턴의 세부 유형 및 대응 방안의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이와 관련하여 다크패턴의 세부 유형 및 대응 방안 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 이와 관련하여 다크패턴의 세부 유형 및 대응 방안 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Dark Pattern, 소비자, 기만하여, 이익, 편취하고자, 다크패턴, 발생하고, 세부','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "이와 관련하여 다크패턴의 세부 유형 및 대응 방안의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "이와 관련하여 다크패턴의 세부 유형 및 대응 방안의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "이와 관련하여 다크패턴의 세부 유형 및 대응 방안의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "이와 관련하여 다크패턴의 세부 유형 및 대응 방안 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 2교시 2번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''이와 관련하여 다크패턴의 세부 유형 및 대응 방안''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(이와 관련하여 다크패턴의 세부 유형 및 대응 방안의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(Dark Pattern, 소비자, 기만하여, 이익)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 2교시 #2 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(208,134,2,3,8,'법제도/거버넌스형','IT 거버넌스에 대하여 설명하시오','["가. IT 거버넌스의 구성요소", "나. IT 거버넌스 효과 측정 지표", "다. IT 거버넌스 효과 측정 방법론."]','["1. 리드문: IT 거버넌스에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: IT 거버넌스에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: IT 거버넌스의 구성요소 및 IT 거버넌스 효과 측정 지표 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','IT, 거버넌스, 측정, 지표, 방법론, 법적 근거, 컴플라이언스','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. IT 거버넌스의 구성요소", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. IT 거버넌스 효과 측정 지표", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. IT 거버넌스 효과 측정 방법론.", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 2교시 3번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''IT 거버넌스에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(IT 거버넌스의 구성요소 · IT 거버넌스 효과 측정 지표 · IT 거버넌스 효과 측정 방법론.)을 필수 키워드(IT, 거버넌스, 측정, 지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 2교시 #3 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(209,134,2,4,5,'실무/시나리오형','대규모 AI 서비스를 위한 데이터센터 구축 기술에 대하여 설명하시오','["가. 저지연 기술과 스케일링 확보 기술", "나. DCI(Data Center Interconnect) 기술"]','["1. 리드문: 대규모 AI 서비스를 위한 데이터센터 구축 기술에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 대규모 AI 서비스를 위한 데이터센터 구축 기술에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 저지연 기술과 스케일링 확보 기술 및 DCI(Data Center Interconnect) 기술 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','AI, DCI, Data Center Interconnect, 대규모, 서비스, 데이터센터, 기술, 저지연','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 저지연 기술과 스케일링 확보 기술", "저지연 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. DCI(Data Center Interconnect) 기술", "DCI 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 2교시 4번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''대규모 AI 서비스를 위한 데이터센터 구축 기술에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(저지연 기술과 스케일링 확보 기술 · DCI(Data Center Interconnect) 기술)을 필수 키워드(AI, DCI, Data Center Interconnect, 대규모)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 2교시 #4 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(210,134,2,5,8,'개념/정의형','ESG(Environment, Social, Governance) 경영에 대하여 설명하시오','["가. ESG 경영의 정의 및 목표", "나. ESG 경영의 주요 지표", "다. ESG 경영 목표 달성을 지원하기 위한 정보기술(IT)"]','["1. 리드문: ESG(Environment, Social, Governance) 경영에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ESG(Environment, Social, Governance) 경영에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ESG 경영의 정의 및 목표 및 ESG 경영의 주요 지표 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','ESG, Environment, Social, Governance, IT, 경영, 목표, 지표','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. ESG 경영의 정의 및 목표", "ESG 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. ESG 경영의 주요 지표", "ESG 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. ESG 경영 목표 달성을 지원하기 위한 정보기술(IT)", "ESG 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 2교시 5번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''ESG(Environment, Social, Governance) 경영에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ESG 경영의 정의 및 목표 · ESG 경영의 주요 지표 · ESG 경영 목표 달성을 지원하기 위한 정보기술(IT))을 필수 키워드(ESG, Environment, Social, Governance)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 2교시 #5 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(211,134,2,6,4,'실무/시나리오형','트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로 설명하시오','["1. 트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','Transaction Isolation Level, 트랜잭션, 격리, 수준, 중심, 데이터 정합성, 성능·확장성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 2교시 6번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(트랜잭션 격리 수준(Transaction Isolation Level) 4 가지를 사례를 중심으로의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Transaction Isolation Level, 트랜잭션, 격리, 수준)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 2교시 #6 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(212,134,3,1,2,'개념/정의형','실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여 설명하시오.','["1. 실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','실행, 중인, 애플리케이션, 배포, 전략, 테스트, 품질속성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 3교시 1번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(실행 중인 애플리케이션에 대한 배포 전략 및 테스트 전략에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(실행, 중인, 애플리케이션, 배포)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 3교시 #1 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(213,134,3,2,5,'개념/클라우드관리형','클라우드 재무관리 FinOps(Financial Operations) 프레임워크의 3단계(Inform, Optimize, Operate)와 멀티클라우드 비용 최적화 방안','["가. 가변적 클라우드 종량제 비용 급증 문제와 FinOps 문화·조직(기술·재무·비즈니스 협업)", "나. 가시성 확보(태깅/쇼백) → 단가·사용량 최적화(RI/Savings Plans, 적정사이징) → 지속적 거버넌스 운영"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','클라우드 재무관리 FinOps, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["가. 가변적 클라우드 종량제 비용 급증 문제와 FinOps 문화·조직(기술·재무·비즈니스 협업)", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["나. 가시성 확보(태깅/쇼백) → 단가·사용량 최적화(RI/Savings Plans, 적정사이징) → 지속적 거버넌스 운영", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','클라우드 재무관리 FinOps(Financial Operations) 프레임워크의 3단계(Inform, Optimize, Operate)와 멀티클라우드 비용 최적화 방안 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 가. 가변적 클라우드 종량제 비용 급증 문제와 FinOps 문화·조직(기술·재무·비즈니스 협업) 및 나. 가시성 확보(태깅/쇼백) → 단가·사용량 최적화(RI/Savings Plans, 적정사이징) → 지속적 거버넌스 운영을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제134회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(214,134,3,2,2,'법제도/거버넌스형','소프트웨어 테스트에 대하여 설명하시오.','["가. 소프트웨어 테스트 원리", "나. 블랙박스 테스트와 화이트박스 테스트", "다. 명세기반, 구조기반, 경험기반 테스트 기법"]','["1. 리드문: 소프트웨어 테스트에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 테스트에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 테스트 원리 및 블랙박스 테스트와 화이트박스 테스트 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','소프트웨어, 테스트, 블랙박스, 화이트박스, 명세기반, 구조기반, 경험기반','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 소프트웨어 테스트 원리", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 블랙박스 테스트와 화이트박스 테스트", "블랙박스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 명세기반, 구조기반, 경험기반 테스트 기법", "명세기반 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 3교시 2번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 테스트에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 테스트 원리 · 블랙박스 테스트와 화이트박스 테스트 · 명세기반, 구조기반, 경험기반 테스트 기법)을 필수 키워드(소프트웨어, 테스트, 블랙박스, 화이트박스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 3교시 #2 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(215,134,3,3,3,'원인분석/대응전략형','SBOM(Software Bill of Materials)에 대하여 설명하시오.','["가. 오픈소스 소프트웨어 취약점", "나. SBOM 기반 오픈소스 소프트웨어 관리 방안"]','["1. 리드문: SBOM(Software Bill of Materials)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: SBOM(Software Bill of Materials)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 오픈소스 소프트웨어 취약점 및 SBOM 기반 오픈소스 소프트웨어 관리 방안 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','SBOM, Software Bill of Materials, 오픈소스, 소프트웨어, 취약점, 관리, 기밀성·무결성','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 오픈소스 소프트웨어 취약점", "오픈소스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. SBOM 기반 오픈소스 소프트웨어 관리 방안", "SBOM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 3교시 3번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''SBOM(Software Bill of Materials)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(오픈소스 소프트웨어 취약점 · SBOM 기반 오픈소스 소프트웨어 관리 방안)을 필수 키워드(SBOM, Software Bill of Materials, 오픈소스, 소프트웨어)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 3교시 #3 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(216,134,3,4,2,'비교/대조분석형','알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notation 의 개념과 유형 및 유형별 연산시간의 차이를 설명하시오.','["1. 알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notation 의 개념과 유형 및 유형별 연산시간의 차이의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notation 의 개념과 유형 및 유형별 연산시간의 차이의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notation 의 개념과 유형 및 유형별 연산시간의 차이 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notation 의 개념과 유형 및 유형별 연산시간의 차이 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','O-Notation, 알고리즘, 복잡도, 설명하고, 성능, 표기하기, 유형별, 연산시간','{"headers": ["비교 항목", "알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notati", "유형 및 유형별 연산시간의"], "rows": [["핵심 개념·목적", "알고리즘의 복잡도를 설명하고 성능을 표기하기의 고유 목적 및 적용 영역 정의", "유형 및 유형별 연산시간의의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제134회 3교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notation 의 개념과 유형 및 유형별 연산시간의 차이''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(알고리즘의 복잡도를 설명하고 성능을 표기하기 위한 O-Notation 의 개념과 유형 및 유형별 연산시간의 차이의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(O-Notation, 알고리즘, 복잡도, 설명하고)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 3교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(217,134,3,5,4,'실무/시나리오형','다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여 설명하시오.','["1. 다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','Multidimensional Index Structure, 다차원, 색인구조, 데이터 정합성, 성능·확장성, 인덱싱/분할, 무결성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 3교시 5번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(다차원 색인구조(Multidimensional Index Structure)의 개념, 유형, 활용 사례에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Multidimensional Index Structure, 다차원, 색인구조, 데이터 정합성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 3교시 #5 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(218,134,3,6,8,'개념/정의형','일부 오픈소스 라이선스가 개방형(예: MIT, BSD 등)에서 폐쇄형(예: SSPL(Server Side Public License), BSL(Business Source License) 등)으로 변화하고 있다. 이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여 설명하시오.','["1. 이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','MIT, BSD, SSPL, Server Side Public License, BSL, Business Source License, 일부, 오픈소스','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 3교시 6번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(이러한 오픈소스 라이선스 정책 변경의 배경 및 소프트웨어 산업에 미치는 영향에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(MIT, BSD, SSPL, Server Side Public License)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 3교시 #6 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(219,134,4,1,7,'원인분석/대응전략형','IT 프로젝트 관리에서 리스크 대응에 대하여 설명하시오.','["가. 리스크 대응 계획 수립 절차", "나. 위협에 대한 대응 전략", "다. 기회에 대한 대응 전략"]','["1. 리드문: IT 프로젝트 관리에서 리스크 대응에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: IT 프로젝트 관리에서 리스크 대응에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 리스크 대응 계획 수립 절차 및 위협에 대한 대응 전략 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IT, 프로젝트, 관리, 리스크, 대응, 계획, 수립, 위협','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 리스크 대응 계획 수립 절차", "리스크 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 위협에 대한 대응 전략", "위협 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 기회에 대한 대응 전략", "기회 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 4교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''IT 프로젝트 관리에서 리스크 대응에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(리스크 대응 계획 수립 절차 · 위협에 대한 대응 전략 · 기회에 대한 대응 전략)을 필수 키워드(IT, 프로젝트, 관리, 리스크)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 4교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(220,134,4,2,1,'실무/시나리오형','딥러닝에서 대규모 신경망을 효율적으로 훈련하기 위한 멀티 GPU 기술에 대하여 설명하시오.','["가. 멀티 GPU 기술의 개념과 장점", "나. 멀티 GPU 환경 구축 시 고려사항"]','["1. 리드문: 딥러닝에서 대규모 신경망을 효율적으로 훈련하기 위한 멀티 GPU 기술에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 딥러닝에서 대규모 신경망을 효율적으로 훈련하기 위한 멀티 GPU 기술에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 멀티 GPU 기술의 개념과 장점 및 멀티 GPU 환경 구축 시 고려사항 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','GPU, 딥러닝, 대규모, 신경망, 효율적, 훈련하기, 멀티, 기술','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 멀티 GPU 기술의 개념과 장점", "GPU 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 멀티 GPU 환경 구축 시 고려사항", "GPU 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 4교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''딥러닝에서 대규모 신경망을 효율적으로 훈련하기 위한 멀티 GPU 기술에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(멀티 GPU 기술의 개념과 장점 · 멀티 GPU 환경 구축 시 고려사항)을 필수 키워드(GPU, 딥러닝, 대규모, 신경망)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 4교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(221,134,4,3,8,'법제도/거버넌스형','AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.','["1. AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오. 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','AI, 시스템, 법적, 이슈, 윤리적, 문제, 기술적, 설명하고','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오. 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 4교시 3번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(AI 시스템에 대한 법적 이슈, 윤리적 문제, 기술적 문제에 대하여 설명하고 해결 방안을 제시하시오.의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(AI, 시스템, 법적, 이슈)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 4교시 #3 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(222,134,4,4,2,'원인분석/대응전략형','개방형 API(Open API)에 대하여 설명하시오.','["가. 정의 및 특징", "나. SOAP 및 REST 구성요소", "다. 취약점 및 대응 방안"]','["1. 리드문: 개방형 API(Open API)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개방형 API(Open API)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정의 및 특징 및 SOAP 및 REST 구성요소 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','API, Open API, SOAP, REST, 개방형, 취약점, 대응','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 정의 및 특징", "품질속성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. SOAP 및 REST 구성요소", "SOAP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 취약점 및 대응 방안", "취약점 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 4교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''개방형 API(Open API)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정의 및 특징 · SOAP 및 REST 구성요소 · 취약점 및 대응 방안)을 필수 키워드(API, Open API, SOAP, REST)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 4교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(223,134,4,5,7,'법제도/거버넌스형','클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여 설명하시오.','["1. 클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','클라우드, 전환, 사업, 단계별, 감리, 검토, 항목','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제134회 4교시 5번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(클라우드 전환 사업의 단계별 감리 방법과 검토 항목에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(클라우드, 전환, 사업, 단계별)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 4교시 #5 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(224,134,4,6,1,'비교/대조분석형','군집분석 기법인 SOM(Self Organizing Map)에 대하여 설명하시오.','["가. SOM 정의 및 특징", "나. SOM 구성요소", "다. SOM 과 신경망 분석기법의 차이점"]','["1. 리드문: 군집분석 기법인 SOM(Self Organizing Map)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 군집분석 기법인 SOM(Self Organizing Map)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: SOM 정의 및 특징 및 SOM 구성요소 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','SOM, Self Organizing Map, 군집분석, 기법인, 신경망, 분석기법, 아키텍처','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. SOM 정의 및 특징", "SOM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. SOM 구성요소", "SOM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. SOM 과 신경망 분석기법의 차이점", "SOM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제134회 4교시 6번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''군집분석 기법인 SOM(Self Organizing Map)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(SOM 정의 및 특징 · SOM 구성요소 · SOM 과 신경망 분석기법의 차이점)을 필수 키워드(SOM, Self Organizing Map, 군집분석, 기법인)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제134회 4교시 #6 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(225,133,1,1,2,'개념/정의형','REST API(REpresentational State Transfer Application Programming Interface)에 대하여 설명하시오.','["1. REST API(REpresentational State Transfer Application Programming Interface)에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: REST API(REpresentational State Transfer Application Programming Interface)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: REST API(REpresentational State Transfer Application Programming Interface)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: REST API(REpresentational State Transfer Application Programming Interface)에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','REST API, REpresentational State Transfer Appli, cation Programming Interface, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "REST API(REpresentational State Transfer Application Programming Interface)에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "REST API(REpresentational State Transfer Application Programming Interface)에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "REST API(REpresentational State Transfer Application Programming Interface)에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "REST API(REpresentational State Transfer Application Programming Interface)에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 1번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''REST API(REpresentational State Transfer Application Programming Interface)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(REST API(REpresentational State Transfer Application Programming Interface)에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(REST API, REpresentational State Transfer Appli, cation Programming Interface, 품질속성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #1 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(226,133,1,2,2,'개념/테스트형','뮤테이션 테스트(Mutation Testing, 변이 테스트)','["1. 테스트 스위트(Test Suite)의 결함 검출 능력을 평가하는 뮤테이션 테스트의 개념", "2. 뮤턴트(Mutant) 생성 연산자, Killed/Survived 판정 및 Mutation Score 산출식"]','["1. 리드문: 테스트 케이스 자체의 품질을 검증하는 결함 기반 테스트(Mutation Testing)", "2. 원본 프로그램(P) → 변이 연산자 적용(Mutant M) → 테스트 실행 → Killed vs Survived 흐름도", "3. 코드 커버리지(Line/Branch)의 한계와 뮤테이션 점수(Mutation Score) 산출 공식", "4. 동치 뮤턴트(Equivalent Mutant) 문제 및 연산 비용 최적화 방안"]','결함 주입(Fault Injection), 변이 연산자(Mutation Operator), Killed Mutant, Survived Mutant, 동치 뮤턴트(Equivalent Mutant), Mutation Score','{"headers": ["구분 항목", "개념 및 판정 기준", "의미 및 후속 조치"], "rows": [["죽은 뮤턴트 (Killed Mutant)", "변이된 코드(예: +를 -로 변경)에 기존 테스트 케이스를 실행했을 때 실패(Fail)가 발생한 경우", "기존 테스트 케이스가 해당 코드 결함을 정상적으로 잡아냄 (우수)"], ["살아남은 뮤턴트 (Survived Mutant)", "변이된 코드임에도 기존 테스트 케이스가 모두 통과(Pass)해버린 경우", "기존 테스트 케이스의 검증(Assertion)이 부실함 → 신규 테스트 케이스 보강 필요"], ["동치 뮤턴트 (Equivalent Mutant)", "문법은 바뀌었으나 원본 프로그램과 의미·출력 결과가 100% 동일한 변이", "어떠한 테스트로도 죽일 수 없으므로 Mutation Score 분모에서 제외"]]}','뮤테이션 테스트는 높은 코드 커버리지에도 불구하고 실제 결함을 잡지 못하는 부실한 테스트 케이스(Assertion 누락 등)를 찾아내기 위해, 원본 코드에 인위적인 작은 문법 변이(Mutant)를 주입한 뒤 기존 테스트 스위트가 이를 실패(Killed)시켜 잡아내는지 평가하는 기법이다. Mutation Score = Killed / (Total - Equivalent) × 100으로 테스트의 실질적 강건성을 측정한다.','127회 코드 커버리지 → 133회 뮤테이션 테스트로 심화 출제','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(227,133,1,3,4,'절차/설계구현형','NoSQL유형과 모델링 절차를 설명하시오.','["1. NoSQL유형과 모델링 절차의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: NoSQL유형과 모델링 절차의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: NoSQL유형과 모델링 절차 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: NoSQL유형과 모델링 절차 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','NoSQL, 모델링, 데이터 정합성, 성능·확장성, 인덱싱/분할, 무결성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "NoSQL유형과 모델링 절차의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "NoSQL유형과 모델링 절차의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "NoSQL유형과 모델링 절차의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "NoSQL유형과 모델링 절차 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 3번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''NoSQL유형과 모델링 절차''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(NoSQL유형과 모델링 절차의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(NoSQL, 모델링, 데이터 정합성, 성능·확장성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #3 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(228,133,1,4,3,'개념/암호기술형','기밀성과 무결성·부인방지를 동시에 보장하는 전자봉투(Digital Envelope)와 전자서명 결합 메커니즘','["1. 대칭키 암호(고속 대용량 처리)와 공개키 암호(안전한 키 배송)의 하이브리드 결합 원리", "2. 송신자 개인키 전자서명 + 대칭 세션키로 본문 암호화 + 수신자 공개키로 세션키 암호화(전자봉투) 절차"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','기밀성과 무결성·부인방지를 동시에 보장하는 전자봉투, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["1. 대칭키 암호(고속 대용량 처리)와 공개키 암호(안전한 키 배송)의 하이브리드 결합 원리", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["2. 송신자 개인키 전자서명 + 대칭 세션키로 본문 암호화 + 수신자 공개키로 세션키 암호화(전자봉투) 절차", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','기밀성과 무결성·부인방지를 동시에 보장하는 전자봉투(Digital Envelope)와 전자서명 결합 메커니즘 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 1. 대칭키 암호(고속 대용량 처리)와 공개키 암호(안전한 키 배송)의 하이브리드 결합 원리 및 2. 송신자 개인키 전자서명 + 대칭 세션키로 본문 암호화 + 수신자 공개키로 세션키 암호화(전자봉투) 절차을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제133회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(229,133,1,5,3,'개념/암호기술형','동형암호(Homomorphic Encryption)의 개념과 유형','["1. 복호화 없이 암호문 상태에서 연산을 수행하는 동형암호의 원리", "2. 부분 동형(PHE), 제한 동형(SHE), 완전 동형암호(FHE, 부트스트래핑) 비교"]','["1. 리드문: 클라우드·AI 시대의 프라이버시 보존 연산 핵심 기술 동형암호", "2. E(x) * E(y) = E(x + y) 암호문 상태 연산 및 부트스트래핑(Bootstrapping) 노이즈 제거 구조도", "3. PHE(부분) vs SHE(제한) vs FHE(완전 동형암호, CKKS/BGV/TFHE) 비교표", "4. 하드웨어 가속기(FHE ASIC/GPU) 및 프라이버시 보존 머신러닝(PPML) 적용 전망"]','암호문 상태 연산, 격자 기반 암호(LWE/RLWE), 노이즈 누적, 부트스트래핑(Bootstrapping), 완전동형암호(FHE), CKKS(실수 근사 연산)','{"headers": ["동형암호 세대", "지원 연산 범위", "대표 알고리즘 및 특징"], "rows": [["부분 동형암호 (PHE)", "덧셈 또는 곱셈 중 한 가지 연산만 무제한 허용", "RSA(곱셈 동형), Paillier(덧셈 동형) — 연산은 빠르나 복합 함수 불가"], ["제한 동형암호 (SHE/LHE)", "덧셈과 곱셈을 모두 지원하나 노이즈 누적으로 연산 횟수(회로 깊이) 제한", "초기 격자 기반 스킴 — 사전 정의된 얕은 깊이의 연산만 가능"], ["완전 동형암호 (FHE)", "부트스트래핑(Bootstrapping)으로 노이즈를 초기화하여 덧셈·곱셈 무제한 수행", "BGV/BFV(정수), CKKS(실수/머신러닝 특화), TFHE(부울 게이트 고속 연산)"]]}','동형암호(Homomorphic Encryption)는 데이터를 복호화하지 않고 암호문 상태에서 직접 덧셈·곱셈 연산을 수행한 결과가 평문 연산 후 암호화한 결과와 동일하게 유지되는 차세대 암호 기술이다. 특히 한국 연구진이 제안해 국제 표준화가 진행 중인 CKKS 스킴은 실수 근사 연산을 지원하여 의료·금융 데이터를 암호화한 채로 AI 추론을 수행하는 PPML의 핵심으로 활용된다.','133회 1교시 동형암호 → 138회 4교시 PET(프라이버시 강화 기술)로 확장','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(230,133,1,6,7,'개념/정의형','기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여 설명하시오.','["1. 기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Technology Acceptance Model, TAM, 기술수용모델, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 6번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(기술수용모델(Technology Acceptance Model; TAM)의 개념과 주요 구성요소에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Technology Acceptance Model, TAM, 기술수용모델, 거버넌스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #6 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(231,133,1,7,4,'법제도/거버넌스형','데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여 설명하시오.','["1. 데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','CRUD, Matrix, 데이터모델링, 매트릭스, 사용하, 표현하, 데이터 정합성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 7번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터모델링에서 CRUD 매트릭스(Matrix)를 사용하는 목적과 이를 표현하는 방법에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(CRUD, Matrix, 데이터모델링, 매트릭스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #7 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(232,133,1,8,8,'개념/정의형','인공지능 신뢰성의 개념과 핵심 속성에 대하여 설명하시오.','["1. 인공지능 신뢰성의 개념과 핵심 속성에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 인공지능 신뢰성의 개념과 핵심 속성에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인공지능 신뢰성의 개념과 핵심 속성에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인공지능 신뢰성의 개념과 핵심 속성에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','인공지능, 신뢰성, 속성, 법적 근거, 컴플라이언스, 관리체계, 공공정책','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "인공지능 신뢰성의 개념과 핵심 속성에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "인공지능 신뢰성의 개념과 핵심 속성에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "인공지능 신뢰성의 개념과 핵심 속성에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "인공지능 신뢰성의 개념과 핵심 속성에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 8번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''인공지능 신뢰성의 개념과 핵심 속성에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인공지능 신뢰성의 개념과 핵심 속성에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(인공지능, 신뢰성, 속성, 법적 근거)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #8 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(233,133,1,9,5,'실무/시나리오형','BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여 설명하시오.','["1. BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','BCP, Business Continuity Planning, DRS, Disaster Recovery System, 수립, 지표, 프로토콜 스택','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 9번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(BCP(Business Continuity Planning) 수립 시의 주요 지표와 DRS(Disaster Recovery System) 구축 시의 핵심 고려사항에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(BCP, Business Continuity Planning, DRS, Disaster Recovery System)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #9 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(234,133,1,10,3,'개념/정의형','딥페이크(Deepfake)에 대하여 설명하시오.','["1. 딥페이크(Deepfake)에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 딥페이크(Deepfake)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 딥페이크(Deepfake)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 딥페이크(Deepfake)에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Deepfake, 딥페이크, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "딥페이크(Deepfake)에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "딥페이크(Deepfake)에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "딥페이크(Deepfake)에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "딥페이크(Deepfake)에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 10번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''딥페이크(Deepfake)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(딥페이크(Deepfake)에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Deepfake, 딥페이크, 기밀성·무결성, 보안통제)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #10 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(235,133,1,11,2,'개념/정의형','소프트웨어 유지보수 향상 및 비용절감을 위한 3R을 설명하시오.','["1. 소프트웨어 유지보수 향상 및 비용절감을 위한 3R의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 소프트웨어 유지보수 향상 및 비용절감을 위한 3R의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 유지보수 향상 및 비용절감을 위한 3R 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 유지보수 향상 및 비용절감을 위한 3R 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','소프트웨어, 유지보수, 향상, 비용절감, 품질속성, 유지보수성, 설계원칙','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "소프트웨어 유지보수 향상 및 비용절감을 위한 3R의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "소프트웨어 유지보수 향상 및 비용절감을 위한 3R의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "소프트웨어 유지보수 향상 및 비용절감을 위한 3R의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "소프트웨어 유지보수 향상 및 비용절감을 위한 3R 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 1교시 11번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 유지보수 향상 및 비용절감을 위한 3R''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 유지보수 향상 및 비용절감을 위한 3R의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(소프트웨어, 유지보수, 향상, 비용절감)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 1교시 #11 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
