INSERT INTO "questions" VALUES(238,133,2,1,7,'절차/설계구현형','정보시스템 하드웨어 규모산정 지침(TTAK.KO-10.0292/R3, 2023.12.06. 개정)에 대하여 다음을 설명하시오.','["가. 규모산정의 개념 및 대상", "나. 규모산정 절차", "다. 규모산정 방식"]','["1. 리드문: 개정)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개정) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 규모산정의 개념 및 대상 및 규모산정 절차 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','TTAK, KO-10, R3, 정보시스템, 하드웨어, 규모산정, 지침, 개정','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 규모산정의 개념 및 대상", "규모산정 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 규모산정 절차", "규모산정 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 규모산정 방식", "규모산정 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 2교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''개정)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(규모산정의 개념 및 대상 · 규모산정 절차 · 규모산정 방식)을 필수 키워드(TTAK, KO-10, R3, 정보시스템)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 2교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(239,133,2,2,2,'법제도/거버넌스형','‘디지털 정부서비스 UI/UX 가이드라인’(2024.2, 행정안전부)은 디지털 서비스를 구성하는 사용자 인터페이스(User Interface; UI)와 사용자 경험(User Experience; UX) 품질에 큰 영향을 주는 요소에 대하여 행정기관 및 공공기관이 준수해야 할 세부사항을 제시한다. 이와 관련하여 다음을 설명하시오.','["가. 목적 및 주요특징", "나. 가이드라인의 구조(구성요소)", "다. 적용대상 및 기준", "라. 가이드라인의 활용방법"]','["1. 리드문: ‘디지털 정부서비스 UI/UX 가이드라인’(2024.2, 행정안전부)은 디지털 서비스를 구성하는 사용자 인터페이스(User Interface; UI)와 사용자 경험(User Experience; UX) 품질에 큰 영향을 주는 요소에 대하여 행정기관 및 공공기관이 준수해야 할 세부사항을 제시한다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ‘디지털 정부서비스 UI/UX 가이드라인’(2024.2, 행정안전부)은 디지털 서비스를 구성하는 사용자 인터페이스(User Interface; UI)와 사용자 경험(User Experience; UX) 품질에 큰 영향을 주는 요소에 대하여 행정기관 및 공공기관이 준수해야 할 세부사항을 제시한다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 목적 및 주요특징 및 가이드라인의 구조(구성요소) 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','UI/UX, User Interface, UI, User Experience, UX, 디지털, 정부서비스, 가이드라인','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 목적 및 주요특징", "주요특징 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 가이드라인의 구조(구성요소)", "가이드라인 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 적용대상 및 기준", "적용대상 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 가이드라인의 활용방법", "가이드라인 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 2교시 2번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''‘디지털 정부서비스 UI/UX 가이드라인’(2024.2, 행정안전부)은 디지털 서비스를 구성하는 사용자 인터페이스(User Interface; UI)와 사용자 경험(User Experience; UX) 품질에 큰 영향을 주는 요소에 대하여 행정기관 및 공공기관이 준수해야 할 세부사항을 제시한다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(목적 및 주요특징 · 가이드라인의 구조(구성요소) · 적용대상 및 기준)을 필수 키워드(UI/UX, User Interface, UI, User Experience)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 2교시 #2 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(240,133,2,3,7,'절차/설계구현형','ISO/IEC 20000에서 제시하는 기준을 중심으로, 정보기술 서비스 관리체계(ITSM)의 개념을 설명하고, 이 시스템의 서비스 설계 및 구축, 전환을 위한 활동에 대하여 설명하시오.','["1. 전환을 위한 활동에 대하여의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 전환을 위한 활동에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 전환을 위한 활동에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 전환을 위한 활동에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','ISO/IEC 20000, ITSM, 제시하, 중심, 정보기술, 서비스, 관리체계, 설명하고','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "전환을 위한 활동에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "전환을 위한 활동에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "전환을 위한 활동에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "전환을 위한 활동에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 2교시 3번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''전환을 위한 활동에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(전환을 위한 활동에 대하여의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(ISO/IEC 20000, ITSM, 제시하, 중심)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 2교시 #3 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(241,133,2,4,1,'개념/정의형','자연어 언어모델에서의 PLM(Pre-trained Language Model)의 특성을 설명하고, 이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로 설명하시오.','["1. 이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','PLM, Pre-trained Language Model, LLM, Large Language Model, 자연어, 언어모델에서, 특성, 설명하고','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 2교시 4번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(이모델이 최종 LLM(Large Language Model)으로 만들어지는 과정에 대하여 훈련 특성을 중심으로의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(PLM, Pre-trained Language Model, LLM, Large Language Model)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 2교시 #4 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(242,133,2,5,3,'비교/대조분석형','PbD(Privacy by Design)는 광범위한 네트워크 환경에서 발생할 수 있는 데이터 처리의 폐해를 방지하기 위해 캐나다 온타리오주의 정보 및 프라이버시 위원(Information and Privacy Commissioner)을 지낸 Ann Cavoukian이 처음 창안해 낸 개념이다. ICT분야의 프라이버시 보호를 위한 주요방법론으로서 다수의 국가에서 이를 정책에 반영하고 있다. 이와 관련하여 다음을 설명하시오.','["가. Privacy by Design의 7대 원칙", "나. Privacy by Design의 8대 전략", "다. Privacy by Design의 8대 전략과 개인정보보호법 제3조 개인정보 보호 원칙과의 비교"]','["1. 리드문: PbD(Privacy by Design)는 광범위한 네트워크 환경에서 발생할 수 있는 데이터 처리의 폐해를 방지하기 위해 캐나다 온타리오주의 정보 및 프라이버시 위원(Information and Privacy Commissioner)을 지낸 Ann Cavoukian이 처음 창안해 낸 개념이다. ICT분야의 프라이버시 보호를 위한 주요방법론으로서 다수의 국가에서 이를 정책에 반영하고 있다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: PbD(Privacy by Design)는 광범위한 네트워크 환경에서 발생할 수 있는 데이터 처리의 폐해를 방지하기 위해 캐나다 온타리오주의 정보 및 프라이버시 위원(Information and Privacy Commissioner)을 지낸 Ann Cavoukian이 처음 창안해 낸 개념이다. ICT분야의 프라이버시 보호를 위한 주요방법론으로서 다수의 국가에서 이를 정책에 반영하고 있다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: Privacy by Design의 7대 원칙 및 Privacy by Design의 8대 전략 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','PbD, Privacy by Design, Information and Privacy Commissioner, Ann Cavoukian, ICT, 광범위한, 네트워크, 환경','{"headers": ["비교 항목", "PbD(Privacy by Design)는 광범위한 네트워크 환경", "관련하여 다음을 설명하시오."], "rows": [["핵심 개념·목적", "PbD(Privacy by Design)는 의 고유 목적 및 적용 영역 정의", "관련하여 다음을 설명하시오.의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제133회 2교시 5번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''PbD(Privacy by Design)는 광범위한 네트워크 환경에서 발생할 수 있는 데이터 처리의 폐해를 방지하기 위해 캐나다 온타리오주의 정보 및 프라이버시 위원(Information and Privacy Commissioner)을 지낸 Ann Cavoukian이 처음 창안해 낸 개념이다. ICT분야의 프라이버시 보호를 위한 주요방법론으로서 다수의 국가에서 이를 정책에 반영하고 있다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(Privacy by Design의 7대 원칙 · Privacy by Design의 8대 전략 · Privacy by Design의 8대 전략과 개인정보보호법 제3조 개인정보 보호 원칙과의 비교)을 필수 키워드(PbD, Privacy by Design, Information and Privacy Commissioner, Ann Cavoukian)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 2교시 #5 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(243,133,2,6,8,'개념/정의형','데이터 안심구역의 정의, 기능, 지정요건에 대하여 설명하시오.','["1. 데이터 안심구역의 정의, 기능, 지정요건에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터 안심구역의 정의, 기능, 지정요건에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 안심구역의 정의, 기능, 지정요건에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 안심구역의 정의, 기능, 지정요건에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','데이터, 안심구역, 지정요건, 법적 근거, 컴플라이언스, 관리체계, 공공정책','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터 안심구역의 정의, 기능, 지정요건에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터 안심구역의 정의, 기능, 지정요건에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터 안심구역의 정의, 기능, 지정요건에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터 안심구역의 정의, 기능, 지정요건에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 2교시 6번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''데이터 안심구역의 정의, 기능, 지정요건에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 안심구역의 정의, 기능, 지정요건에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(데이터, 안심구역, 지정요건, 법적 근거)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 2교시 #6 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(244,133,3,1,3,'법제도/거버넌스형','안티포렌식(Anti-Forensic)이 등장하게 된 배경 및 기술을 설명하고, 안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여 설명하시오.','["1. 안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Anti-Forensic, Compliance, 안티포렌식, 등장하게, 기술, 설명하고, 대응하기, 컴플라이언스','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 3교시 1번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(안티포렌식에 대응하기 위한 컴플라이언스(Compliance) 시스템의 구축 프로세스와 활용 프로세스에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Anti-Forensic, Compliance, 안티포렌식, 등장하게)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 3교시 #1 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(245,133,3,2,3,'법제도/거버넌스형','국가사이버안보센터는 생성형AI의 보안위협과 안전한 활용을 위한 가이드라인(챗GPT 등 생성형 AI 활용 보안 가이드라인, 2023.6)을 발간하였다. 이와 관련하여 다음을 설명하시오.','["가. 생성형AI의 개념 및 활용 서비스 사례", "나. 생성형AI의 보안 위협 종류별 주요 원인과 발생 가능한 보안위협", "다. 생성형AI 모델/서비스 개발 시 보안 고려사항과 보안위협 대응방안"]','["1. 리드문: 국가사이버안보센터는 생성형AI의 보안위협과 안전한 활용을 위한 가이드라인(챗GPT 등 생성형 AI 활용 보안 가이드라인, 2023.6)을 발간하였다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 국가사이버안보센터는 생성형AI의 보안위협과 안전한 활용을 위한 가이드라인(챗GPT 등 생성형 AI 활용 보안 가이드라인, 2023.6)을 발간하였다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 생성형AI의 개념 및 활용 서비스 사례 및 생성형AI의 보안 위협 종류별 주요 원인과 발생 가능한 보안위협 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','AI, GPT, 국가사이버안보센터, 생성형, 보안위협, 안전한, 가이드라인, 보안','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 생성형AI의 개념 및 활용 서비스 사례", "AI 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 생성형AI의 보안 위협 종류별 주요 원인과 발생 가능한 보안위협", "AI 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 생성형AI 모델/서비스 개발 시 보안 고려사항과 보안위협 대응방안", "AI 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 3교시 2번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''국가사이버안보센터는 생성형AI의 보안위협과 안전한 활용을 위한 가이드라인(챗GPT 등 생성형 AI 활용 보안 가이드라인, 2023.6)을 발간하였다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(생성형AI의 개념 및 활용 서비스 사례 · 생성형AI의 보안 위협 종류별 주요 원인과 발생 가능한 보안위협 · 생성형AI 모델/서비스 개발 시 보안 고려사항과 보안위협 대응방안)을 필수 키워드(AI, GPT, 국가사이버안보센터, 생성형)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 3교시 #2 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(246,133,3,3,2,'비교/대조분석형','슈퍼앱의 정의와 주요요소 (슈퍼앱에 대하여 다음을 설명하시오)','["가. 슈퍼앱의 정의와 주요요소", "나. 슈퍼앱과 멀티앱의 비교", "다. 슈퍼앱상 구동 서비스 미니앱", "라. 슈퍼앱의 사례와 전망 및 이슈사항"]','["1. 리드문: 슈퍼앱의 정의와 주요요소 (슈퍼앱에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 슈퍼앱의 정의와 주요요소 (슈퍼앱에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 슈퍼앱의 정의와 주요요소 및 슈퍼앱과 멀티앱의 비교 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','슈퍼앱, 주요요소, 멀티앱, 슈퍼앱상, 구동, 서비스, 미니앱, 이슈사항','{"headers": ["비교 항목", "슈퍼앱의 정의", "주요요소 (슈퍼앱에 대하여 다음을 설명하시오)"], "rows": [["핵심 개념·목적", "슈퍼앱의 정의의 고유 목적 및 적용 영역 정의", "주요요소 (슈퍼앱에 대하여 다음을 설명하시오의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제133회 3교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''슈퍼앱의 정의와 주요요소 (슈퍼앱에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(슈퍼앱의 정의와 주요요소 · 슈퍼앱과 멀티앱의 비교 · 슈퍼앱상 구동 서비스 미니앱)을 필수 키워드(슈퍼앱, 주요요소, 멀티앱, 슈퍼앱상)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 3교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(247,133,3,4,7,'법제도/거버넌스형','경영환경을 분석하는 방법인 SWOT(Strengths, Weaknesses, Opportunities, Threats), 3C(Customer, Competitor, Company), PEST(Political, Economical, Social, Technological) 분석에 대하여 각 방법의 특성과 적용을 위한 조건, 그리고 분석 방법에 대하여 설명하시오.','["1. 그리고 분석 방법에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 그리고 분석 방법에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 그리고 분석 방법에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 그리고 분석 방법에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','SWOT, Strengths, Weaknesses, Opportunities, Threats, Customer, Competitor, Company','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "그리고 분석 방법에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "그리고 분석 방법에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "그리고 분석 방법에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "그리고 분석 방법에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 3교시 4번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''그리고 분석 방법에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(그리고 분석 방법에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(SWOT, Strengths, Weaknesses, Opportunities)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 3교시 #4 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(248,133,3,5,2,'절차/설계구현형','소프트웨어 요구공학(Requirement Engineering)에 대하여 설명하시오.','["가. 요구공학 정의 및 필요성", "나. 요구공학 절차", "다. 요구사항 명세서"]','["1. 리드문: 소프트웨어 요구공학(Requirement Engineering)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 요구공학(Requirement Engineering)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 요구공학 정의 및 필요성 및 요구공학 절차 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Requirement Engineering, 소프트웨어, 요구공학, 요구사항, 명세서, 품질속성, 유지보수성','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 요구공학 정의 및 필요성", "요구공학 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 요구공학 절차", "요구공학 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 요구사항 명세서", "요구사항 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 3교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 요구공학(Requirement Engineering)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(요구공학 정의 및 필요성 · 요구공학 절차 · 요구사항 명세서)을 필수 키워드(Requirement Engineering, 소프트웨어, 요구공학, 요구사항)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 3교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(249,133,3,6,1,'절차/설계구현형','인공신경망 (인공신경망에 대하여 다음을 설명하시오)','["가. 인공신경망의 개념, 구성요소, 역할", "나. 피드포워드 뉴럴 네트워크(Feedforward Neural Network) 개념 및 절차", "다. 역전파(Backpropagation) 개념 및 절차", "라. 활성화 함수의 종류"]','["1. 리드문: 인공신경망 (인공신경망에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인공신경망 (인공신경망에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인공신경망의 개념, 구성요소, 역할 및 피드포워드 뉴럴 네트워크(Feedforward Neural Netwo 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Feedforward Neural Network, Backpropagation, 인공신경망, 피드포워드, 뉴럴, 네트워크, 역전파, 활성화','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 인공신경망의 개념, 구성요소, 역할", "인공신경망 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 피드포워드 뉴럴 네트워크(Feedforward Neural Network) 개념 및 절차", "Feedforward Neural Network 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 역전파(Backpropagation) 개념 및 절차", "Backpropagation 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 활성화 함수의 종류", "활성화 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 3교시 6번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''인공신경망 (인공신경망에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인공신경망의 개념, 구성요소, 역할 · 피드포워드 뉴럴 네트워크(Feedforward Neural Network) 개념 및 절차 · 역전파(Backpropagation) 개념 및 절차)을 필수 키워드(Feedforward Neural Network, Backpropagation, 인공신경망, 피드포워드)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 3교시 #6 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(250,133,4,1,3,'원인분석/대응전략형','데이터 중심 사회에서 데이터의 프라이버시와 보안은 매우 중요한 이슈로 부상하고 있고, 이를 해결하기 위한 다양한 기술적 접근이 시도되고 있다. 그러한 시도 중에서 다자간 계산(Multi-Party Computation; MPC)에 대하여 다음을 설명하시오.','["가. MPC 개념, 원리, 특징", "나. MPC 기술 종류", "다. MPC 기반 인증서비스"]','["1. 리드문: 그러한 시도 중에서 다자간 계산(Multi-Party Computation; MPC)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 그러한 시도 중에서 다자간 계산(Multi-Party Computation; MPC) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: MPC 개념, 원리, 특징 및 MPC 기술 종류 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Multi-Party Computation, MPC, 데이터, 중심, 사회, 프라이버시, 보안, 매우','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. MPC 개념, 원리, 특징", "MPC 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. MPC 기술 종류", "MPC 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. MPC 기반 인증서비스", "MPC 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 4교시 1번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''그러한 시도 중에서 다자간 계산(Multi-Party Computation; MPC)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(MPC 개념, 원리, 특징 · MPC 기술 종류 · MPC 기반 인증서비스)을 필수 키워드(Multi-Party Computation, MPC, 데이터, 중심)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 4교시 #1 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(251,133,4,2,2,'절차/설계구현형','정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여 각각 설명하시오.','["1. 정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','정보시스템, 개발, 운영, 단계, 수행되, 소프트웨어, 테스트, 쓰고','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 4교시 2번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보시스템 개발과 운영 단계에서 수행되는 소프트웨어 테스트의 종류를 쓰고, 이 중 신뢰성 테스트와 이식성 테스트의 세부 활동에 대하여의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(정보시스템, 개발, 운영, 단계)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 4교시 #2 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(252,133,4,3,3,'법제도/거버넌스형','정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여 설명하시오.','["1. 정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','정보보호, 암호화, 접근제어, 크게, 분류할, 개념과정책, 그리고, 구현하','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제133회 4교시 3번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보보호 방법을 암호화와 접근제어로 크게 분류할 때, 접근제어에 대하여 그 개념과정책, 절차, 그리고 이를 구현하는 메커니즘에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(정보보호, 암호화, 접근제어, 크게)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 4교시 #3 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(253,133,4,4,4,'비교/대조분석형','RDBMS를 적용하기 위한 데이터 모델링에 대하여 다음을 설명하시오.','["가. 데이터 모델링의 개념 및 모델링 단계별 수행내용", "나. 데이터 관계 모델링 시 식별(Identification)과 비식별(Non Identification)에 대하여 비교", "다. 데이터 모델링 시 고려사항"]','["1. 리드문: RDBMS를 적용하기 위한 데이터 모델링의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: RDBMS를 적용하기 위한 데이터 모델링 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 모델링의 개념 및 모델링 단계별 수행내용 및 데이터 관계 모델링 시 식별(Identification)과 비식별(N 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','RDBMS, Identification, Non Identification, 적용하기, 데이터, 모델링, 단계별, 수행내용','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 데이터 모델링의 개념 및 모델링 단계별 수행내용", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 데이터 관계 모델링 시 식별(Identification)과 비식별(Non Identification)에 대하여 비교", "Identification 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 데이터 모델링 시 고려사항", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 4교시 4번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''RDBMS를 적용하기 위한 데이터 모델링''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 모델링의 개념 및 모델링 단계별 수행내용 · 데이터 관계 모델링 시 식별(Identification)과 비식별(Non Identification)에 대하여 비교 · 데이터 모델링 시 고려사항)을 필수 키워드(RDBMS, Identification, Non Identification, 적용하기)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 4교시 #4 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(254,133,4,5,5,'실무/시나리오형','5G 특화망을 위한 네트워크를 구축할 때 고려되어야 할 사항에 대하여 다음을 설명하시오.','["가. 안정성‧신뢰성 확보 방안", "나. 간섭회피 방안"]','["1. 리드문: 5G 특화망을 위한 네트워크를 구축할 때 고려되어야 할 사항의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 5G 특화망을 위한 네트워크를 구축할 때 고려되어야 할 사항 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 안정성‧신뢰성 확보 방안 및 간섭회피 방안 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','특화망, 네트워크, 구축할, 고려되어야, 사항, 안정성, 신뢰성, 확보','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 안정성‧신뢰성 확보 방안", "안정성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 간섭회피 방안", "간섭회피 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 4교시 5번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''5G 특화망을 위한 네트워크를 구축할 때 고려되어야 할 사항''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(안정성‧신뢰성 확보 방안 · 간섭회피 방안)을 필수 키워드(특화망, 네트워크, 구축할, 고려되어야)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 4교시 #5 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(255,133,4,6,5,'개념/정의형','VPN(Virtual Private Network)에 대하여 다음을 설명하시오.','["가. VPN의 개념 및 특징", "나. IPSec(Internet Protocol Security) VPN과 SSL(Secure Socket Layer) VPN", "다. VPN의 기술요소"]','["1. 리드문: VPN(Virtual Private Network)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: VPN(Virtual Private Network) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: VPN의 개념 및 특징 및 IPSec(Internet Protocol Security) VPN과 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','VPN, Virtual Private Network, IPSec, Internet Protocol Security, SSL, Secure Socket Layer, 기술요소','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. VPN의 개념 및 특징", "VPN 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. IPSec(Internet Protocol Security) VPN과 SSL(Secure Socket Layer) VPN", "IPSec 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. VPN의 기술요소", "VPN 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제133회 4교시 6번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''VPN(Virtual Private Network)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(VPN의 개념 및 특징 · IPSec(Internet Protocol Security) VPN과 SSL(Secure Socket Layer) VPN · VPN의 기술요소)을 필수 키워드(VPN, Virtual Private Network, IPSec, Internet Protocol Security)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제133회 4교시 #6 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(256,132,1,1,7,'개념/위험관리표준형','국제 표준 리스크 관리 프레임워크 ISO 31000의 3대 구성요소(원칙, 프레임워크, 프로세스)','["1. 가치 창출과 보호를 핵심으로 하는 ISO 31000의 8대 원칙과 리더십 기반 프레임워크", "2. 리스크 식별(Identification) → 리스크 분석(Analysis) → 리스크 평가(Evaluation) → 리스크 처리(Treatment) 프로세스"]','["1. 리드문: 핵심 개념 정의 및 출제 배경", "2. 아키텍처 및 동작 메커니즘 개념도", "3. 핵심 요소 및 대안 기술 비교표", "4. 실무 적용 고려사항 및 기술사적 제언"]','국제 표준 리스크 관리 프레임워크 ISO 31000의 3대 구성요소, 메커니즘, 비교분석, 트레이드오프, 실무거버넌스','{"headers": ["비교/구분 항목", "핵심 원리 및 구성요소", "실무 적용 및 검증 기준"], "rows": [["1. 가치 창출과 보호를 핵심으로 하는 ISO 31000의 8대 원칙과 리더십 기반 프레임워크", "표준 메커니즘 및 핵심 구조 정의", "정합성·성능·보안 요구사항 검증"], ["2. 리스크 식별(Identification) → 리스크 분석(Analysis) → 리스크 평가(Evaluation) → 리스크 처리(Treatment) 프로세스", "대안 기법과의 정량·정성적 트레이드오프 비교", "엔터프라이즈 운영 거버넌스 확립"]]}','국제 표준 리스크 관리 프레임워크 ISO 31000의 3대 구성요소(원칙, 프레임워크, 프로세스) 토픽은 정보관리기술사 핵심 기출 문항으로, (1) 정의와 필요성을 리드문으로 선언하고, (2) 메커니즘 구조도를 도식화한 뒤, (3) 1. 가치 창출과 보호를 핵심으로 하는 ISO 31000의 8대 원칙과 리더십 기반 프레임워크 및 2. 리스크 식별(Identification) → 리스크 분석(Analysis) → 리스크 평가(Evaluation) → 리스크 처리(Treatment) 프로세스를 대조표로 구조화하고, (4) 실무 적용 시 한계점과 극복 제언을 제시해야 한다.','제132회 주요 기출 및 도메인 순환 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(257,132,1,2,7,'개념/정의형','데이터 거래소','["1. 데이터 거래소의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터 거래소의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 거래소 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 거래소 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','데이터, 거래소, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터 거래소의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터 거래소의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터 거래소의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터 거래소 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 1교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''데이터 거래소''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 거래소의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(데이터, 거래소, 거버넌스, ROI·성과지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(258,132,1,3,1,'개념/정의형','베이지안 최적화 (Bayesian Optimization)','["1. 베이지안 최적화 (Bayesian Optimization)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 베이지안 최적화 (Bayesian Optimization)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 베이지안 최적화 (Bayesian Optimization) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 베이지안 최적화 (Bayesian Optimization) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Bayesian Optimization, 베이지안, 최적화, 아키텍처, 성능지표, 학습·추론 최적화, 신뢰성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "베이지안 최적화 (Bayesian Optimization)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "베이지안 최적화 (Bayesian Optimization)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "베이지안 최적화 (Bayesian Optimization)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "베이지안 최적화 (Bayesian Optimization) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 1교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''베이지안 최적화 (Bayesian Optimization)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(베이지안 최적화 (Bayesian Optimization)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Bayesian Optimization, 베이지안, 최적화, 아키텍처)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(259,132,1,4,3,'개념/정의형','대칭 암호화와 비대칭 암호화','["1. 대칭 암호화와 비대칭 암호화의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 대칭 암호화와 비대칭 암호화의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 대칭 암호화와 비대칭 암호화 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 대칭 암호화와 비대칭 암호화 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','대칭, 암호화, 비대칭, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "대칭 암호화와 비대칭 암호화의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "대칭 암호화와 비대칭 암호화의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "대칭 암호화와 비대칭 암호화의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "대칭 암호화와 비대칭 암호화 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 1교시 4번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''대칭 암호화와 비대칭 암호화''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(대칭 암호화와 비대칭 암호화의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(대칭, 암호화, 비대칭, 기밀성·무결성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #4 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(260,132,1,5,3,'개념/산업보안형','산업제어시스템 보안 표준 ISA/IEC 62443','["1. 스마트팩토리·OT/ICS 보안을 위한 ISA/IEC 62443 표준 구조(General, Policies, System, Component)", "2. Zone & Conduit(구역과 통로) 네트워크 분할 모델 및 보안 등급(SL 1~4)"]','["1. 리드문: IT-OT 융합 환경의 산업제어시스템(ICS/SCADA) 국제 보안 표준 ISA/IEC 62443", "2. Purdue 모델 계층 및 Zone(보안구역) & Conduit(통신통로) 방어 아키텍처도", "3. 보안 등급 SL 1~4(Security Level) 및 SL-T / SL-C / SL-A 비교표", "4. 다크 팩토리 및 국가 기반시설 OT 보안 강화를 위한 무중단 보안 적용 방안"]','OT/ICS 보안, Purdue Model, Zone(보안 구역) & Conduit(통로), Security Level(SL 1~4), 심층 방어(Defense in Depth)','{"headers": ["보안 등급 (SL)", "위협 행위자 수준", "요구되는 방어 수준"], "rows": [["SL 1 / SL 2", "우발적 실수(SL 1) / 단순 도구·낮은 자원을 가진 고의적 침해(SL 2)", "기본 오작동 방지 및 일반 해커의 비인가 접근 차단"], ["SL 3", "산업제어 특화 지식과 중간 수준의 자원을 보유한 해커 그룹", "OT 프로토콜(MODBUS/DNP3) 심층 패킷 분석 및 강력한 인증·암호화"], ["SL 4", "국가 지원(APT) 수준의 막대한 자원과 고도의 전문성을 가진 공격자", "다중 물리·논리 격리, 하드웨어 루트오브트러스트, 무결성 실시간 검증"]]}','ISA/IEC 62443은 발전소, 스마트팩토리 등 산업자동화 및 제어시스템(IACS/OT)의 사이버 보안을 위한 국제 표준이다. 시스템을 보안 요구사항이 동일한 구역(Zone)으로 묶고 구역 간 모든 통신을 통제된 통로(Conduit)로만 허용하는 Zone & Conduit 모델과 공격자 역량에 따른 4단계 보안 등급(SL 1~4)을 핵심으로 한다.','132회 ISA/IEC 62443 → 137회 MODBUS → 140회 다크팩토리로 OT 보안 계보 형성','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(261,132,1,6,3,'개념/정의형','큐싱 (Qshing)','["1. 큐싱 (Qshing)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 큐싱 (Qshing)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 큐싱 (Qshing) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 큐싱 (Qshing) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Qshing, 큐싱, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "큐싱 (Qshing)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "큐싱 (Qshing)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "큐싱 (Qshing)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "큐싱 (Qshing) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 1교시 6번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''큐싱 (Qshing)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(큐싱 (Qshing)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Qshing, 큐싱, 기밀성·무결성, 보안통제)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #6 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(262,132,1,7,6,'개념/정의형','ELK(Elasticsearch/Logstach/Kibana) 스택','["1. ELK(Elasticsearch/Logstach/Kibana) 스택의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: ELK(Elasticsearch/Logstach/Kibana) 스택의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ELK(Elasticsearch/Logstach/Kibana) 스택 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ELK(Elasticsearch/Logstach/Kibana) 스택 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','ELK, Elasticsearch/Logstach/Kibana, 스택, 자원스케줄링, 메모리 계층, 동기화·일관성, 성능병목','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "ELK(Elasticsearch/Logstach/Kibana) 스택의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "ELK(Elasticsearch/Logstach/Kibana) 스택의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "ELK(Elasticsearch/Logstach/Kibana) 스택의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "ELK(Elasticsearch/Logstach/Kibana) 스택 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 1교시 7번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''ELK(Elasticsearch/Logstach/Kibana) 스택''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ELK(Elasticsearch/Logstach/Kibana) 스택의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(ELK, Elasticsearch/Logstach/Kibana, 스택, 자원스케줄링)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #7 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(263,132,1,8,3,'개념/하드웨어보안형','하드웨어 기반 신뢰점(Root of Trust)을 제공하는 보안 칩 TPM(Trusted Platform Module) 2.0의 구조와 기능','["1. 암호키 생성·보관(RSA/ECC/AES), 난수 생성기(RNG), 플랫폼 구성 레지스터(PCR) 구조", "2. 측정 부팅(Measured Boot), 디스크 암호화(BitLocker) 키 봉인(Sealing) 및 원격 증명(Remote Attestation)"]','["1. 리드문: 핵심 개념 정의 및 출제 배경", "2. 아키텍처 및 동작 메커니즘 개념도", "3. 핵심 요소 및 대안 기술 비교표", "4. 실무 적용 고려사항 및 기술사적 제언"]','하드웨어 기반 신뢰점, 메커니즘, 비교분석, 트레이드오프, 실무거버넌스','{"headers": ["비교/구분 항목", "핵심 원리 및 구성요소", "실무 적용 및 검증 기준"], "rows": [["1. 암호키 생성·보관(RSA/ECC/AES), 난수 생성기(RNG), 플랫폼 구성 레지스터(PCR) 구조", "표준 메커니즘 및 핵심 구조 정의", "정합성·성능·보안 요구사항 검증"], ["2. 측정 부팅(Measured Boot), 디스크 암호화(BitLocker) 키 봉인(Sealing) 및 원격 증명(Remote Attestation)", "대안 기법과의 정량·정성적 트레이드오프 비교", "엔터프라이즈 운영 거버넌스 확립"]]}','하드웨어 기반 신뢰점(Root of Trust)을 제공하는 보안 칩 TPM(Trusted Platform Module) 2.0의 구조와 기능 토픽은 정보관리기술사 핵심 기출 문항으로, (1) 정의와 필요성을 리드문으로 선언하고, (2) 메커니즘 구조도를 도식화한 뒤, (3) 1. 암호키 생성·보관(RSA/ECC/AES), 난수 생성기(RNG), 플랫폼 구성 레지스터(PCR) 구조 및 2. 측정 부팅(Measured Boot), 디스크 암호화(BitLocker) 키 봉인(Sealing) 및 원격 증명(Remote Attestation)를 대조표로 구조화하고, (4) 실무 적용 시 한계점과 극복 제언을 제시해야 한다.','제132회 주요 기출 및 도메인 순환 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(264,132,1,9,2,'개념/정의형','좋은 소프트웨어가 갖추어야 할 4가지 특성','["1. 좋은 소프트웨어가 갖추어야 할 4가지 특성의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 좋은 소프트웨어가 갖추어야 할 4가지 특성의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 좋은 소프트웨어가 갖추어야 할 4가지 특성 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 좋은 소프트웨어가 갖추어야 할 4가지 특성 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','소프트웨어, 갖추어야, 특성, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "좋은 소프트웨어가 갖추어야 할 4가지 특성의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "좋은 소프트웨어가 갖추어야 할 4가지 특성의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "좋은 소프트웨어가 갖추어야 할 4가지 특성의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "좋은 소프트웨어가 갖추어야 할 4가지 특성 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 1교시 9번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''좋은 소프트웨어가 갖추어야 할 4가지 특성''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(좋은 소프트웨어가 갖추어야 할 4가지 특성의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(소프트웨어, 갖추어야, 특성, 품질속성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #9 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(265,132,1,10,1,'비교/대조분석형','모집단의특성을 추론하는 점추정과 구간추정 비교','["1. 모집단의특성을 추론하는 점추정과 구간추정 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 모집단의특성을 추론하는 점추정과 구간추정 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 모집단의특성을 추론하는 점추정과 구간추정 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 모집단의특성을 추론하는 점추정과 구간추정 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','모집단의특성, 추론하, 점추정, 구간추정, 아키텍처, 성능지표, 학습·추론 최적화','{"headers": ["비교 항목", "모집단의특성을 추론하는 점추정", "구간추정"], "rows": [["핵심 개념·목적", "모집단의특성을 추론하는 점추정의 고유 목적 및 적용 영역 정의", "구간추정의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제132회 1교시 10번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''모집단의특성을 추론하는 점추정과 구간추정 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(모집단의특성을 추론하는 점추정과 구간추정 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(모집단의특성, 추론하, 점추정, 구간추정)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #10 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(266,132,1,11,1,'원인분석/통계모형형','회귀분석에서 다중공선성(Multicollinearity)의 발생 원인, 진단 지표(분산팽창계수 VIF >= 10) 및 해결 방안','["1. 독립변수들 간 강한 선형 상관관계로 인해 회귀계수 추정치의 분산이 비정상적으로 커지는 현상", "2. VIF(Variance Inflation Factor) 진단 기준과 변수 제거, 주성분 회귀(PCA), 능형 회귀(Ridge L2) 해결 기법"]','["1. 리드문: 핵심 개념 정의 및 출제 배경", "2. 아키텍처 및 동작 메커니즘 개념도", "3. 핵심 요소 및 대안 기술 비교표", "4. 실무 적용 고려사항 및 기술사적 제언"]','회귀분석에서 다중공선성, 메커니즘, 비교분석, 트레이드오프, 실무거버넌스','{"headers": ["비교/구분 항목", "핵심 원리 및 구성요소", "실무 적용 및 검증 기준"], "rows": [["1. 독립변수들 간 강한 선형 상관관계로 인해 회귀계수 추정치의 분산이 비정상적으로 커지는 현상", "표준 메커니즘 및 핵심 구조 정의", "정합성·성능·보안 요구사항 검증"], ["2. VIF(Variance Inflation Factor) 진단 기준과 변수 제거, 주성분 회귀(PCA), 능형 회귀(Ridge L2) 해결 기법", "대안 기법과의 정량·정성적 트레이드오프 비교", "엔터프라이즈 운영 거버넌스 확립"]]}','회귀분석에서 다중공선성(Multicollinearity)의 발생 원인, 진단 지표(분산팽창계수 VIF >= 10) 및 해결 방안 토픽은 정보관리기술사 핵심 기출 문항으로, (1) 정의와 필요성을 리드문으로 선언하고, (2) 메커니즘 구조도를 도식화한 뒤, (3) 1. 독립변수들 간 강한 선형 상관관계로 인해 회귀계수 추정치의 분산이 비정상적으로 커지는 현상 및 2. VIF(Variance Inflation Factor) 진단 기준과 변수 제거, 주성분 회귀(PCA), 능형 회귀(Ridge L2) 해결 기법를 대조표로 구조화하고, (4) 실무 적용 시 한계점과 극복 제언을 제시해야 한다.','제132회 주요 기출 및 도메인 순환 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(267,132,1,12,5,'개념/정의형','블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식','["1. 블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','블록, 스토리지, 파일, 오브젝트, 데이터, 접근방식, 프로토콜 스택','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 1교시 12번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(블록 스토리지, 파일 스토리지, 오브젝트 스토리지의 데이터 접근방식의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(블록, 스토리지, 파일, 오브젝트)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 1교시 #12 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(268,132,1,13,4,'개념/분산DB형','분산 데이터베이스의 5가지 투명성(Transparency)','["1. 분산 데이터베이스의 정의와 목표(논리적 단일 DB 뷰 제공)", "2. 위치, 분할, 복제, 병행, 장애 투명성의 개념 및 보장 메커니즘(2PC 등)"]','["1. 리드문: 물리적 분산 환경을 논리적 단일 DB처럼 사용하게 하는 분산 DB 투명성", "2. 전역 스키마 - 분할 스키마 - 할당 스키마 계층 및 분산 DBMS 구조도", "3. 분산 DB 5대 투명성(위치·분할·복제·병행·장애) 상세 비교표", "4. 클라우드 네이티브 분산 SQL(NewSQL: CockroachDB, Spanner)에서의 구현 진화"]','위치 투명성(Location), 분할 투명성(Fragmentation), 복제 투명성(Replication), 병행 투명성(Concurrency), 장애 투명성(Failure), 2PC(2단계 커밋)','{"headers": ["투명성 종류", "핵심 의미", "주요 구현 기법"], "rows": [["위치 / 분할 투명성", "데이터의 물리적 저장 위치나 수평/수직 분할 여부를 몰라도 논리적 테이블명으로 접근", "전역 데이터 사전(Global Directory), 분산 쿼리 옵티마이저"], ["복제 / 병행 투명성", "데이터가 여러 노드에 복제된 사실이나 다수 분산 트랜잭션 동시 실행을 의식하지 않음", "Quorum 합의(Raft/Paxos), 분산 2PL(Two-Phase Locking), 타임스탬프"], ["장애 투명성", "특정 노드나 통신 회선 장애가 발생해도 트랜잭션의 원자성(Atomicity)과 일관성 보장", "2PC(Two-Phase Commit) / 3PC 프로토콜, 분산 WAL 로그 복구"]]}','분산 데이터베이스의 투명성은 물리적으로 네트워크에 분산된 데이터 저장소들을 사용자가 마치 하나의 중앙집중식 데이터베이스처럼 위치나 분할·복제·장애 여부를 의식하지 않고 사용할 수 있게 보장하는 성질이다. 제132회 1교시, 제138회 3교시(분할), 제139회 1교시 등 매 1~2년마다 반드시 출제되는 초빈출 핵심 토픽이다.','132회 1교시 → 138회 3교시 → 139회 1교시 반복 출제된 최빈출 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(269,132,2,1,1,'개념/정의형','중심극한정리, t-검정, z-검정을 설명하시오','["1. 중심극한정리, t-검정, z-검정의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 중심극한정리, t-검정, z-검정의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 중심극한정리, t-검정, z-검정 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 중심극한정리, t-검정, z-검정 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','중심극한정리, 검정, 아키텍처, 성능지표, 학습·추론 최적화, 신뢰성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "중심극한정리, t-검정, z-검정의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "중심극한정리, t-검정, z-검정의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "중심극한정리, t-검정, z-검정의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "중심극한정리, t-검정, z-검정 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 2교시 1번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''중심극한정리, t-검정, z-검정''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(중심극한정리, t-검정, z-검정의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(중심극한정리, 검정, 아키텍처, 성능지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 2교시 #1 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(270,132,2,2,1,'비교/머신러닝형','선형 서포트 벡터 머신(SVM)의 하드 마진(Hard Margin)과 소프트 마진(Soft Margin, 슬랙 변수·C 파라미터) 분류 방법 및 커널 트릭','["가. 결정 경계(Hyperplane)와 서포트 벡터 간 마진(2/||w||) 최대화 원리", "나. 이상치 허용을 위한 슬랙 변수(ξ)와 규제 파라미터(C) 트레이드오프 및 비선형 커널 트릭(RBF)"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','선형 서포트 벡터 머신, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["가. 결정 경계(Hyperplane)와 서포트 벡터 간 마진(2/||w||) 최대화 원리", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["나. 이상치 허용을 위한 슬랙 변수(ξ)와 규제 파라미터(C) 트레이드오프 및 비선형 커널 트릭(RBF)", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','선형 서포트 벡터 머신(SVM)의 하드 마진(Hard Margin)과 소프트 마진(Soft Margin, 슬랙 변수·C 파라미터) 분류 방법 및 커널 트릭 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 가. 결정 경계(Hyperplane)와 서포트 벡터 간 마진(2/||w||) 최대화 원리 및 나. 이상치 허용을 위한 슬랙 변수(ξ)와 규제 파라미터(C) 트레이드오프 및 비선형 커널 트릭(RBF)을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제132회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(271,132,2,3,8,'개념/정의형','현재 소프트웨어 기술자 구분은 과거 기술자 등급제에서 IT역량분류체계를 기반으로 한 직무제 (IT직무제)로 변경되어 운영되고 있으나 실무 현장에서는 여전히 폐지된 등급제가 다수 활용되고 있는 실정이다. 소프트웨어 기술자 구분에 대하여 다음을 설명하시오.','["가. 소프트웨어 기술자 등급제와 IT직무제의 개념과 특징", "나. 현행 IT직무제의 문제점과 개선방향"]','["1. 리드문: 소프트웨어 기술자 구분의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 기술자 구분 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 기술자 등급제와 IT직무제의 개념과 특징 및 현행 IT직무제의 문제점과 개선방향 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','IT, 현재, 소프트웨어, 기술자, 과거, 등급제, 역량분류체계, 직무제','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 소프트웨어 기술자 등급제와 IT직무제의 개념과 특징", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 현행 IT직무제의 문제점과 개선방향", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 2교시 3번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''소프트웨어 기술자 구분''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 기술자 등급제와 IT직무제의 개념과 특징 · 현행 IT직무제의 문제점과 개선방향)을 필수 키워드(IT, 현재, 소프트웨어, 기술자)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 2교시 #3 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(272,132,2,4,7,'법제도/거버넌스형','최근 개인정보보호위원회는 마이데이터 전송 시 개인정보의 안전한 처리를 보장하기 위한 가이드라인 (마이데이터 전송 보안 안내서, 2023.09.)을 발간하였다. 이와 관련하여 다음을 설명하시오.','["가. 전송대상 개인정보 보호책임자의 지정", "나. 전송대상 개인정보처리시스템의 접근 관리", "다. 전송대상 개인정보관리 및 재해재난 대비 조치"]','["1. 리드문: 최근 개인정보보호위원회는 마이데이터 전송 시 개인정보의 안전한 처리를 보장하기 위한 가이드라인 (마이데이터 전송 보안 안내서, 2023.09.)을 발간하였다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 최근 개인정보보호위원회는 마이데이터 전송 시 개인정보의 안전한 처리를 보장하기 위한 가이드라인 (마이데이터 전송 보안 안내서, 2023.09.)을 발간하였다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 전송대상 개인정보 보호책임자의 지정 및 전송대상 개인정보처리시스템의 접근 관리 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','개인정보보호위원회, 마이데이터, 전송, 개인정보, 안전한, 처리, 보장하기, 가이드라인','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 전송대상 개인정보 보호책임자의 지정", "전송대상 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 전송대상 개인정보처리시스템의 접근 관리", "전송대상 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 전송대상 개인정보관리 및 재해재난 대비 조치", "전송대상 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 2교시 4번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''최근 개인정보보호위원회는 마이데이터 전송 시 개인정보의 안전한 처리를 보장하기 위한 가이드라인 (마이데이터 전송 보안 안내서, 2023.09.)을 발간하였다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(전송대상 개인정보 보호책임자의 지정 · 전송대상 개인정보처리시스템의 접근 관리 · 전송대상 개인정보관리 및 재해재난 대비 조치)을 필수 키워드(개인정보보호위원회, 마이데이터, 전송, 개인정보)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 2교시 #4 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(273,132,2,5,8,'절차/설계구현형','ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과를 설명하시오.','["1. ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','ISO 14000, 인증, 인증규격, 인증절차, 인증효과, 법적 근거, 컴플라이언스','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 2교시 5번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ISO 14000 인증의 개념과 필요성, 인증규격, 구축 및 인증절차, 인증효과의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(ISO 14000, 인증, 인증규격, 인증절차)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 2교시 #5 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(274,132,2,6,2,'개념/정의형','선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리를 설명하시오.','["1. 선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','선형, 자료, 구조인, 스택, 리스트, 입출력, 품질속성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 2교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(선형 자료 구조인 스택, 큐, 리스트의 자료 입출력 원리의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(선형, 자료, 구조인, 스택)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 2교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(275,132,3,1,8,'절차/설계구현형','소프트웨어 (이하 SW) 운영단계 대가산정에 대하여 다음을 설명하시오. (단, "소프트웨어 사업 대가 산정 가이드 2023년 개정판" 기준)','["가. 응용SW 요율제 유지관리비 산정방식과 SW운영 투입공수 산정방식", "나. 고정비/변동비 산정방식"]','["1. 리드문: 소프트웨어 (이하 SW) 운영단계 대가산정의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 (이하 SW) 운영단계 대가산정 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 응용SW 요율제 유지관리비 산정방식과 SW운영 투입공수 산정방식 및 고정비/변동비 산정방식 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','SW, 소프트웨어, 이하, 운영단계, 대가산정, 사업, 산정, 가이드','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 응용SW 요율제 유지관리비 산정방식과 SW운영 투입공수 산정방식", "SW 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 고정비/변동비 산정방식", "고정비 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 3교시 1번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''소프트웨어 (이하 SW) 운영단계 대가산정''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(응용SW 요율제 유지관리비 산정방식과 SW운영 투입공수 산정방식 · 고정비/변동비 산정방식)을 필수 키워드(SW, 소프트웨어, 이하, 운영단계)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 3교시 #1 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(276,132,3,2,5,'개념/정의형','클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과를 설명하시오.','["1. 클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','클라우드, 관리, 플랫폼, 필수, 선정기준, 프로토콜 스택, 대역폭·지연시간','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 3교시 2번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(클라우드 관리 플랫폼의 정의 및 필요성, 필수 기능, 플랫폼 선정기준, 기대효과의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(클라우드, 관리, 플랫폼, 필수)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 3교시 #2 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(277,132,3,3,1,'절차/설계구현형','다음과 같이 형태소 분석을 통하여 분서 별로 단어의점수가 식별되었다. 각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과를 설명하시오. (단, Inverse Document Frequency 계산 시 log을 취하여 구하되 Document Emergency 값을 임의로 가공하지 않아야 하며, 주어진 Log값만을 활용한다.)','["1. 각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','TF-IDF, Term Frequency-Inverse Document Frequ, ency, Inverse Document Frequency, log, Document Emergency, 형태소, 분석','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 3교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(각 문서의 TF-IDF (Term Frequency-Inverse Document Frequency)를 식별하기 위한 계산 과정과 그 결과의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(TF-IDF, Term Frequency-Inverse Document Frequ, ency, Inverse Document Frequency)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 3교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(278,132,3,4,5,'개념/정의형','SCTP (Stream Control Transmission Protocol)와 관련하여 다음을 설명하시오.','["가. SCTP 개요와 특징", "나. SCTP 프로토콜 (Protocol) 구조 및 동작 방식"]','["1. 리드문: SCTP (Stream Control Transmission Protocol)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: SCTP (Stream Control Transmission Protocol) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: SCTP 개요와 특징 및 SCTP 프로토콜 (Protocol) 구조 및 동작 방식 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','SCTP, Stream Control Transmission Protocol, Protocol, 개요, 프로토콜, 동작, 프로토콜 스택','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. SCTP 개요와 특징", "SCTP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. SCTP 프로토콜 (Protocol) 구조 및 동작 방식", "SCTP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 3교시 4번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''SCTP (Stream Control Transmission Protocol)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(SCTP 개요와 특징 · SCTP 프로토콜 (Protocol) 구조 및 동작 방식)을 필수 키워드(SCTP, Stream Control Transmission Protocol, Protocol, 개요)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 3교시 #4 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(279,132,3,5,8,'개념/정의형','APEC (Asia-Pacific Economic Cooperation)의 CBPR (Cross Border Privacy Rules)에 대하여 다음을 설명하시오.','["가. APEC 프라이버시 9원칙", "나. CBPR의 주요 인증기준"]','["1. 리드문: APEC (Asia-Pacific Economic Cooperation)의 CBPR (Cross Border Privacy Rules)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: APEC (Asia-Pacific Economic Cooperation)의 CBPR (Cross Border Privacy Rules) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: APEC 프라이버시 9원칙 및 CBPR의 주요 인증기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','APEC, Asia-Pacific Economic Cooperation, CBPR, Cross Border Privacy Rules, 프라이버시, 원칙, 인증기준','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. APEC 프라이버시 9원칙", "APEC 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. CBPR의 주요 인증기준", "CBPR 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 3교시 5번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''APEC (Asia-Pacific Economic Cooperation)의 CBPR (Cross Border Privacy Rules)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(APEC 프라이버시 9원칙 · CBPR의 주요 인증기준)을 필수 키워드(APEC, Asia-Pacific Economic Cooperation, CBPR, Cross Border Privacy Rules)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 3교시 #5 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(280,132,3,6,2,'절차/설계구현형','정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여 설명하시오.','["1. 정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','정보시스템, 성능, 요구사항, 작성, 고려해야, 성능지표, 품질속성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 3교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보시스템의 성능 요구사항 작성 시 고려해야 하는 주요 성능지표 및 내용에 대하여의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(정보시스템, 성능, 요구사항, 작성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 3교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(281,132,4,1,3,'원인분석/대응전략형','FIPS (Frederal Information Processing Standard) 140-2에 대하여 다음을 설명하시오.','["가. FIPS 140-2 레벨 분류", "나. 암호화 시스템 설계 시 고려사항", "다. 암호화 시스템의 보안 요소", "라. 보안 위협 대응 전략"]','["1. 리드문: FIPS (Frederal Information Processing Standard) 140-2의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: FIPS (Frederal Information Processing Standard) 140-2 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: FIPS 140-2 레벨 분류 및 암호화 시스템 설계 시 고려사항 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','FIPS, Frederal Information Processing Stand, ard, FIPS 140-2, 레벨, 분류, 암호화, 시스템','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. FIPS 140-2 레벨 분류", "FIPS 140-2 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 암호화 시스템 설계 시 고려사항", "암호화 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 암호화 시스템의 보안 요소", "암호화 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 보안 위협 대응 전략", "보안 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 4교시 1번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''FIPS (Frederal Information Processing Standard) 140-2''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(FIPS 140-2 레벨 분류 · 암호화 시스템 설계 시 고려사항 · 암호화 시스템의 보안 요소)을 필수 키워드(FIPS, Frederal Information Processing Stand, ard, FIPS 140-2)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 4교시 #1 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(282,132,4,2,4,'원인분석/대응전략형','행정안전부에서 고품질의 공공데이터 제공 및 활용의 선제적 대응을 위해 "공공데이터베이스 표준화 관리 매뉴얼(2023.04)"을 마련하여 예방적 품질관리 기준을 제시하고 있다. 이와 관련하여 다음을 설명하시오.','["가. 시스템 구축 추진 단계별 예방적 품질관리 활동", "나. 공공데이터 예방적 품질관리 4개 진단영역과 9개 진단항목"]','["1. 리드문: 행정안전부에서 고품질의 공공데이터 제공 및 활용의 선제적 대응을 위해 \"공공데이터베이스 표준화 관리 매뉴얼(2023.04)\"을 마련하여 예방적 품질관리 기준을 제시하고 있다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 행정안전부에서 고품질의 공공데이터 제공 및 활용의 선제적 대응을 위해 \"공공데이터베이스 표준화 관리 매뉴얼(2023.04)\"을 마련하여 예방적 품질관리 기준을 제시하고 있다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 시스템 구축 추진 단계별 예방적 품질관리 활동 및 공공데이터 예방적 품질관리 4개 진단영역과 9개 진단항목 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','행정안전부, 고품질, 공공데이터, 제공, 선제적, 대응, 위해, 공공데이터베이스','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 시스템 구축 추진 단계별 예방적 품질관리 활동", "시스템 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 공공데이터 예방적 품질관리 4개 진단영역과 9개 진단항목", "공공데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 4교시 2번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''행정안전부에서 고품질의 공공데이터 제공 및 활용의 선제적 대응을 위해 "공공데이터베이스 표준화 관리 매뉴얼(2023.04)"을 마련하여 예방적 품질관리 기준을 제시하고 있다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(시스템 구축 추진 단계별 예방적 품질관리 활동 · 공공데이터 예방적 품질관리 4개 진단영역과 9개 진단항목)을 필수 키워드(행정안전부, 고품질, 공공데이터, 제공)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 4교시 #2 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(283,132,4,3,1,'실무/시나리오형','설비 예지정비 (Predictive Maintenance) 시스템 구축 시 LangChain 프레임워크를 활용할 수 있는 방안에 대하여 다음을 설명하시오.','["가. 설비 예지정비의 개념 및 필요성", "나. LangChain 프레임워크와 LLM (Large Language Model.", "다. LangChain을 이용한 설비 예지정비"]','["1. 리드문: 설비 예지정비 (Predictive Maintenance) 시스템 구축 시 LangChain 프레임워크를 활용할 수 있는 방안의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 설비 예지정비 (Predictive Maintenance) 시스템 구축 시 LangChain 프레임워크를 활용할 수 있는 방안 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 설비 예지정비의 개념 및 필요성 및 LangChain 프레임워크와 LLM (Large Language M 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Predictive Maintenance, LangChain, LLM, Large Language Model, 설비, 예지정비, 시스템, 프레임워크','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 설비 예지정비의 개념 및 필요성", "설비 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. LangChain 프레임워크와 LLM (Large Language Model.", "LangChain 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. LangChain을 이용한 설비 예지정비", "LangChain 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 4교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''설비 예지정비 (Predictive Maintenance) 시스템 구축 시 LangChain 프레임워크를 활용할 수 있는 방안''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(설비 예지정비의 개념 및 필요성 · LangChain 프레임워크와 LLM (Large Language Model. · LangChain을 이용한 설비 예지정비)을 필수 키워드(Predictive Maintenance, LangChain, LLM, Large Language Model)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 4교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(284,132,4,4,8,'법제도/거버넌스형','소프트웨어 진흥법 (시행 2023.10.19)은 소프트웨어 산업의 발전을 위해 시행되어야 할 다양한 활동의 법적 근거를 마련하고 있다. 이와 관련하여 다음을 설명하시오.','["가. 제5조 (기본계획의 수립 등)의 2항에 따른 기본계획 내 포함되어야 할 사항", "나. 제30조 (소프트웨어안전 확보)의 2항에 따른 소프트웨어안전 확보를 위한 지침 내 포함되어야 할 사항"]','["1. 리드문: 소프트웨어 진흥법 (시행 2023.10.19)은 소프트웨어 산업의 발전을 위해 시행되어야 할 다양한 활동의 법적 근거를 마련하고 있다. 이와 관련하여 다음을 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 진흥법 (시행 2023.10.19)은 소프트웨어 산업의 발전을 위해 시행되어야 할 다양한 활동의 법적 근거를 마련하고 있다. 이와 관련하여 다음을 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 제5조 (기본계획의 수립 등)의 2항에 따른 기본계획 내 포함되어야 및 제30조 (소프트웨어안전 확보)의 2항에 따른 소프트웨어안전 확보를 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','소프트웨어, 진흥법, 시행, 산업, 발전, 위해, 시행되어야, 다양한','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 제5조 (기본계획의 수립 등)의 2항에 따른 기본계획 내 포함되어야 할 사항", "기본계획 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 제30조 (소프트웨어안전 확보)의 2항에 따른 소프트웨어안전 확보를 위한 지침 내 포함되어야 할 사항", "소프트웨어안전 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 4교시 4번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''소프트웨어 진흥법 (시행 2023.10.19)은 소프트웨어 산업의 발전을 위해 시행되어야 할 다양한 활동의 법적 근거를 마련하고 있다. 이와 관련하여 다음을 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(제5조 (기본계획의 수립 등)의 2항에 따른 기본계획 내 포함되어야 할 사항 · 제30조 (소프트웨어안전 확보)의 2항에 따른 소프트웨어안전 확보를 위한 지침 내 포함되어야 할 사항)을 필수 키워드(소프트웨어, 진흥법, 시행, 산업)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 4교시 #4 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(285,132,4,5,8,'비교/대조분석형','소프트웨어 개발에 필요한 규모 산정 방식 종류와 특징을 비교 설명하고, 공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여 설명하시오.','["1. 공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','소프트웨어, 개발, 필요한, 규모, 산정, 설명하고, 공공, 사업','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제132회 4교시 5번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(공공 소프트웨어 사업 규모 산정 방식의 현실적 개선 방안에 대하여의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(소프트웨어, 개발, 필요한, 규모)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 4교시 #5 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(286,132,4,6,3,'원인분석/대응전략형','A 기업의 경영진은 임직원들의 증가로 인해 정보보안의 필요성을 인식하고 정보보안 부서의 신설과 정보보안 체계를 수립하고자 한다. 다음을 설명하시오.','["가. 정보보호 정책의 개념", "나. 정보보호 시점별 보안 활동 (Security Action Cycle)", "다. 정보보안 전문가의 역할과 역량"]','["1. 리드문: A 기업의 경영진은 임직원들의 증가로 인해 정보보안의 필요성을 인식하고 정보보안 부서의 신설과 정보보안 체계를 수립하고자 한다의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: A 기업의 경영진은 임직원들의 증가로 인해 정보보안의 필요성을 인식하고 정보보안 부서의 신설과 정보보안 체계를 수립하고자 한다 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보보호 정책의 개념 및 정보보호 시점별 보안 활동 (Security Action Cycle) 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Security Action Cycle, 경영진, 임직원들, 증가, 인해, 정보보안, 인식하고, 부서','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 정보보호 정책의 개념", "정보보호 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 정보보호 시점별 보안 활동 (Security Action Cycle)", "Security Action Cycle 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 정보보안 전문가의 역할과 역량", "정보보안 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제132회 4교시 6번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''A 기업의 경영진은 임직원들의 증가로 인해 정보보안의 필요성을 인식하고 정보보안 부서의 신설과 정보보안 체계를 수립하고자 한다''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보보호 정책의 개념 · 정보보호 시점별 보안 활동 (Security Action Cycle) · 정보보안 전문가의 역할과 역량)을 필수 키워드(Security Action Cycle, 경영진, 임직원들, 증가)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제132회 4교시 #6 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(287,131,1,1,7,'개념/정의형','디지털 트랜스포메이션(Digital Transformation)','["1. 디지털 트랜스포메이션(Digital Transformation)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 디지털 트랜스포메이션(Digital Transformation)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 디지털 트랜스포메이션(Digital Transformation) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 디지털 트랜스포메이션(Digital Transformation) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Digital Transformation, 디지털, 트랜스포메이션, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "디지털 트랜스포메이션(Digital Transformation)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "디지털 트랜스포메이션(Digital Transformation)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "디지털 트랜스포메이션(Digital Transformation)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "디지털 트랜스포메이션(Digital Transformation) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''디지털 트랜스포메이션(Digital Transformation)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(디지털 트랜스포메이션(Digital Transformation)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Digital Transformation, 디지털, 트랜스포메이션, 거버넌스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(288,131,1,2,5,'개념/정의형','NFC(Near Field Communication)','["1. NFC(Near Field Communication)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: NFC(Near Field Communication)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: NFC(Near Field Communication) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: NFC(Near Field Communication) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','NFC, Near Field Communication, 프로토콜 스택, 대역폭·지연시간, 고가용성, 트래픽 제어','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "NFC(Near Field Communication)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "NFC(Near Field Communication)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "NFC(Near Field Communication)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "NFC(Near Field Communication) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 2번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''NFC(Near Field Communication)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(NFC(Near Field Communication)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(NFC, Near Field Communication, 프로토콜 스택, 대역폭·지연시간)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #2 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(289,131,1,3,2,'비교/대조분석형','폭포수 개발 방법론과 애자일 개발 방법론의 특징 및 장단점 비교','["1. 폭포수 개발 방법론과 애자일 개발 방법론의 특징 및 장단점 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 폭포수 개발 방법론과 애자일 개발 방법론의 특징 및 장단점 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 폭포수 개발 방법론과 애자일 개발 방법론의 특징 및 장단점 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 폭포수 개발 방법론과 애자일 개발 방법론의 특징 및 장단점 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','폭포수, 개발, 방법론, 애자일, 품질속성, 유지보수성, 설계원칙','{"headers": ["비교 항목", "폭포수 개발 방법론", "애자일 개발 방법론의 특징 및 장단점"], "rows": [["핵심 개념·목적", "폭포수 개발 방법론의 고유 목적 및 적용 영역 정의", "애자일 개발 방법론의 특징 및 장단점의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제131회 1교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''폭포수 개발 방법론과 애자일 개발 방법론의 특징 및 장단점 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(폭포수 개발 방법론과 애자일 개발 방법론의 특징 및 장단점 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(폭포수, 개발, 방법론, 애자일)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(290,131,1,4,5,'비교/대조분석형','클라우드 컴퓨팅의 Service Model과 Deployment Model 비교','["1. 클라우드 컴퓨팅의 Service Model과 Deployment Model 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 클라우드 컴퓨팅의 Service Model과 Deployment Model 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 클라우드 컴퓨팅의 Service Model과 Deployment Model 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 클라우드 컴퓨팅의 Service Model과 Deployment Model 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Service Model, Deployment Model, 클라우드, 컴퓨팅, 프로토콜 스택, 대역폭·지연시간, 고가용성','{"headers": ["비교 항목", "클라우드 컴퓨팅의 Service Model", "Deployment Model"], "rows": [["핵심 개념·목적", "클라우드 컴퓨팅의 Service Model의 고유 목적 및 적용 영역 정의", "Deployment Model의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제131회 1교시 4번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''클라우드 컴퓨팅의 Service Model과 Deployment Model 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(클라우드 컴퓨팅의 Service Model과 Deployment Model 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Service Model, Deployment Model, 클라우드, 컴퓨팅)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #4 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(291,131,1,5,1,'개념/정의형','데이터 차원 축소(Data Dimensionality Reduction)','["1. 데이터 차원 축소(Data Dimensionality Reduction)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터 차원 축소(Data Dimensionality Reduction)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 차원 축소(Data Dimensionality Reduction) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 차원 축소(Data Dimensionality Reduction) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Data Dimensionality Reduction, 데이터, 차원, 축소, 아키텍처, 성능지표, 학습·추론 최적화','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터 차원 축소(Data Dimensionality Reduction)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터 차원 축소(Data Dimensionality Reduction)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터 차원 축소(Data Dimensionality Reduction)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터 차원 축소(Data Dimensionality Reduction) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 5번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''데이터 차원 축소(Data Dimensionality Reduction)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 차원 축소(Data Dimensionality Reduction)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Data Dimensionality Reduction, 데이터, 차원, 축소)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #5 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(292,131,1,6,7,'비교/대조분석형','정보시스템 감리와 PMO(Project Management Office) 비교','["1. 정보시스템 감리와 PMO(Project Management Office) 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 정보시스템 감리와 PMO(Project Management Office) 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보시스템 감리와 PMO(Project Management Office) 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보시스템 감리와 PMO(Project Management Office) 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','PMO, Project Management Office, 정보시스템, 감리, 거버넌스, ROI·성과지표, 리스크 관리','{"headers": ["비교 항목", "정보시스템 감리", "PMO(Project Management Office)"], "rows": [["핵심 개념·목적", "정보시스템 감리의 고유 목적 및 적용 영역 정의", "PMO(Project Management O의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제131회 1교시 6번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''정보시스템 감리와 PMO(Project Management Office) 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보시스템 감리와 PMO(Project Management Office) 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(PMO, Project Management Office, 정보시스템, 감리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #6 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(293,131,1,7,1,'비교/대조분석형','머신러닝(Machine Learning)과 딥러닝(Deep Learning) 차이','["1. 머신러닝(Machine Learning)과 딥러닝(Deep Learning) 차이의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 머신러닝(Machine Learning)과 딥러닝(Deep Learning) 차이의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 머신러닝(Machine Learning)과 딥러닝(Deep Learning) 차이 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 머신러닝(Machine Learning)과 딥러닝(Deep Learning) 차이 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Machine Learning, Deep Learning, 머신러닝, 딥러닝, 아키텍처, 성능지표, 학습·추론 최적화','{"headers": ["비교 항목", "머신러닝(Machine Learning)", "딥러닝(Deep Learning)"], "rows": [["핵심 개념·목적", "머신러닝(Machine Learning)의 고유 목적 및 적용 영역 정의", "딥러닝(Deep Learning)의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제131회 1교시 7번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''머신러닝(Machine Learning)과 딥러닝(Deep Learning) 차이''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(머신러닝(Machine Learning)과 딥러닝(Deep Learning) 차이의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Machine Learning, Deep Learning, 머신러닝, 딥러닝)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #7 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(294,131,1,8,5,'개념/정의형','오토 스케일링(Auto Scaling)','["1. 오토 스케일링(Auto Scaling)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 오토 스케일링(Auto Scaling)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 오토 스케일링(Auto Scaling) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 오토 스케일링(Auto Scaling) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Auto Scaling, 오토, 스케일링, 프로토콜 스택, 대역폭·지연시간, 고가용성, 트래픽 제어','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "오토 스케일링(Auto Scaling)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "오토 스케일링(Auto Scaling)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "오토 스케일링(Auto Scaling)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "오토 스케일링(Auto Scaling) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 8번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''오토 스케일링(Auto Scaling)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(오토 스케일링(Auto Scaling)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Auto Scaling, 오토, 스케일링, 프로토콜 스택)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #8 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(295,131,1,9,1,'비교/수리통계형','독립표본 t-검정(Independent Sample t-test)과 대응표본 t-검정(Paired Sample t-test)의 가정 및 차이점 비교','["1. 두 집단 간 평균 차이의 통계적 유의성 검정 원리(정규성, 등분산성 가정)", "2. 서로 다른 두 집단 비교(독립표본)와 동일 대상의 사전-사후 변화 비교(대응표본) 수식 및 활용 사례"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','독립표본 t-검정, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["1. 두 집단 간 평균 차이의 통계적 유의성 검정 원리(정규성, 등분산성 가정)", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["2. 서로 다른 두 집단 비교(독립표본)와 동일 대상의 사전-사후 변화 비교(대응표본) 수식 및 활용 사례", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','독립표본 t-검정(Independent Sample t-test)과 대응표본 t-검정(Paired Sample t-test)의 가정 및 차이점 비교 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 1. 두 집단 간 평균 차이의 통계적 유의성 검정 원리(정규성, 등분산성 가정) 및 2. 서로 다른 두 집단 비교(독립표본)와 동일 대상의 사전-사후 변화 비교(대응표본) 수식 및 활용 사례을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제131회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(296,131,1,10,3,'개념/정의형','크리덴셜 스터핑(Credential stuffing)','["1. 크리덴셜 스터핑(Credential stuffing)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 크리덴셜 스터핑(Credential stuffing)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 크리덴셜 스터핑(Credential stuffing) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 크리덴셜 스터핑(Credential stuffing) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Credential stuffing, 크리덴셜, 스터핑, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "크리덴셜 스터핑(Credential stuffing)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "크리덴셜 스터핑(Credential stuffing)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "크리덴셜 스터핑(Credential stuffing)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "크리덴셜 스터핑(Credential stuffing) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 10번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''크리덴셜 스터핑(Credential stuffing)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(크리덴셜 스터핑(Credential stuffing)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Credential stuffing, 크리덴셜, 스터핑, 기밀성·무결성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #10 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(297,131,1,11,4,'개념/정의형','데이터 표준화의 필요성과 기대효과','["1. 데이터 표준화의 필요성과 기대효과의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터 표준화의 필요성과 기대효과의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 표준화의 필요성과 기대효과 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 표준화의 필요성과 기대효과 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','데이터, 표준화, 기대효, 데이터 정합성, 성능·확장성, 인덱싱/분할, 무결성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터 표준화의 필요성과 기대효과의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터 표준화의 필요성과 기대효과의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터 표준화의 필요성과 기대효과의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터 표준화의 필요성과 기대효과 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 11번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''데이터 표준화의 필요성과 기대효과''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 표준화의 필요성과 기대효과의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(데이터, 표준화, 기대효, 데이터 정합성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #11 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(298,131,1,12,2,'법제도/거버넌스형','객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)','["1. 객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Encapsulation, Information Hiding, 객체지향, 방법론, 캡슐화, 정보은닉, 품질속성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 12번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(객체지향 방법론에서 캡슐화(Encapsulation)와 정보은닉(Information Hiding)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Encapsulation, Information Hiding, 객체지향, 방법론)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #12 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(299,131,1,13,3,'개념/정의형','SBOM(Software Bill of Material)','["1. SBOM(Software Bill of Material)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: SBOM(Software Bill of Material)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: SBOM(Software Bill of Material) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: SBOM(Software Bill of Material) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','SBOM, Software Bill of Material, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "SBOM(Software Bill of Material)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "SBOM(Software Bill of Material)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "SBOM(Software Bill of Material)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "SBOM(Software Bill of Material) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 1교시 13번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''SBOM(Software Bill of Material)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(SBOM(Software Bill of Material)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(SBOM, Software Bill of Material, 기밀성·무결성, 보안통제)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 1교시 #13 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(300,131,2,1,1,'개념/아키텍처형','파운데이션 모델(Foundation Model)의 개념, 기반 기술 및 법적·환경적·사회적 고려사항','["가. 파운데이션 모델의 정의와 자기지도학습(Self-Supervised Learning)·트랜스포머 기반 기술", "나. 스케일링 법칙(Scaling Law)과 창발적 능력(Emergent Abilities)", "다. 도입 시 법적(저작권/개인정보)·환경적(탄소배출)·사회적(편향/환각) 리스크 및 대응 방안"]','["1. 리드문: 단일 태스크 AI에서 범용 적응형 AI로의 전환 Foundation Model", "2. 대규모 비라벨 사전학습(Self-Supervised) → 다운스트림 적응(Fine-tuning / In-Context) 구조도", "3. 기존 Task-Specific AI 모델 vs Foundation Model 비교표", "4. 소형 언어모델(sLLM)·양자화(Green AI) 및 AI 거버넌스 대응 제언"]','자기지도학습(Self-Supervised Learning), Scaling Law(스케일링 법칙), 창발성(Emergent Ability), 동질화(Homogenization) 리스크, Green AI','{"headers": ["비교 항목", "기존 특화 모델 (Task-Specific AI)", "파운데이션 모델 (Foundation Model)"], "rows": [["학습 데이터 및 방식", "특정 과업용 라벨링 데이터 기반 지도학습(Supervised)", "방대한 비라벨 멀티모달 데이터 기반 자기지도학습(Self-Supervised)"], ["적응 및 확장성", "새로운 과업마다 처음부터 별도 모델 재학습 필요", "단일 거대 모델을 프롬프트·PEFT로 수백 가지 하위 과업에 전이 활용"], ["핵심 리스크", "라벨링 비용 과다, 일반화 성능 한계", "단일 기저 모델 결함이 모든 하위 서비스로 전파되는 동질화(Homogenization) 위험"]]}','파운데이션 모델은 방대한 비라벨 데이터를 자기지도학습(Self-Supervised Learning)으로 사전 학습하여 다양한 다운스트림 과업(번역, 요약, 코딩, 시각 인지 등)에 범용적으로 적응할 수 있는 초거대 기저 모델이다. 높은 활용성 이면에 저작권 분쟁, 막대한 전력 소모, 환각 및 단일 실패점(동질화) 위험이 존재하므로 sLLM 최적화와 거버넌스가 요구된다.','생성형 AI/LLM 시리즈의 출발점이 된 기출','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(301,131,2,1,7,'비교/대조분석형','ISP(Information Strategic Planning)와 BPR(Business Process Reengineering)의 개념과 수행절차를 비교 설명하고, 기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안을 설명하시오.','["1. 기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','ISP, Information Strategic Planning, BPR, Business Process Reengineering, 수행절차, 설명하고, 두가지, 상호','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 2교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(기업에서 이 두가지 상호 보완적으로 활용하기 위한 방안의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(ISP, Information Strategic Planning, BPR, Business Process Reengineering)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 2교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(302,131,2,2,1,'절차/설계구현형','데이터 시각화(Data Visualization)와 관련하여 다음을 설명하시오.','["가. 데이터 시각화의 개요", "나. 데이터 시각화의 원리 및 절차", "다. 데이터 시각화 유형", "라. 효과적인 데이터 시각화를 위한 효율화 방안"]','["1. 리드문: 데이터 시각화(Data Visualization)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 시각화(Data Visualization) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 시각화의 개요 및 데이터 시각화의 원리 및 절차 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Data Visualization, 데이터, 시각화, 개요, 효과적인, 효율화, 아키텍처','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 데이터 시각화의 개요", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 데이터 시각화의 원리 및 절차", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 데이터 시각화 유형", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 효과적인 데이터 시각화를 위한 효율화 방안", "효과적인 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 2교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''데이터 시각화(Data Visualization)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 시각화의 개요 · 데이터 시각화의 원리 및 절차 · 데이터 시각화 유형)을 필수 키워드(Data Visualization, 데이터, 시각화, 개요)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 2교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(303,131,2,3,8,'법제도/거버넌스형','인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여 설명하시오.','["1. 인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','인공지능, 개발, 적용과정, 윤리적, 다루어져야, 효과적, 관리하고, 규제하기','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 2교시 3번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인공지능 개발 및 적용과정에서 윤리적으로 다루어져야 할 주요 내용과 인공지능을 효과적으로 관리하고 규제하기 위한 거버넌스 모형에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(인공지능, 개발, 적용과정, 윤리적)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 2교시 #3 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(304,131,2,4,3,'비교/대조분석형','제로 트러스트 보안(Zero Trust Security)모델의 보안원리, 핵심원칙, 적용분야를 트러스트 보안(Trust Security) 모델과 비교하여 설명하시오.','["1. 적용분야를 트러스트 보안(Trust Security) 모델과의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 적용분야를 트러스트 보안(Trust Security) 모델과의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 적용분야를 트러스트 보안(Trust Security) 모델과 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 적용분야를 트러스트 보안(Trust Security) 모델과 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Zero Trust Security, Trust Security, 트러스트, 보안, 모델, 보안원리, 핵심원칙, 적용분야','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "적용분야를 트러스트 보안(Trust Security) 모델과의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "적용분야를 트러스트 보안(Trust Security) 모델과의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "적용분야를 트러스트 보안(Trust Security) 모델과의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "적용분야를 트러스트 보안(Trust Security) 모델과 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 2교시 4번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''적용분야를 트러스트 보안(Trust Security) 모델과''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(적용분야를 트러스트 보안(Trust Security) 모델과의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Zero Trust Security, Trust Security, 트러스트, 보안)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 2교시 #4 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(305,131,2,5,5,'비교/대조분석형','소켓(Socket) 통신과 관련하여 다음을 설명하시오.','["가. 소켓 통신 정의", "나. 소켓 통신 방식 개념도 및 유형", "다. TCP 소켓 및 Web 소켓 흐름 설명", "라. 소켓 통신 방식과 HTTP 통신 방식 비교"]','["1. 리드문: 소켓(Socket) 통신의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소켓(Socket) 통신 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소켓 통신 정의 및 소켓 통신 방식 개념도 및 유형 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Socket, TCP, Web, HTTP, 소켓, 통신, 흐름, 설명','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 소켓 통신 정의", "소켓 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 소켓 통신 방식 개념도 및 유형", "소켓 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. TCP 소켓 및 Web 소켓 흐름 설명", "TCP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 소켓 통신 방식과 HTTP 통신 방식 비교", "HTTP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 2교시 5번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''소켓(Socket) 통신''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소켓 통신 정의 · 소켓 통신 방식 개념도 및 유형 · TCP 소켓 및 Web 소켓 흐름 설명)을 필수 키워드(Socket, TCP, Web, HTTP)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 2교시 #5 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(306,131,2,6,2,'비교/대조분석형','아키텍처 스타일과 디자인 패턴에 대하여 다음을 설명하시오.','["가. 아키텍처 스타일과 디자인 패턴의 차이", "나. 대표적인 아키텍처 스타일 3가지", "다. GoF(Gang of Four) 디자인 패턴과 유형을 구분하고, 유형별 대표적인 디자인 패턴 설명"]','["1. 리드문: 아키텍처 스타일과 디자인 패턴의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 아키텍처 스타일과 디자인 패턴 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 아키텍처 스타일과 디자인 패턴의 차이 및 대표적인 아키텍처 스타일 3가지 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','GoF, Gang of Four, 아키텍처, 스타일, 디자인, 패턴, 대표적인, 구분하고','{"headers": ["비교 항목", "아키텍처 스타일", "디자인 패턴"], "rows": [["핵심 개념·목적", "아키텍처 스타일의 고유 목적 및 적용 영역 정의", "디자인 패턴의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제131회 2교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''아키텍처 스타일과 디자인 패턴''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(아키텍처 스타일과 디자인 패턴의 차이 · 대표적인 아키텍처 스타일 3가지 · GoF(Gang of Four) 디자인 패턴과 유형을 구분하고, 유형별 대표적인 디자인 패턴 설명)을 필수 키워드(GoF, Gang of Four, 아키텍처, 스타일)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 2교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(307,131,3,1,1,'절차/설계구현형','인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여 설명하시오.','["1. 인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','인공지능, 학습용, 데이터, 허브, 과정, 생성된, 품질확보, 주요활동','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 3교시 1번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인공지능 학습용 데이터 허브 구축 과정에서 생성된 학습용 데이터 셋의 품질확보를 위한 주요활동과 데이터 생애 주기별 품질관리 수행절차에 대하여의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(인공지능, 학습용, 데이터, 허브)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 3교시 #1 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(308,131,3,2,2,'비교/대조분석형','데이터 구조(Data Structure)에 대하여 다음을 설명하시오.','["가. 선형 구조(Linear Structure)의 개념 및 유형", "나. 비선형 구조(Non-Linear Structure)의 개념 및 유형", "다. 선형 구조(Linear Structure) 와 비선형 구조(Non-Linear Structure) 비교"]','["1. 리드문: 데이터 구조(Data Structure)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 구조(Data Structure) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 선형 구조(Linear Structure)의 개념 및 유형 및 비선형 구조(Non-Linear Structure)의 개념 및 유형 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Data Structure, Linear Structure, Non-Linear Structure, 데이터, 선형, 비선형, 품질속성','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 선형 구조(Linear Structure)의 개념 및 유형", "Linear Structure 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 비선형 구조(Non-Linear Structure)의 개념 및 유형", "Non-Linear Structure 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 선형 구조(Linear Structure) 와 비선형 구조(Non-Linear Structure) 비교", "Linear Structure 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 3교시 2번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''데이터 구조(Data Structure)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(선형 구조(Linear Structure)의 개념 및 유형 · 비선형 구조(Non-Linear Structure)의 개념 및 유형 · 선형 구조(Linear Structure) 와 비선형 구조(Non-Linear Structure) 비교)을 필수 키워드(Data Structure, Linear Structure, Non-Linear Structure, 데이터)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 3교시 #2 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(309,131,3,3,2,'개념/정의형','통합테스트(Integration Test)에 대하여 다음을 설명하시오.','["가. 비점진적 통합 방식과 점진적 통합 방식", "나. 하향식(Top Down) 통합 테스트와 상향식(Bottom Up) 통합 테스트", "다. 테스트 드라이버(Test Driver)와 테스트 스텁(Test Stub)."]','["1. 리드문: 통합테스트(Integration Test)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 통합테스트(Integration Test) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 비점진적 통합 방식과 점진적 통합 방식 및 하향식(Top Down) 통합 테스트와 상향식(Bottom Up) 통 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Integration Test, Top Down, Bottom Up, Test Driver, Test Stub, 통합테스트, 비점진적, 통합','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 비점진적 통합 방식과 점진적 통합 방식", "비점진적 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 하향식(Top Down) 통합 테스트와 상향식(Bottom Up) 통합 테스트", "Top Down 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 테스트 드라이버(Test Driver)와 테스트 스텁(Test Stub).", "Test Driver 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 3교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''통합테스트(Integration Test)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(비점진적 통합 방식과 점진적 통합 방식 · 하향식(Top Down) 통합 테스트와 상향식(Bottom Up) 통합 테스트 · 테스트 드라이버(Test Driver)와 테스트 스텁(Test Stub).)을 필수 키워드(Integration Test, Top Down, Bottom Up, Test Driver)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 3교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(310,131,3,4,7,'법제도/거버넌스형','소프트웨어 안전성 분석의 필요성과 다음의 분석 기법을 설명하시오.','["가. FTA(Fault Tree Analysis)", "나. FMEA(Failure Mode and Effects Analysis)", "다. HAZOP(Hazard and Operability Analysis)"]','["1. 리드문: 소프트웨어 안전성 분석의 필요성과 다음의 분석 기법의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 안전성 분석의 필요성과 다음의 분석 기법 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: FTA(Fault Tree Analysis) 및 FMEA(Failure Mode and Effects Analysis 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','FTA, Fault Tree Analysis, FMEA, Failure Mode and Effects Analysis, HAZOP, Hazard and Operability Analysis, 소프트웨어, 안전성','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. FTA(Fault Tree Analysis)", "FTA 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. FMEA(Failure Mode and Effects Analysis)", "FMEA 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. HAZOP(Hazard and Operability Analysis)", "HAZOP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 3교시 4번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''소프트웨어 안전성 분석의 필요성과 다음의 분석 기법''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(FTA(Fault Tree Analysis) · FMEA(Failure Mode and Effects Analysis) · HAZOP(Hazard and Operability Analysis))을 필수 키워드(FTA, Fault Tree Analysis, FMEA, Failure Mode and Effects Analysis)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 3교시 #4 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(311,131,3,5,6,'비교/대조분석형','운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 개념을 설명하고, 두 기법에 대하여 비교 설명하시오.','["1. 운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 개념을 설명하고, 두 기법에 대하여의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 개념을 설명하고, 두 기법에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 개념을 설명하고, 두 기법에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 개념을 설명하고, 두 기법에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','운영체제, 메모리, 관리, 페이징, 세그멘티이션, 설명하고, 자원스케줄링','{"headers": ["비교 항목", "운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 ", "두 기법에 대하여"], "rows": [["핵심 개념·목적", "운영체제 메모리 관리 기법 중 페이징 기법과의 고유 목적 및 적용 영역 정의", "두 기법에 대하여의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제131회 3교시 5번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 개념을 설명하고, 두 기법에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(운영체제 메모리 관리 기법 중 페이징 기법과 세그멘티이션 기법의 개념을 설명하고, 두 기법에 대하여의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(운영체제, 메모리, 관리, 페이징)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 3교시 #5 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(312,131,3,6,8,'비교/대조분석형','정보보호 및 개인정보보호 인증제도(ISMS, Information Security Management System)에 대하여 다음을 설명하시오.','["가. ISMS 와 ISMS-P 차이점", "나. ISMS 의무 대상 기준"]','["1. 리드문: 정보보호 및 개인정보보호 인증제도(ISMS, Information Security Management System)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보보호 및 개인정보보호 인증제도(ISMS, Information Security Management System) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ISMS 와 ISMS-P 차이점 및 ISMS 의무 대상 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','ISMS, Information Security Management Syste, ISMS-P, 정보보호, 개인정보보호, 인증제, 의무, 대상','{"headers": ["비교 항목", "정보보호 및 개인정보보호 인증제도(ISMS", "Information Security Management Syst"], "rows": [["핵심 개념·목적", "정보보호 및 개인정보보호 인증제도(ISMS의 고유 목적 및 적용 영역 정의", "Information Security Man의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제131회 3교시 6번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''정보보호 및 개인정보보호 인증제도(ISMS, Information Security Management System)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ISMS 와 ISMS-P 차이점 · ISMS 의무 대상 기준)을 필수 키워드(ISMS, Information Security Management Syste, ISMS-P, 정보보호)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 3교시 #6 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(313,131,4,1,7,'절차/설계구현형','전략적 기업경영(Strategic Enterprise Management)에 대하여 다음을 설명하시오.','["가. 전략적 기업경영의 정의", "나. 전략적 기업경영의 구성요소", "다. 전략적 기업경영의 구축 방안 및 구축 절차"]','["1. 리드문: 전략적 기업경영(Strategic Enterprise Management)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 전략적 기업경영(Strategic Enterprise Management) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 전략적 기업경영의 정의 및 전략적 기업경영의 구성요소 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Strategic Enterprise Management, 전략적, 기업경영, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 전략적 기업경영의 정의", "전략적 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 전략적 기업경영의 구성요소", "전략적 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 전략적 기업경영의 구축 방안 및 구축 절차", "전략적 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 4교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''전략적 기업경영(Strategic Enterprise Management)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(전략적 기업경영의 정의 · 전략적 기업경영의 구성요소 · 전략적 기업경영의 구축 방안 및 구축 절차)을 필수 키워드(Strategic Enterprise Management, 전략적, 기업경영, 거버넌스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 4교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(314,131,4,2,8,'개념/정의형','개인정보보호를 위한 ''개인정보의 안전성 확보조치 기준'' 고시 내용 중 다음을 설명하시오.','["가. 내부관리계획 수립.이행", "나. 암호화 적용방안"]','["1. 리드문: 개인정보보호를 위한 ''개인정보의 안전성 확보조치 기준'' 고시 내용 중의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개인정보보호를 위한 ''개인정보의 안전성 확보조치 기준'' 고시 내용 중 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 내부관리계획 수립.이행 및 암호화 적용방안 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','개인정보보호, 개인정보, 안전성, 확보조치, 고시, 내부관리계획, 수립, 이행','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 내부관리계획 수립.이행", "내부관리계획 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 암호화 적용방안", "암호화 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 4교시 2번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''개인정보보호를 위한 ''개인정보의 안전성 확보조치 기준'' 고시 내용 중''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(내부관리계획 수립.이행 · 암호화 적용방안)을 필수 키워드(개인정보보호, 개인정보, 안전성, 확보조치)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 4교시 #2 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(315,131,4,3,4,'개념/정의형','데이터 품질관리 아키텍처 (데이터 품질관리에 대하여 다음을 설명하시오)','["가. 데이터 품질관리 아키텍처", "나. 데이터 품질관리 성숙도", "다. 정형 데이터 및 비정형 데이터 품질기준", "라. 데이터 품질관리 전략"]','["1. 리드문: 데이터 품질관리 아키텍처 (데이터 품질관리에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 품질관리 아키텍처 (데이터 품질관리에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 품질관리 아키텍처 및 데이터 품질관리 성숙도 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','데이터, 품질관리, 아키텍처, 성숙, 정형, 비정형, 품질기준, 전략','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 데이터 품질관리 아키텍처", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 데이터 품질관리 성숙도", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 정형 데이터 및 비정형 데이터 품질기준", "정형 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 데이터 품질관리 전략", "데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 4교시 3번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''데이터 품질관리 아키텍처 (데이터 품질관리에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 품질관리 아키텍처 · 데이터 품질관리 성숙도 · 정형 데이터 및 비정형 데이터 품질기준)을 필수 키워드(데이터, 품질관리, 아키텍처, 성숙)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 4교시 #3 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(316,131,4,4,8,'법제도/거버넌스형','인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여 설명하시오.','["1. 인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','Foundation, 인공지능, 분야, 파운데이션, 모델, 기반기술, 구현시, 법적','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제131회 4교시 4번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인공지능 분야에서 파운데이션(Foundation) 모델의 개념, 특징, 기반기술 및 구현시 법적,환경적,사회적 측면의 고려사항에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Foundation, 인공지능, 분야, 파운데이션)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 4교시 #4 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(317,131,4,5,7,'법제도/거버넌스형','필요성과 산정방법 (소프트웨어 규모산정에 대하여 다음을 설명하시오)','["가. 필요성과 산정방법", "나. 규모산정 방식의 종류별 특징"]','["1. 리드문: 필요성과 산정방법 (소프트웨어 규모산정에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 필요성과 산정방법 (소프트웨어 규모산정에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 필요성과 산정방법 및 규모산정 방식의 종류별 특징 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','소프트웨어, 규모산정, 산정방법, 종류별, 거버넌스, ROI·성과지표, 리스크 관리','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 필요성과 산정방법", "산정방법 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 규모산정 방식의 종류별 특징", "규모산정 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 4교시 5번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''필요성과 산정방법 (소프트웨어 규모산정에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(필요성과 산정방법 · 규모산정 방식의 종류별 특징)을 필수 키워드(소프트웨어, 규모산정, 산정방법, 종류별)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 4교시 #5 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(318,131,4,6,2,'법제도/거버넌스형','정렬 알고리즘은 데이터Set이 주어졌을때, 이를 사용자가 지정한 기준에 맞게 순서대로 나열하여 재배치하는 기법이다. 정렬 알고리즘과 관련하여 다음에 대하여 설명하시오.','["가. 버블 정렬", "나. 삽입 정렬", "다. 퀵 정렬"]','["1. 리드문: 정렬 알고리즘과 관련하여 다음에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정렬 알고리즘과 관련하여 다음에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 버블 정렬 및 삽입 정렬 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Set, 정렬, 알고리즘, 데이터, 주어졌을때, 사용자, 지정한, 맞게','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 버블 정렬", "버블 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 삽입 정렬", "삽입 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 퀵 정렬", "정렬 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제131회 4교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''정렬 알고리즘과 관련하여 다음에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(버블 정렬 · 삽입 정렬 · 퀵 정렬)을 필수 키워드(Set, 정렬, 알고리즘, 데이터)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제131회 4교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(319,130,1,1,7,'개념/정의형','노코드 (no-code)','["1. 노코드 (no-code)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 노코드 (no-code)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 노코드 (no-code) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 노코드 (no-code) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','no-code, 노코드, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "노코드 (no-code)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "노코드 (no-code)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "노코드 (no-code)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "노코드 (no-code) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''노코드 (no-code)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(노코드 (no-code)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(no-code, 노코드, 거버넌스, ROI·성과지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(320,130,1,2,4,'개념/트랜잭션형','데이터베이스 병행 제어(Concurrency Control) 기법 및 필요성','["1. 병행 제어 미수행 시 발생하는 4대 이상 현상(갱신 손실, 현황 파악 오류, 모순성, 연쇄 복귀)", "2. 로킹(2PL), 타임스탬프, 낙관적 검증, 다중버전 병행제어(MVCC) 비교"]','["1. 리드문: 다중 트랜잭션 처리량(Throughput)과 일관성(ACID)의 조화 병행 제어", "2. 병행 제어 미보장 시 4대 문제점 및 MVCC 스냅샷 격리 동작 구조도", "3. 2단계 로킹(2PL) vs 타임스탬프(Timestamp) vs 낙관적 검증 vs MVCC 비교표", "4. 현대 RDBMS(PostgreSQL/Oracle/MySQL InnoDB)의 MVCC 기반 무잠금 읽기 최적화"]','갱신 손실(Lost Update), Dirty Read, Non-repeatable Read, Phantom Read, 2PL(확장·축소 단계), MVCC(다중버전 병행제어)','{"headers": ["병행 제어 기법", "동작 원리", "장점 및 단점"], "rows": [["2단계 로킹 (2PL)", "트랜잭션이 락을 획득만 하는 확장 단계와 해제만 하는 축소 단계로 구분", "직렬가능성(Serializability) 보장, 단 교착상태(Deadlock) 및 대기 지연 발생"], ["타임스탬프 순서 (Timestamp)", "트랜잭션 시작 시각 순서대로 데이터 접근 순서를 사전 결정", "교착상태 없음, 단 철회(Rollback) 및 연쇄 복귀 빈번 발생 가능"], ["MVCC (다중버전 병행제어)", "데이터 변경 시 Undo 영역에 이전 버전 스냅샷을 유지하여 일관된 읽기 제공", "읽기 작업과 쓰기 작업이 서로 블로킹하지 않아 동시성 극대화 (버전 공간 관리 필요)"]]}','데이터베이스 병행 제어는 다수의 트랜잭션이 동시에 동일한 데이터에 접근할 때 갱신 손실(Lost Update) 등 무결성 훼손을 방지하고 직렬가능성(Serializability)을 보장하는 기법이다. 현대 DBMS는 읽기 잠금 경합을 없애기 위해 Undo 스냅샷 기반의 MVCC(다중버전 병행제어)를 기본 채택하고 있다.','130회 1교시 병행제어 → 137회 3교시 트랜잭션 격리수준으로 연계 출제','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(321,130,1,3,2,'개념/정의형','요구사항명세서에 기술되어야 하는 항목 설명','["1. 요구사항명세서에 기술되어야 하는 항목 설명의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 요구사항명세서에 기술되어야 하는 항목 설명의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 요구사항명세서에 기술되어야 하는 항목 설명 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 요구사항명세서에 기술되어야 하는 항목 설명 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','요구사항명세서, 기술되어야, 항목, 설명, 품질속성, 유지보수성, 설계원칙','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "요구사항명세서에 기술되어야 하는 항목 설명의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "요구사항명세서에 기술되어야 하는 항목 설명의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "요구사항명세서에 기술되어야 하는 항목 설명의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "요구사항명세서에 기술되어야 하는 항목 설명 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''요구사항명세서에 기술되어야 하는 항목 설명''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(요구사항명세서에 기술되어야 하는 항목 설명의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(요구사항명세서, 기술되어야, 항목, 설명)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(322,130,1,4,4,'법제도/거버넌스형','데이터 거버넌스','["1. 데이터 거버넌스의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터 거버넌스의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 거버넌스 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 거버넌스 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','데이터, 거버넌스, 데이터 정합성, 성능·확장성, 인덱싱/분할, 무결성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터 거버넌스의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터 거버넌스의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터 거버넌스의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터 거버넌스 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 4번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''데이터 거버넌스''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 거버넌스의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(데이터, 거버넌스, 데이터 정합성, 성능·확장성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #4 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(323,130,1,5,3,'원인분석/대응전략형','드론의 보안위협과 대응방안','["1. 드론의 보안위협과 대응방안의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: 드론의 보안위협과 대응방안의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 드론의 보안위협과 대응방안 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 드론의 보안위협과 대응방안 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','드론, 보안위협, 대응방안, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "드론의 보안위협과 대응방안의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "드론의 보안위협과 대응방안의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "드론의 보안위협과 대응방안의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "드론의 보안위협과 대응방안 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 5번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''드론의 보안위협과 대응방안''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(드론의 보안위협과 대응방안의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(드론, 보안위협, 대응방안, 기밀성·무결성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #5 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
