INSERT INTO "questions" VALUES(325,130,1,7,5,'개념/정의형','6G 이동통신','["1. 6G 이동통신의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 6G 이동통신의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 6G 이동통신 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 6G 이동통신 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','이동통신, 프로토콜 스택, 대역폭·지연시간, 고가용성, 트래픽 제어','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "6G 이동통신의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "6G 이동통신의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "6G 이동통신의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "6G 이동통신 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 7번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''6G 이동통신''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(6G 이동통신의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(이동통신, 프로토콜 스택, 대역폭·지연시간, 고가용성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #7 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(326,130,1,8,5,'개념/클라우드가상화형','데이터센터 네트워크 가상화를 위한 오버레이 기술 VXLAN(Virtual eXtensible LAN)의 패킷 캡슐화 구조와 VLAN 한계 극복','["1. 기존 IEEE 802.1Q VLAN의 12비트 ID(4,094개) 한계와 STP 링크 차단 비효율 문제", "2. L3 UDP 위에서 L2 프레임을 캡슐화(MAC-in-UDP)하고 24비트 VNI로 1,600만 개 논리 망을 제공하는 VXLAN(VTEP) 원리"]','["1. 리드문: 핵심 개념 정의 및 출제 배경", "2. 아키텍처 및 동작 메커니즘 개념도", "3. 핵심 요소 및 대안 기술 비교표", "4. 실무 적용 고려사항 및 기술사적 제언"]','데이터센터 네트워크 가상화를 위한 오버레이 기술 VXLAN, 메커니즘, 비교분석, 트레이드오프, 실무거버넌스','{"headers": ["비교/구분 항목", "핵심 원리 및 구성요소", "실무 적용 및 검증 기준"], "rows": [["1. 기존 IEEE 802.1Q VLAN의 12비트 ID(4,094개) 한계와 STP 링크 차단 비효율 문제", "표준 메커니즘 및 핵심 구조 정의", "정합성·성능·보안 요구사항 검증"], ["2. L3 UDP 위에서 L2 프레임을 캡슐화(MAC-in-UDP)하고 24비트 VNI로 1,600만 개 논리 망을 제공하는 VXLAN(VTEP) 원리", "대안 기법과의 정량·정성적 트레이드오프 비교", "엔터프라이즈 운영 거버넌스 확립"]]}','데이터센터 네트워크 가상화를 위한 오버레이 기술 VXLAN(Virtual eXtensible LAN)의 패킷 캡슐화 구조와 VLAN 한계 극복 토픽은 정보관리기술사 핵심 기출 문항으로, (1) 정의와 필요성을 리드문으로 선언하고, (2) 메커니즘 구조도를 도식화한 뒤, (3) 1. 기존 IEEE 802.1Q VLAN의 12비트 ID(4,094개) 한계와 STP 링크 차단 비효율 문제 및 2. L3 UDP 위에서 L2 프레임을 캡슐화(MAC-in-UDP)하고 24비트 VNI로 1,600만 개 논리 망을 제공하는 VXLAN(VTEP) 원리를 대조표로 구조화하고, (4) 실무 적용 시 한계점과 극복 제언을 제시해야 한다.','제130회 주요 기출 및 도메인 순환 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(327,130,1,9,1,'개념/정의형','머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점','["1. 머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Optimization Algorithm, 머신러닝, 최적화, 알고리즘, 아키텍처, 성능지표, 학습·추론 최적화','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 9번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(머신러닝 최적화 알고리즘(Optimization Algorithm) 유형 및 장단점의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Optimization Algorithm, 머신러닝, 최적화, 알고리즘)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #9 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(328,130,1,10,7,'절차/설계구현형','정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)','["1. 정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','ISMP, 정보시스템마스터플랜, 기본, 구성, 단계별, 활동, 세부내용, 산출물','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 10번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보시스템마스터플랜(ISMP)의 기본 구성 내용(단계별 활동, 세부내용, 산출물)의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(ISMP, 정보시스템마스터플랜, 기본, 구성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #10 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(329,130,1,11,7,'절차/의사결정형','다기준 의사결정 기법 AHP(Analytic Hierarchy Process, 계층화 분석법)의 수행 절차와 일관성 비율(CR <= 0.1) 검증','["1. 목표 → 평가기준 → 대안의 계층 구조 설정 및 1~9점 척도 쌍대비교(Pairwise Comparison) 행렬 작성", "2. 고유벡터법을 통한 가중치 산출 및 논리적 모순을 검증하는 일관성 지수(CI)/일관성 비율(CR) 산출"]','["1. 리드문: 핵심 개념 정의 및 출제 배경", "2. 아키텍처 및 동작 메커니즘 개념도", "3. 핵심 요소 및 대안 기술 비교표", "4. 실무 적용 고려사항 및 기술사적 제언"]','다기준 의사결정 기법 AHP, 메커니즘, 비교분석, 트레이드오프, 실무거버넌스','{"headers": ["비교/구분 항목", "핵심 원리 및 구성요소", "실무 적용 및 검증 기준"], "rows": [["1. 목표 → 평가기준 → 대안의 계층 구조 설정 및 1~9점 척도 쌍대비교(Pairwise Comparison) 행렬 작성", "표준 메커니즘 및 핵심 구조 정의", "정합성·성능·보안 요구사항 검증"], ["2. 고유벡터법을 통한 가중치 산출 및 논리적 모순을 검증하는 일관성 지수(CI)/일관성 비율(CR) 산출", "대안 기법과의 정량·정성적 트레이드오프 비교", "엔터프라이즈 운영 거버넌스 확립"]]}','다기준 의사결정 기법 AHP(Analytic Hierarchy Process, 계층화 분석법)의 수행 절차와 일관성 비율(CR <= 0.1) 검증 토픽은 정보관리기술사 핵심 기출 문항으로, (1) 정의와 필요성을 리드문으로 선언하고, (2) 메커니즘 구조도를 도식화한 뒤, (3) 1. 목표 → 평가기준 → 대안의 계층 구조 설정 및 1~9점 척도 쌍대비교(Pairwise Comparison) 행렬 작성 및 2. 고유벡터법을 통한 가중치 산출 및 논리적 모순을 검증하는 일관성 지수(CI)/일관성 비율(CR) 산출를 대조표로 구조화하고, (4) 실무 적용 시 한계점과 극복 제언을 제시해야 한다.','제130회 주요 기출 및 도메인 순환 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(330,130,1,12,1,'개념/정의형','베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)','["1. 베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Bernoulli distribution, Geometric Distribution, 베르누, 분포, 기하, 아키텍처, 성능지표','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 12번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(베르누이 분포(Bernoulli distribution)와 기하 분포(Geometric Distribution)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Bernoulli distribution, Geometric Distribution, 베르누, 분포)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #12 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(331,130,1,13,7,'개념/정의형','ISO 21500 구성 모델','["1. ISO 21500 구성 모델의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: ISO 21500 구성 모델의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ISO 21500 구성 모델 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ISO 21500 구성 모델 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','ISO 21500, 구성, 모델, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "ISO 21500 구성 모델의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "ISO 21500 구성 모델의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "ISO 21500 구성 모델의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "ISO 21500 구성 모델 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 1교시 13번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''ISO 21500 구성 모델''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ISO 21500 구성 모델의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(ISO 21500, 구성, 모델, 거버넌스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 1교시 #13 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(332,130,2,1,1,'법제도/거버넌스형','데이터 마이닝의 기법 중 아래 기법에 대하여 설명하시오.','["1) K-means Clustering", "2) DBSCAN(Density Based Spatial Clustering of Applications with Noise)", "3) SVM(Support Vector Machine)"]','["1. 리드문: 데이터 마이닝의 기법 중 아래 기법에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 마이닝의 기법 중 아래 기법에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) K-means Clustering 및 2) DBSCAN(Density Based Spatial Cluste 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','K-means Clustering 2, DBSCAN, Density Based Spatial Clustering of A, pplications with Noise, SVM, Support Vector Machine, 데이터, 마이닝','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) K-means Clustering", "K-means Clustering 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) DBSCAN(Density Based Spatial Clustering of Applications with Noise)", "DBSCAN 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) SVM(Support Vector Machine)", "SVM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 2교시 1번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''데이터 마이닝의 기법 중 아래 기법에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) K-means Clustering · 2) DBSCAN(Density Based Spatial Clustering of Applications with Noise) · 3) SVM(Support Vector Machine))을 필수 키워드(K-means Clustering 2, DBSCAN, Density Based Spatial Clustering of A, pplications with Noise)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 2교시 #1 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(333,130,2,2,1,'개념/정의형','최근 데이터사이언스와 기계학습이 융합된 DSML(Data Science & Machine Learning) 프로젝트가 확산되고 있다. 성공적인 DSML프로젝트를 수행하기 위해 아래 항목을 설명하시오.','["1) DSML 프로젝트 수명주기", "2) 기계학습 운영화(Machine Learning Operationalizations/Operations : MLops)"]','["1. 리드문: 성공적인 DSML프로젝트를 수행하기 위해 아래 항목의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 성공적인 DSML프로젝트를 수행하기 위해 아래 항목 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) DSML 프로젝트 수명주기 및 2) 기계학습 운영화(Machine Learning Operation 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','DSML, Data Science & Machine Learning, Machine Learning Operationalizations, Operations, MLops, 데이터사이언스, 기계학습, 융합된','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) DSML 프로젝트 수명주기", "DSML 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 기계학습 운영화(Machine Learning Operationalizations/Operations : MLops)", "Machine Learning Operationalizations 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 2교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''성공적인 DSML프로젝트를 수행하기 위해 아래 항목''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) DSML 프로젝트 수명주기 · 2) 기계학습 운영화(Machine Learning Operationalizations/Operations : MLops))을 필수 키워드(DSML, Data Science & Machine Learning, Machine Learning Operationalizations, Operations)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 2교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(334,130,2,3,5,'절차/설계구현형','네트워크 서브네팅(subnetting)과 관련하여 아래 사항들을 설명하시오.','["1) 수퍼네팅(supernetting)과 서브네팅(subnetting) 개념을 설명하시오.", "2) 192.168.100.0/24 네트워크 대역을 동일한 IP 개수를 가진 4개의 서브넷(Subnet)으로 분할하고자 한다. 해당 절차에 대해서 상세히 설명하고, 서브넷 마스크 값을 구하시오. 그리고 하나의 서브넷에서 할당 가능한 IP 수량을 제시하시오."]','["1. 리드문: 네트워크 서브네팅(subnetting)과 관련하여 아래 사항들의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 네트워크 서브네팅(subnetting)과 관련하여 아래 사항들 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 수퍼네팅(supernetting)과 서브네팅(subnetting 및 2) 192.168.100.0/24 네트워크 대역을 동일한 IP 개수 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','subnetting, supernetting, IP, Subnet, 네트워크, 서브네팅, 아래, 사항들','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 수퍼네팅(supernetting)과 서브네팅(subnetting) 개념을 설명하시오.", "supernetting 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 192.168.100.0/24 네트워크 대역을 동일한 IP 개수를 가진 4개의 서브넷(Subnet)으로 분할하고자 한다. 해당 절", "IP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 2교시 3번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''네트워크 서브네팅(subnetting)과 관련하여 아래 사항들''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 수퍼네팅(supernetting)과 서브네팅(subnetting) 개념을 설명하시오. · 2) 192.168.100.0/24 네트워크 대역을 동일한 IP 개수를 가진 4개의 서브넷(Subnet)으로 분할하고자 한다. 해당 절차에 대해서 상세히 설명하고, 서브넷 마스크 값을 구하시오. 그리고 하나의 서브넷에서 할당 가능한 IP 수량을 제시하시오.)을 필수 키워드(subnetting, supernetting, IP, Subnet)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 2교시 #3 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(335,130,2,4,8,'법제도/거버넌스형','최근(2023년 2월 27일) 국회에서 개인정보보호법 개정안이 의결되었다. 이와 관련하여 아래 사항들을 설명하시오.','["1) 개인정보보호법 개정안 주요 내용", "2) 개인정보 관련 개별 주체들과 개인 정보 처리 흐름", "3) 개인정보 전송요구권과 AI 활용을 위한 자동화 의사결정 대응권"]','["1. 리드문: 이와 관련하여 아래 사항들의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이와 관련하여 아래 사항들 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 개인정보보호법 개정안 주요 내용 및 2) 개인정보 관련 개별 주체들과 개인 정보 처리 흐름 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','AI, 국회, 개인정보보호법, 개정안, 의결되었다, 아래, 사항들, 개인정보','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 개인정보보호법 개정안 주요 내용", "개인정보보호법 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 개인정보 관련 개별 주체들과 개인 정보 처리 흐름", "개인정보 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) 개인정보 전송요구권과 AI 활용을 위한 자동화 의사결정 대응권", "AI 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 2교시 4번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''이와 관련하여 아래 사항들''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 개인정보보호법 개정안 주요 내용 · 2) 개인정보 관련 개별 주체들과 개인 정보 처리 흐름 · 3) 개인정보 전송요구권과 AI 활용을 위한 자동화 의사결정 대응권)을 필수 키워드(AI, 국회, 개인정보보호법, 개정안)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 2교시 #4 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(336,130,2,5,8,'비교/대조분석형','과학기술정보통신부가 발표한 「메타버스 윤리원칙」에 대하여 다음을 설명하시오.','["1) 3대 지향가치와 8대 실천원칙", "2) 인터넷 윤리, 인공지능 윤리 및 메타버스 윤리 비교"]','["1. 리드문: 과학기술정보통신부가 발표한 「메타버스 윤리원칙」의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 과학기술정보통신부가 발표한 「메타버스 윤리원칙」 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 3대 지향가치와 8대 실천원칙 및 2) 인터넷 윤리, 인공지능 윤리 및 메타버스 윤리 비교 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','과학기술정보통신부, 발표한, 메타버스, 윤리원칙, 지향가치, 실천원칙, 인터넷, 윤리','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 3대 지향가치와 8대 실천원칙", "지향가치 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 인터넷 윤리, 인공지능 윤리 및 메타버스 윤리 비교", "인터넷 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 2교시 5번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''과학기술정보통신부가 발표한 「메타버스 윤리원칙」''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 3대 지향가치와 8대 실천원칙 · 2) 인터넷 윤리, 인공지능 윤리 및 메타버스 윤리 비교)을 필수 키워드(과학기술정보통신부, 발표한, 메타버스, 윤리원칙)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 2교시 #5 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(337,130,2,6,8,'원인분석/대응전략형','최근 디지털 역기능이 확산되고 있어 심각한 사회적 문제로 대두되고 있다. 디지털 역기능에 대하여 다음을 설명하시오.','["1) 디지털 역기능 개념과 사례", "2) 디지털 역기능 3대 이슈", "3) 대응방안"]','["1. 리드문: 디지털 역기능의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 디지털 역기능 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 디지털 역기능 개념과 사례 및 2) 디지털 역기능 3대 이슈 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','디지털, 역기능, 확산되고, 있어, 심각한, 사회적, 문제, 대두되고','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 디지털 역기능 개념과 사례", "디지털 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 디지털 역기능 3대 이슈", "디지털 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) 대응방안", "대응방안 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 2교시 6번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''디지털 역기능''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 디지털 역기능 개념과 사례 · 2) 디지털 역기능 3대 이슈 · 3) 대응방안)을 필수 키워드(디지털, 역기능, 확산되고, 있어)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 2교시 #6 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(338,130,3,1,1,'개념/정의형','머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델을 설명하시오.','["1. 머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Machine Learning, Decision Tree, 머신, 러닝, 활용되, 의사결정나무, 모델','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 3교시 1번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(머신 러닝(Machine Learning)에서 활용되는 의사결정나무(Decision Tree) 모델의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Machine Learning, Decision Tree, 머신, 러닝)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 3교시 #1 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(339,130,3,2,4,'비교/대조분석형','데이터저장 측면에서 파일, 데이터베이스, 블록체인을 비교하시오.','["1. 데이터저장 측면에서 파일, 데이터베이스, 블록체인을 비교하시오.의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 데이터저장 측면에서 파일, 데이터베이스, 블록체인을 비교하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터저장 측면에서 파일, 데이터베이스, 블록체인을 비교하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터저장 측면에서 파일, 데이터베이스, 블록체인을 비교하시오. 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','데이터저장, 파일, 데이터베이스, 블록체인, 비교하시오, 데이터 정합성, 성능·확장성','{"headers": ["비교 항목", "데이터저장 측면에서 파일", "데이터베이스", "블록체인을"], "rows": [["핵심 개념·목적", "데이터저장 측면에서 파일의 고유 목적 및 적용 영역 정의", "데이터베이스의 고유 목적 및 적용 영역 정의", "블록체인을의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제130회 3교시 2번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''데이터저장 측면에서 파일, 데이터베이스, 블록체인을 비교하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터저장 측면에서 파일, 데이터베이스, 블록체인을 비교하시오.의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(데이터저장, 파일, 데이터베이스, 블록체인)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 3교시 #2 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(340,130,3,3,5,'개념/정의형','TCP(Transmission Control Protocol)는 네트워크에 혼잡(Congestion)이 발생한 경우, 이를 해소하기 위한 다양한 메커니즘을 사용한다. 이와 관련하여 아래 사항들에 대해서 설명하시오.','["1) TCP 혼잡제어 메커니즘의 구성요소", "2) 혼잡상황 감지", "3) 혼잡상황 제어", "4) 혼잡 윈도우 크기"]','["1. 리드문: 이와 관련하여 아래 사항들에 대해서의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이와 관련하여 아래 사항들에 대해서 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) TCP 혼잡제어 메커니즘의 구성요소 및 2) 혼잡상황 감지 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','TCP, Transmission Control Protocol, Congestion, 네트워크, 혼잡, 발생한, 해소하기, 다양한','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) TCP 혼잡제어 메커니즘의 구성요소", "TCP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 혼잡상황 감지", "혼잡상황 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) 혼잡상황 제어", "혼잡상황 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["4) 혼잡 윈도우 크기", "혼잡 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 3교시 3번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''이와 관련하여 아래 사항들에 대해서''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) TCP 혼잡제어 메커니즘의 구성요소 · 2) 혼잡상황 감지 · 3) 혼잡상황 제어)을 필수 키워드(TCP, Transmission Control Protocol, Congestion, 네트워크)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 3교시 #3 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(341,130,3,4,1,'법제도/거버넌스형','최근 인공지능 기술 활용이 증가하면서 다양한 보안 위협이 증가하고 있다. 이와 관련하여 아래 사항들에 대하여 설명하시오.','["1) 머신러닝 학습과정에서의 적대적 공격 4가지와 방어기법", "2) 생성형 언어모델 기반의 인공지능 기술 활용 시 발생할 수 있는 보안취약점"]','["1. 리드문: 이와 관련하여 아래 사항들에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이와 관련하여 아래 사항들에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 머신러닝 학습과정에서의 적대적 공격 4가지와 방어기법 및 2) 생성형 언어모델 기반의 인공지능 기술 활용 시 발생할 수 있는 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','인공지능, 기술, 증가하면서, 다양한, 보안, 위협, 증가하고, 아래','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 머신러닝 학습과정에서의 적대적 공격 4가지와 방어기법", "머신러닝 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 생성형 언어모델 기반의 인공지능 기술 활용 시 발생할 수 있는 보안취약점", "생성형 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 3교시 4번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''이와 관련하여 아래 사항들에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 머신러닝 학습과정에서의 적대적 공격 4가지와 방어기법 · 2) 생성형 언어모델 기반의 인공지능 기술 활용 시 발생할 수 있는 보안취약점)을 필수 키워드(인공지능, 기술, 증가하면서, 다양한)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 3교시 #4 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(342,130,3,5,1,'원인분석/대응전략형','인공지능 등 지능정보 기술에 비현실적인 감리기준을 해결하기 위해 지능정보기술 감리 실무 가이드(한국지능정보사회진흥원, 2023년)를 발간했다. 그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여 설명하시오.','["1. 그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: 그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','인공지능, 지능정보, 기술, 비현실적인, 감리기준, 해결하기, 위해, 지능정보기술','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 3교시 5번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(그 중 빅데이터 정보화 사업의 분석·설계 단계별, 영역별 점검 항목에 대하여의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(인공지능, 지능정보, 기술, 비현실적인)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 3교시 #5 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(343,130,3,6,7,'개념/정의형','금융 클라우드 서비스를 받는 금융회사의 데이터는 가장 중요한 자산이며 민감정보를 다룬다. 금융 클라우드 SLA(Service Level Agreement)에 대하여 설명하시오.','["1) SLA의 개념", "2) 클라우드 SLA 가이드", "3) 금융 클라우드 SLA 가이드"]','["1. 리드문: 금융 클라우드 SLA(Service Level Agreement)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 금융 클라우드 SLA(Service Level Agreement)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) SLA의 개념 및 2) 클라우드 SLA 가이드 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','SLA, Service Level Agreement, 금융, 클라우드, 서비스, 금융회사, 데이터, 가장','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) SLA의 개념", "SLA 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 클라우드 SLA 가이드", "SLA 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) 금융 클라우드 SLA 가이드", "SLA 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 3교시 6번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''금융 클라우드 SLA(Service Level Agreement)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) SLA의 개념 · 2) 클라우드 SLA 가이드 · 3) 금융 클라우드 SLA 가이드)을 필수 키워드(SLA, Service Level Agreement, 금융, 클라우드)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 3교시 #6 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(344,130,4,1,1,'개념/정의형','음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.','["1. 음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오. 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','음성데이터, 마이닝, 기술, 가능, 분야, 발전, 방향, 기술하시오','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오. 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 4교시 1번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(음성데이터 마이닝의 정의, 목적, 주요 기술, 활용 가능 분야, 발전 방향에 대하여 기술하시오.의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(음성데이터, 마이닝, 기술, 가능)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 4교시 #1 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(345,130,4,2,3,'절차/설계구현형','최근 많은 범죄들이 지능화·고도화 되면서 디지털 포렌식의 중요성이 증가하고 있다. 이러한 디지털 포렌식과 관련하여 아래 사항을 설명하시오.','["1) 디지털 포렌식의 개념", "2) 디지털 포렌식의 유형과 절차", "3) 디지털 포렌식 기술 및 활용분야"]','["1. 리드문: 이러한 디지털 포렌식과 관련하여 아래 사항의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이러한 디지털 포렌식과 관련하여 아래 사항 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 디지털 포렌식의 개념 및 2) 디지털 포렌식의 유형과 절차 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','범죄들, 지능화, 고도화, 되면서, 디지털, 포렌식, 증가하고, 이러한','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 디지털 포렌식의 개념", "디지털 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 디지털 포렌식의 유형과 절차", "디지털 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) 디지털 포렌식 기술 및 활용분야", "디지털 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 4교시 2번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''이러한 디지털 포렌식과 관련하여 아래 사항''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 디지털 포렌식의 개념 · 2) 디지털 포렌식의 유형과 절차 · 3) 디지털 포렌식 기술 및 활용분야)을 필수 키워드(범죄들, 지능화, 고도화, 되면서)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 4교시 #2 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(346,130,4,3,3,'원인분석/대응전략형','최근 다수의 기업들이 클라우드 서비스를 도입하면서 다양한 보안 문제가 대두되고 있다. IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소를 설명하시오.','["1. IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','IT, 다수, 기업들, 클라우드, 서비스, 도입하면서, 다양한, 보안','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제130회 4교시 3번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(IT 담당자 입장에서 클라우드 서비스 도입 시 고려해야 할 보안 요소의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(IT, 다수, 기업들, 클라우드)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 4교시 #3 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(347,130,4,4,2,'법제도/거버넌스형','IT프로젝트를 성공적으로 수행하기 위해 요구사항의 체계적인 관리와 문서화가 매우 중요하다. 요구사항에 대하여 다음을 설명하시오.','["1) 소프트웨어(SW) 요구사항 품질속성", "2) 요구사항 도출기법", "3) 요구사항 개발"]','["1. 리드문: 요구사항의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 요구사항 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 소프트웨어(SW) 요구사항 품질속성 및 2) 요구사항 도출기법 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','IT, SW, 프로젝트, 성공적, 수행하기, 위해, 요구사항, 체계적인','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 소프트웨어(SW) 요구사항 품질속성", "SW 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 요구사항 도출기법", "요구사항 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) 요구사항 개발", "요구사항 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 4교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''요구사항''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 소프트웨어(SW) 요구사항 품질속성 · 2) 요구사항 도출기법 · 3) 요구사항 개발)을 필수 키워드(IT, SW, 프로젝트, 성공적)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 4교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(348,130,4,5,2,'실무/시나리오형','1) 웹3.0의 도입배경 및 개념 (웹3.0에 대하여 다음을 설명하시오)','["1) 웹3.0의 도입배경 및 개념", "2) 웹3.0의 주요특징 및 기술요소", "3) 웹3.0 기반의 서비스 활용 방안"]','["1. 리드문: 1) 웹3.0의 도입배경 및 개념 (웹3.0에 대하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 1) 웹3.0의 도입배경 및 개념 (웹3.0에 대하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 웹3.0의 도입배경 및 개념 및 2) 웹3.0의 주요특징 및 기술요소 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','도입배경, 주요특징, 기술요소, 서비스, 품질속성, 유지보수성, 설계원칙','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["1) 웹3.0의 도입배경 및 개념", "도입배경 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["2) 웹3.0의 주요특징 및 기술요소", "주요특징 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["3) 웹3.0 기반의 서비스 활용 방안", "서비스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제130회 4교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''1) 웹3.0의 도입배경 및 개념 (웹3.0에 대하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 웹3.0의 도입배경 및 개념 · 2) 웹3.0의 주요특징 및 기술요소 · 3) 웹3.0 기반의 서비스 활용 방안)을 필수 키워드(도입배경, 주요특징, 기술요소, 서비스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 4교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(349,130,4,6,2,'비교/대조분석형','데이터옵스(DataOps)와 데브옵스(DevOps)에 대하여 다음을 설명하시오.','["1) 데이터옵스와 데브옵스의 비교", "2) 데이터옵스 아키텍처 및 주요 기술"]','["1. 리드문: 데이터옵스(DataOps)와 데브옵스(DevOps)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터옵스(DataOps)와 데브옵스(DevOps) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 1) 데이터옵스와 데브옵스의 비교 및 2) 데이터옵스 아키텍처 및 주요 기술 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','DataOps, DevOps, 데이터옵스, 데브옵스, 아키텍처, 기술, 품질속성','{"headers": ["비교 항목", "데이터옵스(DataOps)", "데브옵스(DevOps)"], "rows": [["핵심 개념·목적", "데이터옵스(DataOps)의 고유 목적 및 적용 영역 정의", "데브옵스(DevOps)의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제130회 4교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''데이터옵스(DataOps)와 데브옵스(DevOps)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(1) 데이터옵스와 데브옵스의 비교 · 2) 데이터옵스 아키텍처 및 주요 기술)을 필수 키워드(DataOps, DevOps, 데이터옵스, 데브옵스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제130회 4교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(350,129,1,1,8,'개념/공공정책형','디지털플랫폼정부(DPG)의 4대 기본 원칙과 DPG 허브(민관 협력 혁신 인프라) 아키텍처','["1. 사일로화된 전자정부를 넘어선 국민·기업·정부 공동 가치 창출 디지털플랫폼정부 정의", "2. 데이터 레이크·초거대 AI·API 통합 테스트베드를 제공하는 DPG 허브 구조 및 보안 대책"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','디지털플랫폼정부, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["1. 사일로화된 전자정부를 넘어선 국민·기업·정부 공동 가치 창출 디지털플랫폼정부 정의", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["2. 데이터 레이크·초거대 AI·API 통합 테스트베드를 제공하는 DPG 허브 구조 및 보안 대책", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','디지털플랫폼정부(DPG)의 4대 기본 원칙과 DPG 허브(민관 협력 혁신 인프라) 아키텍처 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 1. 사일로화된 전자정부를 넘어선 국민·기업·정부 공동 가치 창출 디지털플랫폼정부 정의 및 2. 데이터 레이크·초거대 AI·API 통합 테스트베드를 제공하는 DPG 허브 구조 및 보안 대책을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제129회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(351,129,1,2,8,'법제도/거버넌스형','정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건','["1. 정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','정부, 인공지능, 윤리기준, 과학기술정보통신부, 제시한, 기본, 원칙, 요건','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제129회 1교시 2번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정부의 인공지능 윤리기준(과학기술정보통신부 2020.12.23)에서 제시한 인공지능의 3대 기본 원칙 및 10대 핵심 요건의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(정부, 인공지능, 윤리기준, 과학기술정보통신부)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #2 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(352,129,1,3,2,'개념/정의형','AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과','["1. AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','AOP, Aspect Oriented Programming, 구성, 기대효, 품질속성, 유지보수성, 설계원칙','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제129회 1교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(AOP(Aspect Oriented Programming)의 정의, 구성, 기대효과의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(AOP, Aspect Oriented Programming, 구성, 기대효)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(353,129,1,4,7,'비교/대조분석형','정보시스템 감리기준 고시(2021-4호, 2021.1.19)에 의거한 현장감리의 활동, 작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명','["1. 작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','PMO, Project Management Office, 정보시스템, 감리기준, 고시, 의거한, 현장감리, 활동','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제129회 1교시 4번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(작업 내용을 기술하고 PMO(Project Management Office)와의 차이점을 설명의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(PMO, Project Management Office, 정보시스템, 감리기준)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #4 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(354,129,1,5,1,'비교/머신러닝형','비지도 학습 군집화 알고리즘 K-Means Clustering과 DBSCAN 비교','["1. 거리 기반 분할 군집화 K-Means의 동작 절차와 한계", "2. 밀도 기반 군집화 DBSCAN(Eps, MinPts, Core/Border/Noise Point)과의 비교"]','["1. 리드문: 비지도 군집화(Clustering)의 양대 패러다임(중심점 거리 기반 vs 밀도 기반)", "2. K-Means(원형 군집) vs DBSCAN(비선형 기하학적 군집 및 노이즈 분리) 시각적 비교도", "3. K-Means vs DBSCAN vs 계층적 군집화 상세 비교표", "4. 실루엣 계수(Silhouette Coefficient)를 통한 군집 타당성 평가 및 이상치 탐지 응용"]','K-Means, 중심점(Centroid), 엘보우 기법(Elbow), DBSCAN, Eps(반경), MinPts(최소점수), Core/Border/Noise Point, 실루엣 계수','{"headers": ["비교 항목", "K-Means Clustering (중심점 기반)", "DBSCAN (밀도 기반)"], "rows": [["군집 수(K) 사전 지정", "사전에 군집 수 K를 반드시 지정해야 함 (Elbow/실루엣으로 탐색)", "군집 수를 사전에 지정할 필요 없음 (반경 Eps와 최소 데이터 수 MinPts만 설정)"], ["군집 형태 적응성", "구형(Spherical/원형) 군집만 정상 분리 가능 (오목·비선형 군집 취약)", "데이터 밀도를 따라 임의의 기하학적(초승달, 도넛형) 군집 완벽 분리"], ["이상치(Outlier) 민감도", "평균(중심점)을 계산하므로 이상치에 매우 민감하게 왜곡됨", "밀도가 낮은 외곽 데이터를 노이즈(Noise Point)로 자연스럽게 분리·제외"]]}','K-Means는 사전에 지정한 K개의 중심점(Centroid)과 데이터 간 유클리드 거리를 최소화하는 분할 군집화 기법으로 속도가 빠르나 이상치와 비선형 구조에 취약하다. 반면 DBSCAN은 반경(Eps) 내 최소 이웃 수(MinPts)라는 밀도 조건을 이용해 K값 지정 없이 임의 형태의 군집을 형성하고 노이즈(이상치)를 자동으로 걸러낸다.','129회 K-Means/DBSCAN → 130회 K-Means → 135회 실루엣 계수로 이어지는 빈출 클러스터','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(355,129,1,6,4,'개념/정의형','데이터베이스 트랜잭션(Transaction)의 특징','["1. 데이터베이스 트랜잭션(Transaction)의 특징의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터베이스 트랜잭션(Transaction)의 특징의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터베이스 트랜잭션(Transaction)의 특징 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터베이스 트랜잭션(Transaction)의 특징 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','Transaction, 데이터베이스, 트랜잭션, 데이터 정합성, 성능·확장성, 인덱싱/분할, 무결성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터베이스 트랜잭션(Transaction)의 특징의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터베이스 트랜잭션(Transaction)의 특징의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터베이스 트랜잭션(Transaction)의 특징의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터베이스 트랜잭션(Transaction)의 특징 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제129회 1교시 6번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''데이터베이스 트랜잭션(Transaction)의 특징''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터베이스 트랜잭션(Transaction)의 특징의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Transaction, 데이터베이스, 트랜잭션, 데이터 정합성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #6 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(356,129,1,7,2,'개념/정의형','소프트웨어 결합도(Coupling)의 종류','["1. 소프트웨어 결합도(Coupling)의 종류의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 소프트웨어 결합도(Coupling)의 종류의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 결합도(Coupling)의 종류 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 결합도(Coupling)의 종류 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Coupling, 소프트웨어, 결합, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "소프트웨어 결합도(Coupling)의 종류의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "소프트웨어 결합도(Coupling)의 종류의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "소프트웨어 결합도(Coupling)의 종류의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "소프트웨어 결합도(Coupling)의 종류 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제129회 1교시 7번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 결합도(Coupling)의 종류''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 결합도(Coupling)의 종류의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Coupling, 소프트웨어, 결합, 품질속성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #7 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(357,129,1,8,2,'비교/대조분석형','화이트박스 테스트(White Box Test)와 블랙박스 테스트(Black Box Test)의 비교','["1. 화이트박스 테스트(White Box Test)와 블랙박스 테스트(Black Box Test)의 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 화이트박스 테스트(White Box Test)와 블랙박스 테스트(Black Box Test)의 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 화이트박스 테스트(White Box Test)와 블랙박스 테스트(Black Box Test)의 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 화이트박스 테스트(White Box Test)와 블랙박스 테스트(Black Box Test)의 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','White Box Test, Black Box Test, 화이트박스, 테스트, 블랙박스, 품질속성, 유지보수성','{"headers": ["비교 항목", "화이트박스 테스트(White Box Test)", "블랙박스 테스트(Black Box Test)"], "rows": [["핵심 개념·목적", "화이트박스 테스트(White Box Test의 고유 목적 및 적용 영역 정의", "블랙박스 테스트(Black Box Test)의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제129회 1교시 8번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''화이트박스 테스트(White Box Test)와 블랙박스 테스트(Black Box Test)의 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(화이트박스 테스트(White Box Test)와 블랙박스 테스트(Black Box Test)의 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(White Box Test, Black Box Test, 화이트박스, 테스트)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #8 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(358,129,1,9,2,'개념/정의형','객체지향 프로그래밍의 캡슐화(Encapsulation)','["1. 객체지향 프로그래밍의 캡슐화(Encapsulation)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 객체지향 프로그래밍의 캡슐화(Encapsulation)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 객체지향 프로그래밍의 캡슐화(Encapsulation) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 객체지향 프로그래밍의 캡슐화(Encapsulation) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Encapsulation, 객체지향, 프로그래밍, 캡슐화, 품질속성, 유지보수성, 설계원칙','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "객체지향 프로그래밍의 캡슐화(Encapsulation)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "객체지향 프로그래밍의 캡슐화(Encapsulation)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "객체지향 프로그래밍의 캡슐화(Encapsulation)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "객체지향 프로그래밍의 캡슐화(Encapsulation) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제129회 1교시 9번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''객체지향 프로그래밍의 캡슐화(Encapsulation)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(객체지향 프로그래밍의 캡슐화(Encapsulation)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Encapsulation, 객체지향, 프로그래밍, 캡슐화)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #9 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
