INSERT INTO "questions" VALUES(362,129,1,13,2,'개념/정의형','트리정렬(Tree Sort)','["1. 트리정렬(Tree Sort)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 트리정렬(Tree Sort)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 트리정렬(Tree Sort) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 트리정렬(Tree Sort) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Tree Sort, 트리정렬, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "트리정렬(Tree Sort)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "트리정렬(Tree Sort)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "트리정렬(Tree Sort)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "트리정렬(Tree Sort) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제129회 1교시 13번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''트리정렬(Tree Sort)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(트리정렬(Tree Sort)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Tree Sort, 트리정렬, 품질속성, 유지보수성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 1교시 #13 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(363,129,2,1,5,'개념/정의형','가상화(Virtualization)에 대하여 다음을 설명하시오.','["가. 일반적인 운영 체제의 프로그램 동작방식", "나. 응용 프로그램 가상화 동작방식", "다. 원격 데스크톱 프로토콜의 종류"]','["1. 리드문: 가상화(Virtualization)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 가상화(Virtualization) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 일반적인 운영 체제의 프로그램 동작방식 및 응용 프로그램 가상화 동작방식 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Virtualization, 가상화, 일반적인, 운영, 체제, 프로그램, 동작방식, 응용','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 일반적인 운영 체제의 프로그램 동작방식", "일반적인 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 응용 프로그램 가상화 동작방식", "응용 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 원격 데스크톱 프로토콜의 종류", "원격 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제129회 2교시 1번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''가상화(Virtualization)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(일반적인 운영 체제의 프로그램 동작방식 · 응용 프로그램 가상화 동작방식 · 원격 데스크톱 프로토콜의 종류)을 필수 키워드(Virtualization, 가상화, 일반적인, 운영)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제129회 2교시 #1 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
