INSERT INTO "questions" VALUES(488,125,1,12,5,'개념/정의형','SDR(Software Defined Radio)','["1. SDR(Software Defined Radio)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: SDR(Software Defined Radio)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: SDR(Software Defined Radio) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: SDR(Software Defined Radio) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','SDR, Software Defined Radio, 프로토콜 스택, 대역폭·지연시간, 고가용성, 트래픽 제어','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "SDR(Software Defined Radio)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "SDR(Software Defined Radio)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "SDR(Software Defined Radio)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "SDR(Software Defined Radio) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 1교시 12번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''SDR(Software Defined Radio)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(SDR(Software Defined Radio)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(SDR, Software Defined Radio, 프로토콜 스택, 대역폭·지연시간)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 1교시 #12 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(489,125,1,13,2,'개념/정의형','소프트웨어 형상관리','["1. 소프트웨어 형상관리의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 소프트웨어 형상관리의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 형상관리 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 형상관리 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','소프트웨어, 형상관리, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "소프트웨어 형상관리의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "소프트웨어 형상관리의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "소프트웨어 형상관리의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "소프트웨어 형상관리 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 1교시 13번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 형상관리''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 형상관리의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(소프트웨어, 형상관리, 품질속성, 유지보수성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 1교시 #13 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(490,125,2,1,7,'법제도/거버넌스형','대부분 공공부문 소프트웨어 사업에 ISMP(Information System Master Plan)를 적용 하고 있다. ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물을 설명하시오.','["1. ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','ISMP, Information System Master Plan, 대부분, 공공부문, 소프트웨어, 사업, 하고, 방법론','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 2교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ISMP의 방법론 체계를 설명하고, 정보시스템 구축사업 이행방안 수립 절차와 산출물의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(ISMP, Information System Master Plan, 대부분, 공공부문)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 2교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(491,125,2,2,7,'법제도/거버넌스형','프로젝트 획득가치관리(Earned Value Management) 보고서의 EV(Earned Value)가 500만원, PV(Planned Value)가 600만원 그리고 AC(Actual Cost)가 450만원일 때, 다음을 설명하시오.','["가. 획득가치관리를 분석하고, 일정과 비용에 대한 위험(Risk)요소를 설명하시오.", "나. 부정적인 위험대응 방법을 설명하고, 일정과 비용에 대한 부정적인 위험대응 방안을 예시로 설명하시오."]','["1. 리드문: 프로젝트 획득가치관리(Earned Value Management) 보고서의 EV(Earned Value)가 500만원, PV(Planned Value)가 600만원 그리고 AC(Actual Cost)가 450만원일 때,의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 프로젝트 획득가치관리(Earned Value Management) 보고서의 EV(Earned Value)가 500만원, PV(Planned Value)가 600만원 그리고 AC(Actual Cost)가 450만원일 때, 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 획득가치관리를 분석하고, 일정과 비용에 대한 위험(Risk)요소를 설 및 부정적인 위험대응 방법을 설명하고, 일정과 비용에 대한 부정적인 위험 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Earned Value Management, EV, Earned Value, PV, Planned Value, AC, Actual Cost, Risk','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 획득가치관리를 분석하고, 일정과 비용에 대한 위험(Risk)요소를 설명하시오.", "Risk 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 부정적인 위험대응 방법을 설명하고, 일정과 비용에 대한 부정적인 위험대응 방안을 예시로 설명하시오.", "부정적인 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 2교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''프로젝트 획득가치관리(Earned Value Management) 보고서의 EV(Earned Value)가 500만원, PV(Planned Value)가 600만원 그리고 AC(Actual Cost)가 450만원일 때,''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(획득가치관리를 분석하고, 일정과 비용에 대한 위험(Risk)요소를 설명하시오. · 부정적인 위험대응 방법을 설명하고, 일정과 비용에 대한 부정적인 위험대응 방안을 예시로 설명하시오.)을 필수 키워드(Earned Value Management, EV, Earned Value, PV)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 2교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(492,125,2,3,6,'개념/정의형','병렬처리 시스템의 상호연결망(Interconnection Network)에 대해 다음을 설명하시오.','["가. 상호연결망의 개념과 종류", "나. 토러스(Torus) 구조"]','["1. 리드문: 병렬처리 시스템의 상호연결망(Interconnection Network)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 병렬처리 시스템의 상호연결망(Interconnection Network) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 상호연결망의 개념과 종류 및 토러스(Torus) 구조 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','Interconnection Network, Torus, 병렬처리, 시스템, 상호연결망, 대해, 토러스','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 상호연결망의 개념과 종류", "상호연결망 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 토러스(Torus) 구조", "Torus 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 2교시 3번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''병렬처리 시스템의 상호연결망(Interconnection Network)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(상호연결망의 개념과 종류 · 토러스(Torus) 구조)을 필수 키워드(Interconnection Network, Torus, 병렬처리, 시스템)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 2교시 #3 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(493,125,2,4,3,'원인분석/대응전략형','구현단계에서 발생 가능한 코딩 보안 약점인 검사시점과 사용시점(TOCTOU)에 대하여 다음을 설명하시오.','["가. TOCTOU의 정의와 개념", "나. 문제가 발생하는 상황과 보안대책", "다. TOCTOU 관점에서 아래 코드 실행시 발생가능한 문제점을 설명하고, 해결방안을 제시하시오.", "static volatile double account; void deposit(int amount) { account += amount; } void withdraw(int amount) { account -= amount; }"]','["1. 리드문: 구현단계에서 발생 가능한 코딩 보안 약점인 검사시점과 사용시점(TOCTOU)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 구현단계에서 발생 가능한 코딩 보안 약점인 검사시점과 사용시점(TOCTOU) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: TOCTOU의 정의와 개념 및 문제가 발생하는 상황과 보안대책 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','TOCTOU, static volatile double account, void deposit, int amount, account, amount, void withdraw, 구현단계','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. TOCTOU의 정의와 개념", "TOCTOU 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 문제가 발생하는 상황과 보안대책", "문제 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. TOCTOU 관점에서 아래 코드 실행시 발생가능한 문제점을 설명하고, 해결방안을 제시하시오.", "TOCTOU 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["static volatile double account; void deposit(int amount) { account += amoun", "static volatile double account 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 2교시 4번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''구현단계에서 발생 가능한 코딩 보안 약점인 검사시점과 사용시점(TOCTOU)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(TOCTOU의 정의와 개념 · 문제가 발생하는 상황과 보안대책 · TOCTOU 관점에서 아래 코드 실행시 발생가능한 문제점을 설명하고, 해결방안을 제시하시오.)을 필수 키워드(TOCTOU, static volatile double account, void deposit, int amount)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 2교시 #4 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(494,125,2,5,3,'원인분석/대응전략형','EMP공격(ElectroMagnetic Pulse attack)에 대하여 다음 물음에 답하시오.','["가. EMP공격의 정의와 구분", "나. HEMP(High altitude EMP)의 원리", "다. EMP공격의 위협을 정의하고 위협별 방호 방안 제시"]','["1. 리드문: EMP공격(ElectroMagnetic Pulse attack)에 대하여 다음 물음에 답하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: EMP공격(ElectroMagnetic Pulse attack)에 대하여 다음 물음에 답하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: EMP공격의 정의와 구분 및 HEMP(High altitude EMP)의 원리 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','EMP, ElectroMagnetic Pulse attack, HEMP, High altitude EMP, 공격, 물음, 위협, 정의하고','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. EMP공격의 정의와 구분", "EMP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. HEMP(High altitude EMP)의 원리", "HEMP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. EMP공격의 위협을 정의하고 위협별 방호 방안 제시", "EMP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 2교시 5번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''EMP공격(ElectroMagnetic Pulse attack)에 대하여 다음 물음에 답하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(EMP공격의 정의와 구분 · HEMP(High altitude EMP)의 원리 · EMP공격의 위협을 정의하고 위협별 방호 방안 제시)을 필수 키워드(EMP, ElectroMagnetic Pulse attack, HEMP, High altitude EMP)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 2교시 #5 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(495,125,2,6,2,'법제도/거버넌스형','소프트웨어의 시험(Test)에 사용되는 다음의 기법에 대해 설명하시오.','["가. 블랙박스(Black Box) 시험", "나. 화이트박스(White Box) 시험"]','["1. 리드문: 소프트웨어의 시험(Test)에 사용되는 다음의 기법에 대해의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어의 시험(Test)에 사용되는 다음의 기법에 대해 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 블랙박스(Black Box) 시험 및 화이트박스(White Box) 시험 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Test, Black Box, White Box, 소프트웨어, 시험, 사용되, 대해, 블랙박스','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 블랙박스(Black Box) 시험", "Black Box 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 화이트박스(White Box) 시험", "White Box 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 2교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어의 시험(Test)에 사용되는 다음의 기법에 대해''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(블랙박스(Black Box) 시험 · 화이트박스(White Box) 시험)을 필수 키워드(Test, Black Box, White Box, 소프트웨어)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 2교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(496,125,3,1,2,'법제도/거버넌스형','배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법을 설명하시오.','["1. 배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Queue, 배열, 이용하여, 구성할, 단점, 품질속성, 유지보수성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 3교시 1번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(배열을 이용하여 큐(Queue)를 구성할 때의 단점과 해결 방법의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Queue, 배열, 이용하여, 구성할)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 3교시 #1 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(497,125,3,2,7,'법제도/거버넌스형','IT 프로젝트의 위험도가 크거나 대규모 사업은 상주감리 제도를 적용할 수 있다. 상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계를 설명하시오.','["1. 상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IT, PMO, Project Management Office, 프로젝트, 위험도, 크거나, 대규모, 사업','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 3교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(상주감리 업무 수행 범위와 절차를 설명하고, PMO(Project Management Office)와의 연관관계의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(IT, PMO, Project Management Office, 프로젝트)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 3교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(498,125,3,3,5,'개념/정의형','QoS(Quality of Service) 방식인 DiffServ와 IntServ를 설명하시오.','["1. QoS(Quality of Service) 방식인 DiffServ와 IntServ의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: QoS(Quality of Service) 방식인 DiffServ와 IntServ의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: QoS(Quality of Service) 방식인 DiffServ와 IntServ 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: QoS(Quality of Service) 방식인 DiffServ와 IntServ 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','QoS, Quality of Service, DiffServ, IntServ, 방식인, 프로토콜 스택, 대역폭·지연시간','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "QoS(Quality of Service) 방식인 DiffServ와 IntServ의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "QoS(Quality of Service) 방식인 DiffServ와 IntServ의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "QoS(Quality of Service) 방식인 DiffServ와 IntServ의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "QoS(Quality of Service) 방식인 DiffServ와 IntServ 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 3교시 3번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''QoS(Quality of Service) 방식인 DiffServ와 IntServ''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(QoS(Quality of Service) 방식인 DiffServ와 IntServ의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(QoS, Quality of Service, DiffServ, IntServ)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 3교시 #3 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(499,125,3,4,8,'원인분석/대응전략형','인공지능(AI) 기술이 확산됨에 따라 개인정보 침해 등 다양한 사회적 문제 발생 우려가 높아졌다. 이를 대응하기 위하여, 최근 개인정보보호위원회에서 인공지능(AI) 개인정보보호 자율점검표를 확정하였다. 인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도를 설명하시오.','["1. 인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: 인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','AI, 인공지능, 기술, 확산됨, 따라, 개인정보, 침해, 다양한','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 3교시 4번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인공지능(AI) 개인정보보호 자율점검표의 원칙과 총괄흐름도의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(AI, 인공지능, 기술, 확산됨)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 3교시 #4 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(500,125,3,5,3,'개념/정의형','JASON Web Token에 대하여 다음을 설명하시오.','["가. JASON Web Token의 개념", "나. JASON Web Token의 구성과 인증 메커니즘", "다. JASON Web Token의 장․단점과 활용방안"]','["1. 리드문: JASON Web Token의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: JASON Web Token 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: JASON Web Token의 개념 및 JASON Web Token의 구성과 인증 메커니즘 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','JASON Web Token, 구성, 인증, 메커니즘, 단점, 활용방안, 기밀성·무결성','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. JASON Web Token의 개념", "JASON Web Token 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. JASON Web Token의 구성과 인증 메커니즘", "JASON Web Token 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. JASON Web Token의 장․단점과 활용방안", "JASON Web Token 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 3교시 5번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''JASON Web Token''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(JASON Web Token의 개념 · JASON Web Token의 구성과 인증 메커니즘 · JASON Web Token의 장․단점과 활용방안)을 필수 키워드(JASON Web Token, 구성, 인증, 메커니즘)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 3교시 #5 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(501,125,3,6,7,'법제도/거버넌스형','IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오. (IT 투자평가 기법에 대하여 다음 물음에 답하시오)','["가. IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오.", "나. 매출증대의 재무적 목표 달성을 위해 고객에게 배송시간 절감과 만족도 증가를 제공하려는 기업의 BSC(Balanced Score Card) 전략맵을 작성하시오."]','["1. 리드문: IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오. (IT 투자평가 기법에 대하여 다음 물음에 답하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오. (IT 투자평가 기법에 대하여 다음 물음에 답하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오. 및 매출증대의 재무적 목표 달성을 위해 고객에게 배송시간 절감과 만족도 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IT, BSC, Balanced Score Card, 투자평, 물음, 투자, 평가, 정량적','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오.", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 매출증대의 재무적 목표 달성을 위해 고객에게 배송시간 절감과 만족도 증가를 제공하려는 기업의 BSC(Balanced Score C", "BSC 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 3교시 6번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오. (IT 투자평가 기법에 대하여 다음 물음에 답하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(IT 투자 평가의 정량적 및 정성적 평가 항목 및 내용을 설명하시오. · 매출증대의 재무적 목표 달성을 위해 고객에게 배송시간 절감과 만족도 증가를 제공하려는 기업의 BSC(Balanced Score Card) 전략맵을 작성하시오.)을 필수 키워드(IT, BSC, Balanced Score Card, 투자평)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 3교시 #6 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(502,125,4,1,7,'실무/시나리오형','금융 환경의 변화로 최근 은행권 공동 오픈 플랫폼을 구축하여 핀테크서비스가 활성화 되고 있다. 다음 내용에 대하여 설명하시오.','["가. 오픈 플랫폼의 개념", "나. 오픈 플랫폼의 주요기술인 Open API", "다. 오픈 플랫폼의 제공 기능"]','["1. 리드문: 금융 환경의 변화로 최근 은행권 공동 오픈 플랫폼을 구축하여 핀테크서비스가 활성화 되고 있다. 다음 내용에 대하여 설명하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 금융 환경의 변화로 최근 은행권 공동 오픈 플랫폼을 구축하여 핀테크서비스가 활성화 되고 있다. 다음 내용에 대하여 설명하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 오픈 플랫폼의 개념 및 오픈 플랫폼의 주요기술인 Open API 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Open API, 금융, 환경, 변화, 은행권, 공동, 오픈, 플랫폼','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 오픈 플랫폼의 개념", "오픈 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 오픈 플랫폼의 주요기술인 Open API", "Open API 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 오픈 플랫폼의 제공 기능", "오픈 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 4교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''금융 환경의 변화로 최근 은행권 공동 오픈 플랫폼을 구축하여 핀테크서비스가 활성화 되고 있다. 다음 내용에 대하여 설명하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(오픈 플랫폼의 개념 · 오픈 플랫폼의 주요기술인 Open API · 오픈 플랫폼의 제공 기능)을 필수 키워드(Open API, 금융, 환경, 변화)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 4교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(503,125,4,2,1,'개념/정의형','정보통신분야 정보이론(Information Theory)과 샤논(Shannon)의 정리에 대하여 다음을 설명하시오.','["가. 정보이론의 개념", "나. 샤논의 제1정리 및 제2정리", "다. 샤논-하틀리(Shannon-Hartley)의 정리"]','["1. 리드문: 정보통신분야 정보이론(Information Theory)과 샤논(Shannon)의 정리의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보통신분야 정보이론(Information Theory)과 샤논(Shannon)의 정리 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보이론의 개념 및 샤논의 제1정리 및 제2정리 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Information Theory, Shannon, Shannon-Hartley, 정보통신분야, 정보이론, 샤논, 정리, 하틀리','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 정보이론의 개념", "정보이론 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 샤논의 제1정리 및 제2정리", "샤논 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 샤논-하틀리(Shannon-Hartley)의 정리", "Shannon-Hartley 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 4교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''정보통신분야 정보이론(Information Theory)과 샤논(Shannon)의 정리''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보이론의 개념 · 샤논의 제1정리 및 제2정리 · 샤논-하틀리(Shannon-Hartley)의 정리)을 필수 키워드(Information Theory, Shannon, Shannon-Hartley, 정보통신분야)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 4교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(504,125,4,3,1,'개념/정의형','한 공장에서 스마트 팩토리(Smart Factory) 적용을 통한 생산시간 단축을 확인하려고 한다. 기존 공정에서의 제품 생산시간이 정규분포를 따르며 평균이 30분, 표준 편차가 5분인 것으로 알려져 있다. 스마트 팩토리가 적용된 공정의 제품에 대한 생산시간을 49개 랜덤 추출하여 관측한 결과 평균이 28.5분이었다. 스마트 팩토리가 적용된 공정의 생산시간이 표준편차가 5분인 정규분포를 따른다고 할 때, 스마트 팩토리를 통해 생산 시간이 단축되었는지 가설을 설정하고 검정하시오. (단, 유의수준 5%, Z0.05=1.645)','["1. (단, 유의수준 5%, Z0.05=1.645)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: (단, 유의수준 5%, Z0.05=1.645)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: (단, 유의수준 5%, Z0.05=1.645) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: (단, 유의수준 5%, Z0.05=1.645) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Smart Factory, Z0, 공장, 스마트, 팩토리, 생산시간, 단축, 확인하려고','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "(단, 유의수준 5%, Z0.05=1.645)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "(단, 유의수준 5%, Z0.05=1.645)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "(단, 유의수준 5%, Z0.05=1.645)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "(단, 유의수준 5%, Z0.05=1.645) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제125회 4교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''(단, 유의수준 5%, Z0.05=1.645)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항((단, 유의수준 5%, Z0.05=1.645)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Smart Factory, Z0, 공장, 스마트)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 4교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(505,125,4,4,2,'개념/정의형','방향성 비순환 그래프(Directed Acyclic Graph)에 대하여 다음 물음에 답하시오.','["가. 방향성 비순환 그래프의 개념과 특징", "나. 아래 방향성 비순환 그래프에 대하여 위상정렬(Topology Sort)을 실시하고 결과값 제시"]','["1. 리드문: 방향성 비순환 그래프(Directed Acyclic Graph)에 대하여 다음 물음에 답하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 방향성 비순환 그래프(Directed Acyclic Graph)에 대하여 다음 물음에 답하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 방향성 비순환 그래프의 개념과 특징 및 아래 방향성 비순환 그래프에 대하여 위상정렬(Topology Sort 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Directed Acyclic Graph, Topology Sort, 방향성, 비순환, 그래프, 물음, 아래, 위상정렬','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 방향성 비순환 그래프의 개념과 특징", "방향성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 아래 방향성 비순환 그래프에 대하여 위상정렬(Topology Sort)을 실시하고 결과값 제시", "Topology Sort 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 4교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''방향성 비순환 그래프(Directed Acyclic Graph)에 대하여 다음 물음에 답하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(방향성 비순환 그래프의 개념과 특징 · 아래 방향성 비순환 그래프에 대하여 위상정렬(Topology Sort)을 실시하고 결과값 제시)을 필수 키워드(Directed Acyclic Graph, Topology Sort, 방향성, 비순환)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 4교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(506,125,4,5,2,'비교/대조분석형','절차지향 프로그래밍(Procedure Oriented Programming) 방법과 객체지향 프로그래밍 (Object Oriented Programming) 방법을 비교 설명하시오.','["1. 절차지향 프로그래밍(Procedure Oriented Programming) 방법과 객체지향 프로그래밍 (Object Oriented Programming) 방법의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 절차지향 프로그래밍(Procedure Oriented Programming) 방법과 객체지향 프로그래밍 (Object Oriented Programming) 방법의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 절차지향 프로그래밍(Procedure Oriented Programming) 방법과 객체지향 프로그래밍 (Object Oriented Programming) 방법 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 절차지향 프로그래밍(Procedure Oriented Programming) 방법과 객체지향 프로그래밍 (Object Oriented Programming) 방법 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Procedure Oriented Programming, Object Oriented Programming, 절차지향, 프로그래밍, 객체지향, 품질속성, 유지보수성','{"headers": ["비교 항목", "절차지향 프로그래밍(Procedure Oriented Progra", "객체지향 프로그래밍 (Object Oriented Programm"], "rows": [["핵심 개념·목적", "절차지향 프로그래밍(Procedure Ori의 고유 목적 및 적용 영역 정의", "객체지향 프로그래밍 (Object Orien의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제125회 4교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''절차지향 프로그래밍(Procedure Oriented Programming) 방법과 객체지향 프로그래밍 (Object Oriented Programming) 방법''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(절차지향 프로그래밍(Procedure Oriented Programming) 방법과 객체지향 프로그래밍 (Object Oriented Programming) 방법의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Procedure Oriented Programming, Object Oriented Programming, 절차지향, 프로그래밍)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 4교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(507,125,4,6,6,'개념/정의형','산업제어시스템(Industrial Control System)의 퍼듀(Purdue) 모델에 대하여 다음을 설명하시오.','["가. 퍼듀 모델의 개념", "나. 퍼듀 모델의 계층과 계층별 특징"]','["1. 리드문: 산업제어시스템(Industrial Control System)의 퍼듀(Purdue) 모델의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 산업제어시스템(Industrial Control System)의 퍼듀(Purdue) 모델 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 퍼듀 모델의 개념 및 퍼듀 모델의 계층과 계층별 특징 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','Industrial Control System, Purdue, 산업제어시스템, 퍼듀, 모델, 계층, 계층별','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 퍼듀 모델의 개념", "퍼듀 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 퍼듀 모델의 계층과 계층별 특징", "퍼듀 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제125회 4교시 6번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''산업제어시스템(Industrial Control System)의 퍼듀(Purdue) 모델''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(퍼듀 모델의 개념 · 퍼듀 모델의 계층과 계층별 특징)을 필수 키워드(Industrial Control System, Purdue, 산업제어시스템, 퍼듀)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제125회 4교시 #6 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(508,124,1,1,7,'비교/대조분석형','가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교','["1. 가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Value-chain, ERP, SCM, MES, CRM, 가치사슬, 거버넌스','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제124회 1교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(가치사슬(Value-chain) 관점에서 ERP, SCM, MES, CRM 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Value-chain, ERP, SCM, MES)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제124회 1교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(509,124,1,2,1,'비교/대조분석형','통계학의 4가지 척도를 구분하고, 이 관점에서 다중회귀분석(Multiple Regression Analysis)과 로지스틱회귀분석(Logistic Regression Analysis) 비교','["1. 통계학의 4가지 척도를 구분하고, 이 관점에서 다중회귀분석(Multiple Regression Analysis)과 로지스틱회귀분석(Logistic Regression Analysis) 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 통계학의 4가지 척도를 구분하고, 이 관점에서 다중회귀분석(Multiple Regression Analysis)과 로지스틱회귀분석(Logistic Regression Analysis) 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 통계학의 4가지 척도를 구분하고, 이 관점에서 다중회귀분석(Multiple Regression Analysis)과 로지스틱회귀분석(Logistic Regression Analysis) 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 통계학의 4가지 척도를 구분하고, 이 관점에서 다중회귀분석(Multiple Regression Analysis)과 로지스틱회귀분석(Logistic Regression Analysis) 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Multiple Regression Analysis, Logistic Regression Analysis, 통계학, 척도, 구분하고, 다중회귀분석, 로지스틱회귀분석','{"headers": ["비교 항목", "통계학의 4가지 척도를 구분하고", "이 관점에서 다중회귀분석(Multiple Regression An"], "rows": [["핵심 개념·목적", "통계학의 4가지 척도를 구분하고의 고유 목적 및 적용 영역 정의", "이 관점에서 다중회귀분석(Multiple R의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제124회 1교시 2번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''통계학의 4가지 척도를 구분하고, 이 관점에서 다중회귀분석(Multiple Regression Analysis)과 로지스틱회귀분석(Logistic Regression Analysis) 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(통계학의 4가지 척도를 구분하고, 이 관점에서 다중회귀분석(Multiple Regression Analysis)과 로지스틱회귀분석(Logistic Regression Analysis) 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Multiple Regression Analysis, Logistic Regression Analysis, 통계학, 척도)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제124회 1교시 #2 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(510,124,1,3,7,'비교/대조분석형','스마트팩토리에서 MES(Manufacturing Execution System) 참조모델인 ISA-88과 ISA-95 비교','["1. 스마트팩토리에서 MES(Manufacturing Execution System) 참조모델인 ISA-88과 ISA-95 비교의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 스마트팩토리에서 MES(Manufacturing Execution System) 참조모델인 ISA-88과 ISA-95 비교의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 스마트팩토리에서 MES(Manufacturing Execution System) 참조모델인 ISA-88과 ISA-95 비교 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 스마트팩토리에서 MES(Manufacturing Execution System) 참조모델인 ISA-88과 ISA-95 비교 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','MES, Manufacturing Execution System, ISA-88, ISA-95, 스마트팩토리, 참조모델인, 거버넌스','{"headers": ["비교 항목", "스마트팩토리에서 MES(Manufacturing Execution", "ISA-95"], "rows": [["핵심 개념·목적", "스마트팩토리에서 MES(Manufacturi의 고유 목적 및 적용 영역 정의", "ISA-95의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제124회 1교시 3번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''스마트팩토리에서 MES(Manufacturing Execution System) 참조모델인 ISA-88과 ISA-95 비교''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(스마트팩토리에서 MES(Manufacturing Execution System) 참조모델인 ISA-88과 ISA-95 비교의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(MES, Manufacturing Execution System, ISA-88, ISA-95)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제124회 1교시 #3 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(511,124,1,4,1,'비교/수리통계형','통계학에서 데이터의 4가지 측정 척도(명목, 서열, 등간, 비율 척도)','["1. 스티븐스(Stevens)의 4대 측정 척도(Nominal, Ordinal, Interval, Ratio) 개념", "2. 각 척도별 허용되는 산술 연산, 대표값 및 적용 가능한 통계 분석 기법 비교"]','["1. 리드문: 데이터 분석 및 머신러닝 피처 엔지니어링의 출발점 4대 측정 척도", "2. 범주형(명목·서열) vs 수치형(등간·비율) 정보량 및 연산 계층 구조도", "3. 4대 척도 비교표 (구분성, 서열성, 등간격성, 절대영점 유무, 대표값, 인코딩 기법)", "4. 머신러닝 모델 학습 시 척도 오용 방지(One-Hot vs Label Encoding) 주의사항"]','범주형(질적) 데이터, 수치형(양적) 데이터, 명목척도, 서열척도, 등간척도, 비율척도, 절대영점(Absolute Zero), One-Hot Encoding','{"headers": ["척도 구분", "보유 속성", "허용 연산 / 대표값", "대표 예시 및 ML 인코딩"], "rows": [["명목 척도 (Nominal)", "구분(이름)만 가능", "=(같다/다르다) / 최빈값(Mode)", "성별, 혈액형, 지역코드 → One-Hot Encoding 적용"], ["서열 척도 (Ordinal)", "구분 + 순서(대소 관계)", "<, > / 중앙값(Median), 백분위수", "학점(A/B/C), 만족도 등급 → Ordinal Encoding"], ["등간 척도 (Interval)", "구분 + 순서 + 동일 간격 (절대영점 없음)", "+, - (덧셈/뺄셈) / 산술평균(Mean)", "섭씨온도(℃), 지능지수(IQ), 서기 연도 (비율 배수 의미 없음)"], ["비율 척도 (Ratio)", "구분 + 순서 + 간격 + 절대영점(0=없음) 존재", "+, -, ×, ÷ (사칙연산) / 산술·기하·조화평균", "무게, 키, 매출액, 응답시간(ms) → Standard/MinMax Scaling"]]}','데이터의 측정 척도는 포함된 정보의 수준에 따라 범주형인 명목·서열 척도와 수치형인 등간·비율 척도로 구분된다. 특히 등간 척도(섭씨온도 등)는 임의 영점을 가지므로 덧셈·뺄셈만 가능하고 비율 척도(무게, 금액 등)는 절대 영점(0이 아무것도 없음을 의미)을 가져 곱셈·나눗셈(2배, 3배 비교)이 가능하다는 점이 핵심 차이다.','통계 기초 단답형 빈출','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(512,124,1,4,7,'개념/정의형','디지털 휴먼증강(Digital Human Augmentation)','["1. 디지털 휴먼증강(Digital Human Augmentation)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 디지털 휴먼증강(Digital Human Augmentation)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 디지털 휴먼증강(Digital Human Augmentation) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 디지털 휴먼증강(Digital Human Augmentation) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Digital Human Augmentation, 디지털, 휴먼증강, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "디지털 휴먼증강(Digital Human Augmentation)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "디지털 휴먼증강(Digital Human Augmentation)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "디지털 휴먼증강(Digital Human Augmentation)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "디지털 휴먼증강(Digital Human Augmentation) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제124회 1교시 4번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''디지털 휴먼증강(Digital Human Augmentation)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(디지털 휴먼증강(Digital Human Augmentation)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Digital Human Augmentation, 디지털, 휴먼증강, 거버넌스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제124회 1교시 #4 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(513,124,1,5,2,'개념/정의형','반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴','["1. 반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Responsive Web Design, RWD, 반응형, 디자인, 패턴, 품질속성, 유지보수성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제124회 1교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(반응형 웹 디자인(Responsive Web Design, RWD) 3가지 패턴의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Responsive Web Design, RWD, 반응형, 디자인)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제124회 1교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(514,124,1,6,2,'개념/정의형','의존성 주입(Dependency Injection)의 장점','["1. 의존성 주입(Dependency Injection)의 장점의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 의존성 주입(Dependency Injection)의 장점의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 의존성 주입(Dependency Injection)의 장점 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 의존성 주입(Dependency Injection)의 장점 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Dependency Injection, 의존성, 주입, 장점, 품질속성, 유지보수성, 설계원칙','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "의존성 주입(Dependency Injection)의 장점의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "의존성 주입(Dependency Injection)의 장점의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "의존성 주입(Dependency Injection)의 장점의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "의존성 주입(Dependency Injection)의 장점 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제124회 1교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''의존성 주입(Dependency Injection)의 장점''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(의존성 주입(Dependency Injection)의 장점의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Dependency Injection, 의존성, 주입, 장점)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제124회 1교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
