INSERT INTO "questions" VALUES(553,123,1,12,8,'개념/정의형','GADI(Global Architecture for Digital Identity)','["1. GADI(Global Architecture for Digital Identity)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: GADI(Global Architecture for Digital Identity)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: GADI(Global Architecture for Digital Identity) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: GADI(Global Architecture for Digital Identity) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','GADI, Global Architecture for Digital Ident, ity, 법적 근거, 컴플라이언스, 관리체계, 공공정책','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "GADI(Global Architecture for Digital Identity)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "GADI(Global Architecture for Digital Identity)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "GADI(Global Architecture for Digital Identity)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "GADI(Global Architecture for Digital Identity) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제123회 1교시 12번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''GADI(Global Architecture for Digital Identity)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(GADI(Global Architecture for Digital Identity)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(GADI, Global Architecture for Digital Ident, ity, 법적 근거)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 1교시 #12 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
