INSERT INTO "questions" VALUES(555,123,2,1,2,'개념/정의형','소프트웨어의 주요 특성과 공학의 발전원리 (다음의 개념에 대하여 설명하시오)','["가. 소프트웨어의 주요 특성과 공학의 발전원리", "나. 소프트웨어 공학이 다루는 주제와 그 목표", "다. 좋은 소프트웨어의 조건들과 개발에 영향을 미치는 요인들"]','["1. 리드문: 소프트웨어의 주요 특성과 공학의 발전원리 (다음의 개념에 대하여 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어의 주요 특성과 공학의 발전원리 (다음의 개념에 대하여 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어의 주요 특성과 공학의 발전원리 및 소프트웨어 공학이 다루는 주제와 그 목표 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','소프트웨어, 특성, 공학, 발전원리, 다루, 주제, 목표, 조건들','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 소프트웨어의 주요 특성과 공학의 발전원리", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 소프트웨어 공학이 다루는 주제와 그 목표", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 좋은 소프트웨어의 조건들과 개발에 영향을 미치는 요인들", "소프트웨어 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 2교시 1번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어의 주요 특성과 공학의 발전원리 (다음의 개념에 대하여 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어의 주요 특성과 공학의 발전원리 · 소프트웨어 공학이 다루는 주제와 그 목표 · 좋은 소프트웨어의 조건들과 개발에 영향을 미치는 요인들)을 필수 키워드(소프트웨어, 특성, 공학, 발전원리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 2교시 #1 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(556,123,2,2,3,'법제도/거버넌스형','머신러닝 보안 취약점에 대하여 설명하시오.','["가. 머신러닝 학습과정에서의 적대적 공격 4가지", "나. 각각 적대적 공격의 방어기법"]','["1. 리드문: 머신러닝 보안 취약점에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 머신러닝 보안 취약점에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 머신러닝 학습과정에서의 적대적 공격 4가지 및 각각 적대적 공격의 방어기법 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','머신러닝, 보안, 취약점, 학습과정에서, 적대적, 공격, 방어기법','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 머신러닝 학습과정에서의 적대적 공격 4가지", "머신러닝 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 각각 적대적 공격의 방어기법", "적대적 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 2교시 2번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''머신러닝 보안 취약점에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(머신러닝 학습과정에서의 적대적 공격 4가지 · 각각 적대적 공격의 방어기법)을 필수 키워드(머신러닝, 보안, 취약점, 학습과정에서)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 2교시 #2 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
