INSERT INTO "questions" VALUES(559,123,2,5,2,'법제도/거버넌스형','“정보시스템 감리 수행 가이드”의 검사기준서에 대하여 설명하시오.','["가. 기능 및 비기능 요구사항의 검사기준 점검방법", "나. 과업이행여부 점검결과에 대한 적부 판정방법"]','["1. 리드문: “정보시스템 감리 수행 가이드”의 검사기준서에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: “정보시스템 감리 수행 가이드”의 검사기준서에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 기능 및 비기능 요구사항의 검사기준 점검방법 및 과업이행여부 점검결과에 대한 적부 판정방법 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','정보시스템, 감리, 수행, 가이드, 검사기준서, 비기능, 요구사항, 검사기준','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 기능 및 비기능 요구사항의 검사기준 점검방법", "비기능 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 과업이행여부 점검결과에 대한 적부 판정방법", "과업이행여부 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 2교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''“정보시스템 감리 수행 가이드”의 검사기준서에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(기능 및 비기능 요구사항의 검사기준 점검방법 · 과업이행여부 점검결과에 대한 적부 판정방법)을 필수 키워드(정보시스템, 감리, 수행, 가이드)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 2교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(560,123,2,6,7,'절차/설계구현형','“정보화전략계획수립(ISP) 공통가이드(제4판)”에 대하여 설명하시오.','["가. ISP 추진 및 검토 절차", "나. ISP 기본 구성 내용(단계별 활동, 세부내용, 산출물)"]','["1. 리드문: “정보화전략계획수립(ISP) 공통가이드(제4판)”에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: “정보화전략계획수립(ISP) 공통가이드(제4판)”에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ISP 추진 및 검토 절차 및 ISP 기본 구성 내용(단계별 활동, 세부내용, 산출물) 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','ISP, 정보화전략계획수립, 공통가이드, 추진, 검토, 기본, 구성, 단계별','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. ISP 추진 및 검토 절차", "ISP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. ISP 기본 구성 내용(단계별 활동, 세부내용, 산출물)", "ISP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 2교시 6번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''“정보화전략계획수립(ISP) 공통가이드(제4판)”에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ISP 추진 및 검토 절차 · ISP 기본 구성 내용(단계별 활동, 세부내용, 산출물))을 필수 키워드(ISP, 정보화전략계획수립, 공통가이드, 추진)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 2교시 #6 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(561,123,3,1,8,'개념/보안인증형','정보보호 및 개인정보보호 관리체계 인증(ISMS-P)의 3대 영역(관리체계 수립·운영, 보호대책 요구사항, 개인정보 처리단계별 요구사항) 및 심사 절차','["가. 기존 ISMS와 PIMS 통합 배경 및 ISMS-P 101개(클라우드/가상자산 특화 포함) 인증 기준", "나. 인증 의무 대상자 기준 및 사후·갱신 심사 실무 대응 방안"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','정보보호 및 개인정보보호 관리체계 인증, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["가. 기존 ISMS와 PIMS 통합 배경 및 ISMS-P 101개(클라우드/가상자산 특화 포함) 인증 기준", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["나. 인증 의무 대상자 기준 및 사후·갱신 심사 실무 대응 방안", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','정보보호 및 개인정보보호 관리체계 인증(ISMS-P)의 3대 영역(관리체계 수립·운영, 보호대책 요구사항, 개인정보 처리단계별 요구사항) 및 심사 절차 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 가. 기존 ISMS와 PIMS 통합 배경 및 ISMS-P 101개(클라우드/가상자산 특화 포함) 인증 기준 및 나. 인증 의무 대상자 기준 및 사후·갱신 심사 실무 대응 방안을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제123회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(562,123,3,1,5,'개념/정의형','메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여 설명하시오.','["1. 메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','메시지큐잉, 프로토콜 스택, 대역폭·지연시간, 고가용성, 트래픽 제어','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제123회 3교시 1번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(메시지큐잉에 대한 개념과 필요성, 종류, 기능에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(메시지큐잉, 프로토콜 스택, 대역폭·지연시간, 고가용성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 3교시 #1 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(563,123,3,2,2,'개념/정의형','데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여 설명하시오.','["1. 데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','데이터, 품질관리, 프레임워크, 관리, 구조관리, 관리프로세스, 품질속성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제123회 3교시 2번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(데이터 품질관리 프레임워크, 데이터 관리, 데이터 구조관리, 데이터 관리프로세스에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(데이터, 품질관리, 프레임워크, 관리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 3교시 #2 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(564,123,3,3,1,'비교/대조분석형','기술통계와 추론통계에 대하여 설명하시오.','["가. 기술통계와 추론통계의 차이점 비교", "나. 기술통계와 추론통계에 사용되는 기술(각각 4개만 쓰시오)"]','["1. 리드문: 기술통계와 추론통계에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 기술통계와 추론통계에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 기술통계와 추론통계의 차이점 비교 및 기술통계와 추론통계에 사용되는 기술(각각 4개만 쓰시오) 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','기술통계, 추론통계, 사용되, 기술, 개만, 쓰시오, 아키텍처','{"headers": ["비교 항목", "기술통계", "추론통계에 대하여"], "rows": [["핵심 개념·목적", "기술통계의 고유 목적 및 적용 영역 정의", "추론통계에 대하여의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제123회 3교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''기술통계와 추론통계에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(기술통계와 추론통계의 차이점 비교 · 기술통계와 추론통계에 사용되는 기술(각각 4개만 쓰시오))을 필수 키워드(기술통계, 추론통계, 사용되, 기술)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 3교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(565,123,3,4,2,'실무/시나리오형','API Gateway를 활용하여 정보시스템을 구축하고자 한다. API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여 설명하시오.','["1. API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','API Gateway, 활용하여, 정보시스템, 구축하고자, 한다, 주요기능, 적용사례','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제123회 3교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(API Gateway의 역할과 필요성, 주요기능, 적용 시 고려사항과 적용사례에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(API Gateway, 활용하여, 정보시스템, 구축하고자)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 3교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(566,123,3,5,2,'비교/대조분석형','코로나 19로 비대면 언택트 시대에 부각되고 있는 가상융합기술에 대하여 설명하시오.','["가. 가상현실, 증강현실, 가상융합기술 비교", "나. 가상융합경제 발전전략"]','["1. 리드문: 코로나 19로 비대면 언택트 시대에 부각되고 있는 가상융합기술에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 코로나 19로 비대면 언택트 시대에 부각되고 있는 가상융합기술에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 가상현실, 증강현실, 가상융합기술 비교 및 가상융합경제 발전전략 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','코로나, 비대면, 언택트, 시대, 부각되고, 가상융합기술, 가상현실, 증강현실','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 가상현실, 증강현실, 가상융합기술 비교", "가상현실 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 가상융합경제 발전전략", "가상융합경제 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 3교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''코로나 19로 비대면 언택트 시대에 부각되고 있는 가상융합기술에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(가상현실, 증강현실, 가상융합기술 비교 · 가상융합경제 발전전략)을 필수 키워드(코로나, 비대면, 언택트, 시대)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 3교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(567,123,3,6,7,'비교/대조분석형','비대면 시대에 떠오르는 이슈인 행동인터넷(IoB, Internet of Behavior)에 대하여 설명하시오.','["가. 개념과 배경", "나. IoT와의 비교", "다. 기술의 영향"]','["1. 리드문: 비대면 시대에 떠오르는 이슈인 행동인터넷(IoB, Internet of Behavior)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 비대면 시대에 떠오르는 이슈인 행동인터넷(IoB, Internet of Behavior)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개념과 배경 및 IoT와의 비교 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IoB, Internet of Behavior, IoT, 비대면, 시대, 떠오르, 이슈인, 행동인터넷','{"headers": ["비교 항목", "비대면 시대에 떠오르는 이슈인 행동인터넷(IoB", "Internet of Behavior)에 대하여"], "rows": [["핵심 개념·목적", "비대면 시대에 떠오르는 이슈인 행동인터넷(I의 고유 목적 및 적용 영역 정의", "Internet of Behavior)에 대의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제123회 3교시 6번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''비대면 시대에 떠오르는 이슈인 행동인터넷(IoB, Internet of Behavior)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개념과 배경 · IoT와의 비교 · 기술의 영향)을 필수 키워드(IoB, Internet of Behavior, IoT, 비대면)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 3교시 #6 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(568,123,4,1,8,'법제도/거버넌스형','최근 Netflix 등 CP(Contents Provider)들의 망관리 비용을 요구하는 법제화 움직임이 일자 그들의 불만이 표시되고 있다. 4차 산업혁명시대의 망중립성 이슈에 대하여 설명 하시오.','["가. 쟁점 사항 및 정책 이슈", "나. 시사점 및 대응 방안"]','["1. 리드문: 4차 산업혁명시대의 망중립성 이슈에 대하여 설명 하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 4차 산업혁명시대의 망중립성 이슈에 대하여 설명 하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 쟁점 사항 및 정책 이슈 및 시사점 및 대응 방안 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','Netflix, CP, Contents Provider, 망관리, 비용, 요구하, 법제화, 움직임','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 쟁점 사항 및 정책 이슈", "쟁점 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 시사점 및 대응 방안", "대응 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 4교시 1번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''4차 산업혁명시대의 망중립성 이슈에 대하여 설명 하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(쟁점 사항 및 정책 이슈 · 시사점 및 대응 방안)을 필수 키워드(Netflix, CP, Contents Provider, 망관리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 4교시 #1 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(569,123,4,2,7,'개념/정의형','A발주기관은 B수행업체에게 IT 아웃소싱업무를 위탁하였다. 다음에 대하여 설명하시오.','["가. 발주가능한 아웃소싱의 유형", "나. SLA(Service Level Agreement)와 OLA(Operational Level Agreement)", "다. Penalty/Incentive 관리체계, SIP(Service Improvement Plan), Annual Reset"]','["1. 리드문: 다음에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 다음에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 발주가능한 아웃소싱의 유형 및 SLA(Service Level Agreement)와 OLA(Oper 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IT, SLA, Service Level Agreement, OLA, Operational Level Agreement, Penalty/Incentive, SIP, Service Improvement Plan','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 발주가능한 아웃소싱의 유형", "발주가능한 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. SLA(Service Level Agreement)와 OLA(Operational Level Agreement)", "SLA 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. Penalty/Incentive 관리체계, SIP(Service Improvement Plan), Annual Reset", "Penalty/Incentive 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 4교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''다음에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(발주가능한 아웃소싱의 유형 · SLA(Service Level Agreement)와 OLA(Operational Level Agreement) · Penalty/Incentive 관리체계, SIP(Service Improvement Plan), Annual Reset)을 필수 키워드(IT, SLA, Service Level Agreement, OLA)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 4교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(570,123,4,3,8,'법제도/거버넌스형','정보윤리 정의 및 원칙 (정보윤리와 관련하여 다음에 대하여 설명하시오)','["가. 정보윤리 정의 및 원칙", "나. 컴퓨터(사이버) 범죄의 정의와 특징, 종류와 그 대응책", "다. 컴퓨터(사이버) 중독의 정의, 종류와 그 문제점"]','["1. 리드문: 정보윤리 정의 및 원칙 (정보윤리와 관련하여 다음에 대하여 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보윤리 정의 및 원칙 (정보윤리와 관련하여 다음에 대하여 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정보윤리 정의 및 원칙 및 컴퓨터(사이버) 범죄의 정의와 특징, 종류와 그 대응책 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','정보윤리, 원칙, 컴퓨터, 사이버, 범죄, 대응책, 중독','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 정보윤리 정의 및 원칙", "정보윤리 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 컴퓨터(사이버) 범죄의 정의와 특징, 종류와 그 대응책", "컴퓨터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 컴퓨터(사이버) 중독의 정의, 종류와 그 문제점", "컴퓨터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 4교시 3번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''정보윤리 정의 및 원칙 (정보윤리와 관련하여 다음에 대하여 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정보윤리 정의 및 원칙 · 컴퓨터(사이버) 범죄의 정의와 특징, 종류와 그 대응책 · 컴퓨터(사이버) 중독의 정의, 종류와 그 문제점)을 필수 키워드(정보윤리, 원칙, 컴퓨터, 사이버)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 4교시 #3 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(571,123,4,4,1,'비교/대조분석형','NER(Named Entity Recognition)과 Word Embedding (자연어처리와 관련하여 다음에 대하여 설명하시오)','["가. NER(Named Entity Recognition)과 Word Embedding", "나. BERT와 GPT-3의 비교"]','["1. 리드문: NER(Named Entity Recognition)과 Word Embedding (자연어처리와 관련하여 다음에 대하여 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: NER(Named Entity Recognition)과 Word Embedding (자연어처리와 관련하여 다음에 대하여 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: NER(Named Entity Recognition)과 Word Em 및 BERT와 GPT-3의 비교 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','NER, Named Entity Recognition, Word Embedding, BERT, GPT-3, 자연어처리, 아키텍처','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. NER(Named Entity Recognition)과 Word Embedding", "NER 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. BERT와 GPT-3의 비교", "BERT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 4교시 4번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''NER(Named Entity Recognition)과 Word Embedding (자연어처리와 관련하여 다음에 대하여 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(NER(Named Entity Recognition)과 Word Embedding · BERT와 GPT-3의 비교)을 필수 키워드(NER, Named Entity Recognition, Word Embedding, BERT)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 4교시 #4 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(572,123,4,5,1,'법제도/거버넌스형','정량적 위험분석의 정의와 필요성을 설명하고, 아래의 4가지 위험분석 기법에 대하여 예시를 들어 설명하시오.','["의사결정나무 분석(Decision Tree Analysis)", "금전적 기대값 분석(Expected Monetary Value Analysis)", "몬테카를로 시뮬레이션(Monte Carlo Simulation)", "민감도 분석(Sensitivity Analysis)"]','["1. 리드문: 정량적 위험분석의 정의와 필요성을 설명하고, 아래의 4가지 위험분석 기법에 대하여 예시를 들어의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정량적 위험분석의 정의와 필요성을 설명하고, 아래의 4가지 위험분석 기법에 대하여 예시를 들어 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 의사결정나무 분석(Decision Tree Analysis) 및 금전적 기대값 분석(Expected Monetary Value Ana 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Decision Tree Analysis, Expected Monetary Value Analysis, Monte Carlo Simulation, Sensitivity Analysis, 정량적, 위험분석, 설명하고, 아래','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["의사결정나무 분석(Decision Tree Analysis)", "Decision Tree Analysis 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["금전적 기대값 분석(Expected Monetary Value Analysis)", "Expected Monetary Value Analysis 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["몬테카를로 시뮬레이션(Monte Carlo Simulation)", "Monte Carlo Simulation 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["민감도 분석(Sensitivity Analysis)", "Sensitivity Analysis 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 4교시 5번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''정량적 위험분석의 정의와 필요성을 설명하고, 아래의 4가지 위험분석 기법에 대하여 예시를 들어''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(의사결정나무 분석(Decision Tree Analysis) · 금전적 기대값 분석(Expected Monetary Value Analysis) · 몬테카를로 시뮬레이션(Monte Carlo Simulation))을 필수 키워드(Decision Tree Analysis, Expected Monetary Value Analysis, Monte Carlo Simulation, Sensitivity Analysis)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 4교시 #5 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(573,123,4,6,2,'비교/대조분석형','최단경로 알고리즘의 유형 4가지 (다음에 대하여 설명하시오)','["가. 최단경로 알고리즘의 유형 4가지", "나. 다음 그래프에서 4가지 알고리즘 계산방법", "- A, B, C, D, E 5개 노드로 구성된 그래프(A가 출발지, E가 목적지임)", "다. “나”의 4가지 알고리즘 계산결과 비교"]','["1. 리드문: 최단경로 알고리즘의 유형 4가지 (다음에 대하여 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 최단경로 알고리즘의 유형 4가지 (다음에 대하여 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 최단경로 알고리즘의 유형 4가지 및 다음 그래프에서 4가지 알고리즘 계산방법 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','E 5, 최단경, 알고리즘, 그래프, 계산방법, 노드, 구성된, 출발지','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 최단경로 알고리즘의 유형 4가지", "최단경 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 다음 그래프에서 4가지 알고리즘 계산방법", "그래프 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["- A, B, C, D, E 5개 노드로 구성된 그래프(A가 출발지, E가 목적지임)", "E 5 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. “나”의 4가지 알고리즘 계산결과 비교", "알고리즘 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제123회 4교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''최단경로 알고리즘의 유형 4가지 (다음에 대하여 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(최단경로 알고리즘의 유형 4가지 · 다음 그래프에서 4가지 알고리즘 계산방법 · - A, B, C, D, E 5개 노드로 구성된 그래프(A가 출발지, E가 목적지임))을 필수 키워드(E 5, 최단경, 알고리즘, 그래프)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제123회 4교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(574,122,1,1,6,'비교/운영체제형','운영체제 프로세스·스레드 동기화를 위한 세마포어(Semaphore)와 모니터(Monitor) 비교','["1. 임계구역(Critical Section) 문제 해결을 위한 상호배제·진행·한정대기 조건", "2. 세마포어(P/V 연산)와 모니터(고수준 동기화 구조체)의 동작 원리 및 장단점 비교"]','["1. 리드문: 경쟁 조건(Race Condition) 예방과 임계구역 보호를 위한 동기화 메커니즘", "2. 세마포어(공유 정수 변수 S + 대기 큐) vs 모니터(공유자원 + 프로시저 + 조건변수 캡슐화) 구조도", "3. 뮤텍스(Mutex) vs 세마포어(Semaphore) vs 모니터(Monitor) 비교표", "4. 데드락·우선순위 역전 방지 및 언어 차원(Java synchronized, Go Channel) 동시성 발전"]','임계구역(Critical Section), 상호배제·진행·한정대기, Semaphore(P=wait, V=signal), Monitor, 조건변수(wait/notify), Race Condition','{"headers": ["비교 항목", "세마포어 (Semaphore)", "모니터 (Monitor)"], "rows": [["추상화 수준", "운영체제 커널/시스템 콜 수준의 저수준(Low-level) 동기화 도구", "프로그래밍 언어·컴파일러가 지원하는 고수준(High-level) 객체 캡슐화 구조"], ["동작 메커니즘", "정수형 변수 S와 원자적 P(wait)/V(signal) 연산으로 가용 자원 수 제어", "공유 데이터와 접근 프로시저를 하나로 묶어 한 시점에 하나의 스레드만 진입 자동 보장"], ["사용 안전성", "개발자가 P/V 연산 순서를 실수하거나 누락하면 즉시 데드락·상호배제 파괴 발생", "락 획득·해제를 컴파일러가 자동 처리하여 안전하고 코드 가독성이 높음 (Java synchronized)"]]}','세마포어(Semaphore)는 다익스트라가 제안한 저수준 동기화 기법으로 원자적 P(wait)·V(signal) 연산을 통해 N개의 공유 자원 접근을 제어하나 개발자의 코딩 실수로 인한 데드락 위험이 있다. 반면 모니터(Monitor)는 공유 자원과 접근 함수를 하나의 모듈로 캡슐화하여 컴파일러 차원에서 상호배제를 자동 보장하는 고수준 동기화 구조다.','122회 세마포어/모니터 → 126회 Race Condition → 138회 은행가 알고리즘 등 OS 동기화 지속 출제','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(575,122,1,2,7,'개념/정의형','인슈어테크(InsurTech)','["1. 인슈어테크(InsurTech)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 인슈어테크(InsurTech)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 인슈어테크(InsurTech) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 인슈어테크(InsurTech) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','InsurTech, 인슈어테크, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "인슈어테크(InsurTech)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "인슈어테크(InsurTech)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "인슈어테크(InsurTech)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "인슈어테크(InsurTech) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제122회 1교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''인슈어테크(InsurTech)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(인슈어테크(InsurTech)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(InsurTech, 인슈어테크, 거버넌스, ROI·성과지표)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 1교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(576,122,1,3,4,'개념/정의형','LOD(Linked Open Data)','["1. LOD(Linked Open Data)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: LOD(Linked Open Data)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: LOD(Linked Open Data) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: LOD(Linked Open Data) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','LOD, Linked Open Data, 데이터 정합성, 성능·확장성, 인덱싱/분할, 무결성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "LOD(Linked Open Data)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "LOD(Linked Open Data)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "LOD(Linked Open Data)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "LOD(Linked Open Data) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제122회 1교시 3번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''LOD(Linked Open Data)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(LOD(Linked Open Data)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(LOD, Linked Open Data, 데이터 정합성, 성능·확장성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 1교시 #3 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(577,122,1,4,8,'개념/정의형','허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)','["1. 허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','Permissive License, Copyleft License, 허용적, 라이선스, 카피레프트, 법적 근거, 컴플라이언스','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제122회 1교시 4번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(허용적 라이선스(Permissive License)와 카피레프트 라이선스(Copyleft License)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Permissive License, Copyleft License, 허용적, 라이선스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 1교시 #4 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
