INSERT INTO "questions" VALUES(588,122,2,2,3,'개념/정의형','블록체인 합의 알고리즘(Consensus Algorithm)에 대하여 다음을 설명하시오.','["가. 합의 알고리즘의 목적", "나. 합의 알고리즘의 원리", "다. 합의 알고리즘의 종류 및 특징"]','["1. 리드문: 블록체인 합의 알고리즘(Consensus Algorithm)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 블록체인 합의 알고리즘(Consensus Algorithm) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 합의 알고리즘의 목적 및 합의 알고리즘의 원리 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','Consensus Algorithm, 블록체인, 알고리즘, 기밀성·무결성, 보안통제, 위협모델링, 대응아키텍처','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 합의 알고리즘의 목적", "알고리즘 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 합의 알고리즘의 원리", "알고리즘 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 합의 알고리즘의 종류 및 특징", "알고리즘 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 2교시 2번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''블록체인 합의 알고리즘(Consensus Algorithm)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(합의 알고리즘의 목적 · 합의 알고리즘의 원리 · 합의 알고리즘의 종류 및 특징)을 필수 키워드(Consensus Algorithm, 블록체인, 알고리즘, 기밀성·무결성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 2교시 #2 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(589,122,2,3,2,'비교/대조분석형','개방형 API(Open Application Programming Interface)와 관련하여 다음을 설명하시오.','["가. 정의 및 필요성", "나. 개방형 API 시스템 구성도", "다. 2 가지 구조(SOAP, REST)별 특징 비교", "라. SOAP 의 4 가지 구성요소"]','["1. 리드문: 개방형 API(Open Application Programming Interface)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개방형 API(Open Application Programming Interface) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 정의 및 필요성 및 개방형 API 시스템 구성도 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','API, Open Application Programming Interfac, SOAP, REST, 개방형, 시스템, 구성','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 정의 및 필요성", "품질속성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 개방형 API 시스템 구성도", "API 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 2 가지 구조(SOAP, REST)별 특징 비교", "SOAP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. SOAP 의 4 가지 구성요소", "SOAP 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 2교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''개방형 API(Open Application Programming Interface)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(정의 및 필요성 · 개방형 API 시스템 구성도 · 2 가지 구조(SOAP, REST)별 특징 비교)을 필수 키워드(API, Open Application Programming Interfac, SOAP, REST)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 2교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(590,122,2,4,2,'절차/설계구현형','서비스 워커(Service Worker)에 대하여 다음을 설명하시오.','["가. 서비스 워커의 개념", "나. 구현 기술", "다. 수명 주기", "라. 활용 분야"]','["1. 리드문: 서비스 워커(Service Worker)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 서비스 워커(Service Worker) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 서비스 워커의 개념 및 구현 기술 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Service Worker, 서비스, 워커, 구현, 기술, 수명, 주기, 분야','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 서비스 워커의 개념", "서비스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 구현 기술", "구현 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 수명 주기", "수명 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 활용 분야", "분야 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 2교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''서비스 워커(Service Worker)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(서비스 워커의 개념 · 구현 기술 · 수명 주기)을 필수 키워드(Service Worker, 서비스, 워커, 구현)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 2교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(591,122,2,5,7,'원인분석/대응전략형','정보시스템 운영환경 변환과정에서 장애 예방 및 대응과 관련하여 다음을 설명하시오.','["가. 목적 및 필요성", "나. 운영환경 변환 유형 및 장애 유형", "다. 장애 예방 및 대응 활동 강화 방안"]','["1. 리드문: 정보시스템 운영환경 변환과정에서 장애 예방 및 대응의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보시스템 운영환경 변환과정에서 장애 예방 및 대응 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 목적 및 필요성 및 운영환경 변환 유형 및 장애 유형 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','정보시스템, 운영환경, 변환과정, 장애, 예방, 대응, 변환, 활동','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 목적 및 필요성", "거버넌스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 운영환경 변환 유형 및 장애 유형", "운영환경 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 장애 예방 및 대응 활동 강화 방안", "장애 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 2교시 5번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''정보시스템 운영환경 변환과정에서 장애 예방 및 대응''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(목적 및 필요성 · 운영환경 변환 유형 및 장애 유형 · 장애 예방 및 대응 활동 강화 방안)을 필수 키워드(정보시스템, 운영환경, 변환과정, 장애)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 2교시 #5 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(592,122,2,6,2,'절차/설계구현형','스택(Stack)의 개념을 설명하고, 아래의 조건을 만족하는 스택의 작동 알고리즘을 작성하시오.','["K : 스택의 크기 Top : 스택 포인터 S : 스택의 이름", "가. 스택(S)의 스택 포인터(Top)를 1 증가시킨다. 스택 포인터가 스택의 크기(K)보다 크면 Overflow 처리한다. 그렇지 않으면 Item 이 가지고 있는 값을 스택의 Top 위치에 삽입한다.", "나. 스택 포인터가 0 이면 스택의 바닥이며 더 이상 삭제할 자료가 없으므로 Underflow 처리한다. 그렇지 않으면 Top 위치에 있는 값을 Item 으로 옮기고 스택포인터를 1 감소시킨다."]','["1. 리드문: 스택(Stack)의 개념을 설명하고, 아래의 조건을 만족하는 스택의 작동 알고리즘을 작성하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 스택(Stack)의 개념을 설명하고, 아래의 조건을 만족하는 스택의 작동 알고리즘을 작성하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: K : 스택의 크기 Top : 스택 포인터 S : 스택의 이름 및 스택(S)의 스택 포인터(Top)를 1 증가시킨다. 스택 포인터가 스 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Stack, Top, Overflow, Item, Underflow, 스택, 설명하고, 아래','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["K : 스택의 크기 Top : 스택 포인터 S : 스택의 이름", "Top 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["가. 스택(S)의 스택 포인터(Top)를 1 증가시킨다. 스택 포인터가 스택의 크기(K)보다 크면 Overflow 처리한다. 그렇지 않", "Top 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 스택 포인터가 0 이면 스택의 바닥이며 더 이상 삭제할 자료가 없으므로 Underflow 처리한다. 그렇지 않으면 Top 위치에 ", "Underflow 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 2교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''스택(Stack)의 개념을 설명하고, 아래의 조건을 만족하는 스택의 작동 알고리즘을 작성하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(K : 스택의 크기 Top : 스택 포인터 S : 스택의 이름 · 스택(S)의 스택 포인터(Top)를 1 증가시킨다. 스택 포인터가 스택의 크기(K)보다 크면 Overflow 처리한다. 그렇지 않으면 Item 이 가지고 있는 값을 스택의 Top 위치에 삽입한다. · 스택 포인터가 0 이면 스택의 바닥이며 더 이상 삭제할 자료가 없으므로 Underflow 처리한다. 그렇지 않으면 Top 위치에 있는 값을 Item 으로 옮기고 스택포인터를 1 감소시킨다.)을 필수 키워드(Stack, Top, Overflow, Item)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 2교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(593,122,3,1,2,'개념/정의형','웹크롤링(Web Crawling)에 대하여 설명하시오.','["1. 웹크롤링(Web Crawling)에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 웹크롤링(Web Crawling)에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 웹크롤링(Web Crawling)에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 웹크롤링(Web Crawling)에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Web Crawling, 웹크롤링, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "웹크롤링(Web Crawling)에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "웹크롤링(Web Crawling)에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "웹크롤링(Web Crawling)에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "웹크롤링(Web Crawling)에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제122회 3교시 1번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''웹크롤링(Web Crawling)에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(웹크롤링(Web Crawling)에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Web Crawling, 웹크롤링, 품질속성, 유지보수성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 3교시 #1 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(594,122,3,2,3,'개념/정의형','ISO/IEC 27017(클라우드 서비스 정보보호 통제)을 설명하시오.','["1. ISO/IEC 27017(클라우드 서비스 정보보호 통제)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: ISO/IEC 27017(클라우드 서비스 정보보호 통제)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ISO/IEC 27017(클라우드 서비스 정보보호 통제) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ISO/IEC 27017(클라우드 서비스 정보보호 통제) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','ISO/IEC 27017, 클라우드, 서비스, 정보보호, 통제, 기밀성·무결성, 보안통제','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "ISO/IEC 27017(클라우드 서비스 정보보호 통제)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "ISO/IEC 27017(클라우드 서비스 정보보호 통제)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "ISO/IEC 27017(클라우드 서비스 정보보호 통제)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "ISO/IEC 27017(클라우드 서비스 정보보호 통제) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제122회 3교시 2번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''ISO/IEC 27017(클라우드 서비스 정보보호 통제)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ISO/IEC 27017(클라우드 서비스 정보보호 통제)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(ISO/IEC 27017, 클라우드, 서비스, 정보보호)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 3교시 #2 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(595,122,3,3,3,'절차/설계구현형','분산 ID(Decentralized Identity)와 관련하여 다음을 설명하시오.','["가. 개념 및 등장배경", "나. 신원증명 발전 단계", "다. 특징 및 기본 구조도", "라. 활용 분야"]','["1. 리드문: 분산 ID(Decentralized Identity)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 분산 ID(Decentralized Identity) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개념 및 등장배경 및 신원증명 발전 단계 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','ID, Decentralized Identity, 분산, 등장배경, 신원증명, 발전, 단계, 기본','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 개념 및 등장배경", "등장배경 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 신원증명 발전 단계", "신원증명 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 특징 및 기본 구조도", "기본 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 활용 분야", "분야 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 3교시 3번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''분산 ID(Decentralized Identity)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개념 및 등장배경 · 신원증명 발전 단계 · 특징 및 기본 구조도)을 필수 키워드(ID, Decentralized Identity, 분산, 등장배경)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 3교시 #3 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(596,122,3,4,2,'법제도/거버넌스형','블랙박스 테스트(Blackbox Test) 기법을 설명하고, YYYY-MM-DD 형식의 날짜 처리 모듈을 위한 블랙박스 테스트 케이스를 작성하시오.','["YYYY 는 년(네자리 숫자) MM 은 월(한자리 또는 두자리 숫자) DD 는 일(한자리 또는 두자리 숫자) 빈칸은 무시"]','["1. 리드문: YYYY-MM-DD 형식의 날짜 처리 모듈을 위한 블랙박스 테스트 케이스를 작성하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: YYYY-MM-DD 형식의 날짜 처리 모듈을 위한 블랙박스 테스트 케이스를 작성하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: YYYY 는 년(네자리 숫자) MM 은 월(한자리 또는 두자리 숫자) 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Blackbox Test, YYYY-MM-DD, YYYY, MM, DD, 블랙박스, 테스트, 설명하고','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["YYYY 는 년(네자리 숫자) MM 은 월(한자리 또는 두자리 숫자) DD 는 일(한자리 또는 두자리 숫자) 빈칸은 무시", "YYYY 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 3교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''YYYY-MM-DD 형식의 날짜 처리 모듈을 위한 블랙박스 테스트 케이스를 작성하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(YYYY 는 년(네자리 숫자) MM 은 월(한자리 또는 두자리 숫자) DD 는 일(한자리 또는 두자리 숫자) 빈칸은 무시)을 필수 키워드(Blackbox Test, YYYY-MM-DD, YYYY, MM)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 3교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(597,122,3,5,7,'절차/설계구현형','개념 및 필요성 (IT 투자관리와 관련하여 다음을 설명하시오)','["가. 개념 및 필요성", "나. 추진단계별 주요 활동", "다. IT 투자 평가 항목 및 내용(정량적, 정성적)", "라. 기대 효과"]','["1. 리드문: 개념 및 필요성 (IT 투자관리와 관련하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개념 및 필요성 (IT 투자관리와 관련하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개념 및 필요성 및 추진단계별 주요 활동 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','IT, 투자관리, 추진단계별, 활동, 투자, 항목, 정량적, 정성적','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 개념 및 필요성", "거버넌스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 추진단계별 주요 활동", "추진단계별 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. IT 투자 평가 항목 및 내용(정량적, 정성적)", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 기대 효과", "기대 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 3교시 5번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''개념 및 필요성 (IT 투자관리와 관련하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개념 및 필요성 · 추진단계별 주요 활동 · IT 투자 평가 항목 및 내용(정량적, 정성적))을 필수 키워드(IT, 투자관리, 추진단계별, 활동)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 3교시 #5 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(598,122,3,6,2,'절차/설계구현형','아래 시나리오를 기반으로 고객과 점주가 사용하는 주문 시스템에 대한 Use Case Diagram 을 작성하시오.','["가. 고객은 주문 시스템을 통해 가격을 조회하고 주문할 수 있다.", "나. 고객은 주문 시스템을 통해 주문 상태를 확인하고 주문을 취소할 수 있다.", "다. 점주는 주문 시스템을 통해 주문 활동을 모니터링하고 창고를 관리할 수 있다.", "라. 회계 시스템은 주문 시스템과 연동하여 주문이나 취소 처리할 수 있다.", "시나리오"]','["1. 리드문: 아래 시나리오를 기반으로 고객과 점주가 사용하는 주문 시스템에 대한 Use Case Diagram 을 작성하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 아래 시나리오를 기반으로 고객과 점주가 사용하는 주문 시스템에 대한 Use Case Diagram 을 작성하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 고객은 주문 시스템을 통해 가격을 조회하고 주문할 수 있다. 및 고객은 주문 시스템을 통해 주문 상태를 확인하고 주문을 취소할 수 있 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Use Case Diagram, 아래, 시나리오, 고객, 점주, 사용하, 주문, 시스템','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 고객은 주문 시스템을 통해 가격을 조회하고 주문할 수 있다.", "고객 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 고객은 주문 시스템을 통해 주문 상태를 확인하고 주문을 취소할 수 있다.", "고객 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 점주는 주문 시스템을 통해 주문 활동을 모니터링하고 창고를 관리할 수 있다.", "점주 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 회계 시스템은 주문 시스템과 연동하여 주문이나 취소 처리할 수 있다.", "회계 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 3교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''아래 시나리오를 기반으로 고객과 점주가 사용하는 주문 시스템에 대한 Use Case Diagram 을 작성하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(고객은 주문 시스템을 통해 가격을 조회하고 주문할 수 있다. · 고객은 주문 시스템을 통해 주문 상태를 확인하고 주문을 취소할 수 있다. · 점주는 주문 시스템을 통해 주문 활동을 모니터링하고 창고를 관리할 수 있다.)을 필수 키워드(Use Case Diagram, 아래, 시나리오, 고객)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 3교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(599,122,4,1,5,'법제도/거버넌스형','IaaS(Infrastructure as a Service), PaaS(Platform as a Service), SaaS(Software as a Service)의 특징 및 구축방법을 설명하시오.','["1. SaaS(Software as a Service)의 특징 및 구축방법의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: SaaS(Software as a Service)의 특징 및 구축방법의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: SaaS(Software as a Service)의 특징 및 구축방법 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: SaaS(Software as a Service)의 특징 및 구축방법 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','IaaS, Infrastructure as a Service, PaaS, Platform as a Service, SaaS, Software as a Service, 구축방법','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "SaaS(Software as a Service)의 특징 및 구축방법의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "SaaS(Software as a Service)의 특징 및 구축방법의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "SaaS(Software as a Service)의 특징 및 구축방법의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "SaaS(Software as a Service)의 특징 및 구축방법 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제122회 4교시 1번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''SaaS(Software as a Service)의 특징 및 구축방법''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(SaaS(Software as a Service)의 특징 및 구축방법의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(IaaS, Infrastructure as a Service, PaaS, Platform as a Service)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 4교시 #1 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(600,122,4,2,8,'비교/대조분석형','공공 기관의 정보시스템 구축업체 선정 및 계약 체결과 관련하여 다음을 설명하시오.','["가. 협상에 의한 계약체결 방식과 품질 등에 따른 낙찰자 결정방식의 비교", "나. 협상에 의한 계약체결 방식의 진행 절차", "다. 협상에 의한 계약체결 방식의 기준에서 제시하는 제안서의 평가항목 및 배점한도"]','["1. 리드문: 공공 기관의 정보시스템 구축업체 선정 및 계약 체결의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 공공 기관의 정보시스템 구축업체 선정 및 계약 체결 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 협상에 의한 계약체결 방식과 품질 등에 따른 낙찰자 결정방식의 비교 및 협상에 의한 계약체결 방식의 진행 절차 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','공공, 정보시스템, 구축업체, 선정, 계약, 체결, 협상, 의한','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 협상에 의한 계약체결 방식과 품질 등에 따른 낙찰자 결정방식의 비교", "협상 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 협상에 의한 계약체결 방식의 진행 절차", "협상 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 협상에 의한 계약체결 방식의 기준에서 제시하는 제안서의 평가항목 및 배점한도", "협상 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 4교시 2번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''공공 기관의 정보시스템 구축업체 선정 및 계약 체결''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(협상에 의한 계약체결 방식과 품질 등에 따른 낙찰자 결정방식의 비교 · 협상에 의한 계약체결 방식의 진행 절차 · 협상에 의한 계약체결 방식의 기준에서 제시하는 제안서의 평가항목 및 배점한도)을 필수 키워드(공공, 정보시스템, 구축업체, 선정)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 4교시 #2 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(601,122,4,3,8,'법제도/거버넌스형','2020 년 5 월에 공인인증서와 사설인증서의 구별을 없애는 전자서명법이 개정되었다. 이에 따라 국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여 설명하시오.','["1. 국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','공인인증서, 사설인증서, 구별, 없애, 전자서명법, 개정되었다, 따라, 국내','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제122회 4교시 3번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(국내에 대중화 되어 있는 사설인증서의 종류 및 전자서명 시장의 발전방향에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(공인인증서, 사설인증서, 구별, 없애)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 4교시 #3 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(602,122,4,4,2,'개념/정의형','IT 프로젝트 관리과정에서의 IT 개발 요구사항과 관련하여 다음을 설명하시오.','["가. IT 프로젝트 관리의 정의 및 관리 영역", "나. IT 개발 요구사항의 정의 및 특징", "다. IT 개발 요구사항의 유형 : 기능, 비기능 및 인터페이스", "라. IT 개발 요구사항의 명세 조건"]','["1. 리드문: IT 프로젝트 관리과정에서의 IT 개발 요구사항의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: IT 프로젝트 관리과정에서의 IT 개발 요구사항 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: IT 프로젝트 관리의 정의 및 관리 영역 및 IT 개발 요구사항의 정의 및 특징 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','IT, 프로젝트, 관리과정에서, 개발, 요구사항, 관리, 영역, 비기능','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. IT 프로젝트 관리의 정의 및 관리 영역", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. IT 개발 요구사항의 정의 및 특징", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. IT 개발 요구사항의 유형 : 기능, 비기능 및 인터페이스", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. IT 개발 요구사항의 명세 조건", "IT 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 4교시 4번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''IT 프로젝트 관리과정에서의 IT 개발 요구사항''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(IT 프로젝트 관리의 정의 및 관리 영역 · IT 개발 요구사항의 정의 및 특징 · IT 개발 요구사항의 유형 : 기능, 비기능 및 인터페이스)을 필수 키워드(IT, 프로젝트, 관리과정에서, 개발)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 4교시 #4 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(603,122,4,5,4,'절차/설계구현형','아래 조건으로 학생과 수강신청서 간의 관계에 대하여 다음을 작성하시오.','["가. ERD(Entity Relationship Diagram)", "나. 관계형 데이터 모델(Relational Data Model)"]','["1. 리드문: 아래 조건으로 학생과 수강신청서 간의 관계의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 아래 조건으로 학생과 수강신청서 간의 관계 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ERD(Entity Relationship Diagram) 및 관계형 데이터 모델(Relational Data Model) 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','ERD, Entity Relationship Diagram, Relational Data Model, 아래, 조건, 학생, 수강신청서, 관계','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. ERD(Entity Relationship Diagram)", "ERD 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 관계형 데이터 모델(Relational Data Model)", "Relational Data Model 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 4교시 5번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''아래 조건으로 학생과 수강신청서 간의 관계''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ERD(Entity Relationship Diagram) · 관계형 데이터 모델(Relational Data Model))을 필수 키워드(ERD, Entity Relationship Diagram, Relational Data Model, 아래)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 4교시 #5 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(604,122,4,6,2,'절차/설계구현형','아래 내용을 반영한 클래스 다이어그램(Class Diagram)을 작성하시오.','["가. 훈련교사(Trainer)는 하나 이상의 여러 종목(Program)을 훈련시킬 수 있다.", "나. 각 종목(Program)은 훈련시간표 상 슬롯(Slot)에 훈련시간(Time)과 훈련실 (Room)이 할당되어 있다", "개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name | Program | number, name / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name | Program | number, name | Room | number, name / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name | Program | number, name | Room | number, name | Time | day, hour"]','["1. 리드문: 아래 내용을 반영한 클래스 다이어그램(Class Diagram)을 작성하시오.의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 아래 내용을 반영한 클래스 다이어그램(Class Diagram)을 작성하시오. 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 훈련교사(Trainer)는 하나 이상의 여러 종목(Program)을 및 각 종목(Program)은 훈련시간표 상 슬롯(Slot)에 훈련시간 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Class Diagram, Trainer, Program, Slot, Time, Room, Entity, Attribute','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 훈련교사(Trainer)는 하나 이상의 여러 종목(Program)을 훈련시킬 수 있다.", "Trainer 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 각 종목(Program)은 훈련시간표 상 슬롯(Slot)에 훈련시간(Time)과 훈련실 (Room)이 할당되어 있다", "Program 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점", "Entity 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제122회 4교시 6번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''아래 내용을 반영한 클래스 다이어그램(Class Diagram)을 작성하시오.''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(훈련교사(Trainer)는 하나 이상의 여러 종목(Program)을 훈련시킬 수 있다. · 각 종목(Program)은 훈련시간표 상 슬롯(Slot)에 훈련시간(Time)과 훈련실 (Room)이 할당되어 있다 · 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name | Program | number, name / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name | Program | number, name | Room | number, name / 개체(Entity) | 속성(Attribute) | 학생 | 학번, 성명, 전화번호 | 수강신청서 | 신청번호, 과목명, 교수명, 학점 | 학생과 수강신청서는 일 대 다의 관계이다. 즉, 한 사람의 학생이 다수의 수강신청을 할 수 있고, 수강신청서 1개는 특정학생의 수강신청서로 되어 있다 | 클래스 | 속성 | Trainer | id, name | Program | number, name | Room | number, name | Time | day, hour)을 필수 키워드(Class Diagram, Trainer, Program, Slot)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제122회 4교시 #6 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(605,121,1,1,3,'개념/보안아키텍처형','제로트러스트(Zero Trust) 보안 모델의 핵심 원칙(Never Trust, Always Verify)과 NIST SP 800-207 아키텍처','["1. 경계 기반 보안(Perimeter Security)의 한계와 제로트러스트 7대 기본 원칙", "2. 정책결정지점(PDP: Policy Engine + Policy Administrator)과 정책시행지점(PEP) 동작 구조"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','제로트러스트, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["1. 경계 기반 보안(Perimeter Security)의 한계와 제로트러스트 7대 기본 원칙", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["2. 정책결정지점(PDP: Policy Engine + Policy Administrator)과 정책시행지점(PEP) 동작 구조", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','제로트러스트(Zero Trust) 보안 모델의 핵심 원칙(Never Trust, Always Verify)과 NIST SP 800-207 아키텍처 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 1. 경계 기반 보안(Perimeter Security)의 한계와 제로트러스트 7대 기본 원칙 및 2. 정책결정지점(PDP: Policy Engine + Policy Administrator)과 정책시행지점(PEP) 동작 구조을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제121회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(606,121,1,1,7,'개념/정의형','지능형 CCTV 스마트 관제','["1. 지능형 CCTV 스마트 관제의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 지능형 CCTV 스마트 관제의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 지능형 CCTV 스마트 관제 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 지능형 CCTV 스마트 관제 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','CCTV, 지능형, 스마트, 관제, 거버넌스, ROI·성과지표, 리스크 관리','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "지능형 CCTV 스마트 관제의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "지능형 CCTV 스마트 관제의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "지능형 CCTV 스마트 관제의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "지능형 CCTV 스마트 관제 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제121회 1교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''지능형 CCTV 스마트 관제''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(지능형 CCTV 스마트 관제의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(CCTV, 지능형, 스마트, 관제)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제121회 1교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(607,121,1,2,7,'개념/정의형','그로스 해킹(Growth Hacking)','["1. 그로스 해킹(Growth Hacking)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 그로스 해킹(Growth Hacking)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 그로스 해킹(Growth Hacking) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 그로스 해킹(Growth Hacking) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Growth Hacking, 그로스, 해킹, 거버넌스, ROI·성과지표, 리스크 관리, 이해관계자 정렬','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "그로스 해킹(Growth Hacking)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "그로스 해킹(Growth Hacking)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "그로스 해킹(Growth Hacking)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "그로스 해킹(Growth Hacking) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제121회 1교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''그로스 해킹(Growth Hacking)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(그로스 해킹(Growth Hacking)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Growth Hacking, 그로스, 해킹, 거버넌스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제121회 1교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(608,121,1,3,5,'개념/정의형','BaaS(Backend as a Service)와 FaaS(Function as a Service)','["1. BaaS(Backend as a Service)와 FaaS(Function as a Service)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: BaaS(Backend as a Service)와 FaaS(Function as a Service)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: BaaS(Backend as a Service)와 FaaS(Function as a Service) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: BaaS(Backend as a Service)와 FaaS(Function as a Service) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','BaaS, Backend as a Service, FaaS, Function as a Service, 프로토콜 스택, 대역폭·지연시간, 고가용성','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "BaaS(Backend as a Service)와 FaaS(Function as a Service)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "BaaS(Backend as a Service)와 FaaS(Function as a Service)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "BaaS(Backend as a Service)와 FaaS(Function as a Service)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "BaaS(Backend as a Service)와 FaaS(Function as a Service) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제121회 1교시 3번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''BaaS(Backend as a Service)와 FaaS(Function as a Service)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(BaaS(Backend as a Service)와 FaaS(Function as a Service)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(BaaS, Backend as a Service, FaaS, Function as a Service)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제121회 1교시 #3 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
