INSERT INTO "questions" VALUES(610,121,1,5,2,'개념/정의형','ALM(Application Lifecycle Management)','["1. ALM(Application Lifecycle Management)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: ALM(Application Lifecycle Management)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: ALM(Application Lifecycle Management) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: ALM(Application Lifecycle Management) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','ALM, Application Lifecycle Management, 품질속성, 유지보수성, 설계원칙, 검증전략','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "ALM(Application Lifecycle Management)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "ALM(Application Lifecycle Management)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "ALM(Application Lifecycle Management)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "ALM(Application Lifecycle Management) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제121회 1교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''ALM(Application Lifecycle Management)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(ALM(Application Lifecycle Management)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(ALM, Application Lifecycle Management, 품질속성, 유지보수성)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제121회 1교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(611,121,1,6,1,'절차/설계구현형','통계적 가설 검정(Statistical Hypothesis Test)의 절차','["1. 통계적 가설 검정(Statistical Hypothesis Test)의 절차의 정의 및 핵심 원리", "2. 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준"]','["1. 리드문: 통계적 가설 검정(Statistical Hypothesis Test)의 절차의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 통계적 가설 검정(Statistical Hypothesis Test)의 절차 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 통계적 가설 검정(Statistical Hypothesis Test)의 절차 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Statistical Hypothesis Test, 통계적, 가설, 검정, 아키텍처, 성능지표, 학습·추론 최적화','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "통계적 가설 검정(Statistical Hypothesis Test)의 절차의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "통계적 가설 검정(Statistical Hypothesis Test)의 절차의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "통계적 가설 검정(Statistical Hypothesis Test)의 절차의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "통계적 가설 검정(Statistical Hypothesis Test)의 절차 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제121회 1교시 6번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''통계적 가설 검정(Statistical Hypothesis Test)의 절차''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(통계적 가설 검정(Statistical Hypothesis Test)의 절차의 정의 및 핵심 원리 · 단계별 수행 절차·구현 메커니즘 및 실무 검증 기준)을 필수 키워드(Statistical Hypothesis Test, 통계적, 가설, 검정)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제121회 1교시 #6 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
