INSERT INTO "questions" VALUES(650,120,1,12,6,'개념/정의형','CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)','["1. CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 CA/OS 거버넌스 제언"]','CPU, Central Processing Unit, GPGPU, General-Purpose computing on Graphics, Processing Units, 자원스케줄링, 메모리 계층','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 1교시 12번([CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅) 실제 기출 토픽으로, ''CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(CPU(Central Processing Unit)와 GPGPU(General-Purpose computing on Graphics Processing Units)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(CPU, Central Processing Unit, GPGPU, General-Purpose computing on Graphics)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 1교시 #12 실제 기출 · [CA/OS] 컴퓨터구조 · 운영체제 · 양자컴퓨팅 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(651,120,1,13,1,'개념/정의형','워크플로우 관리(Workflow Management)의 백필(Backfill)','["1. 워크플로우 관리(Workflow Management)의 백필(Backfill)의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 워크플로우 관리(Workflow Management)의 백필(Backfill)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 워크플로우 관리(Workflow Management)의 백필(Backfill) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 워크플로우 관리(Workflow Management)의 백필(Backfill) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Workflow Management, Backfill, 워크플로우, 관리, 백필, 아키텍처, 성능지표','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "워크플로우 관리(Workflow Management)의 백필(Backfill)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "워크플로우 관리(Workflow Management)의 백필(Backfill)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "워크플로우 관리(Workflow Management)의 백필(Backfill)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "워크플로우 관리(Workflow Management)의 백필(Backfill) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 1교시 13번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''워크플로우 관리(Workflow Management)의 백필(Backfill)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(워크플로우 관리(Workflow Management)의 백필(Backfill)의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Workflow Management, Backfill, 워크플로우, 관리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 1교시 #13 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(652,120,2,1,2,'비교/아키텍처형','마이크로서비스 아키텍처(MSA) 환경에서 분산 트랜잭션 정합성을 위한 Saga 패턴(Choreography vs Orchestration)과 CQRS','["가. MSA 폴리글랏 퍼시스턴스 환경에서 2PC(Two-Phase Commit)의 한계", "나. 보상 트랜잭션 기반 Saga 패턴의 두 가지 구현 방식 비교 및 CQRS 결합 아키텍처"]','["1. 리드문: 핵심 개념 정의 및 등장 배경", "2. 아키텍처 및 핵심 메커니즘 구조도", "3. 핵심 구성요소 및 비교 분석표", "4. 실무 적용 시 고려사항 및 기술사적 제언"]','마이크로서비스 아키텍처, 아키텍처, 트레이드오프, 거버넌스, 실무 최적화','{"headers": ["핵심 구분", "주요 기술 및 메커니즘", "실무 적용 및 검증 포인트"], "rows": [["가. MSA 폴리글랏 퍼시스턴스 환경에서 2PC(Two-Phase Commit)의 한계", "표준 아키텍처 및 동작 원리 정의", "성능·보안·확장성 요구사항 충족 여부 검증"], ["나. 보상 트랜잭션 기반 Saga 패턴의 두 가지 구현 방식 비교 및 CQRS 결합 아키텍처", "대안 기술과의 정량·정성적 트레이드오프 분석", "운영 자동화 및 컴플라이언스 준수 체계 확립"]]}','마이크로서비스 아키텍처(MSA) 환경에서 분산 트랜잭션 정합성을 위한 Saga 패턴(Choreography vs Orchestration)과 CQRS 토픽은 정보관리기술사 핵심 기출 영역으로, (1) 정의 및 등장 배경을 두괄식 리드문으로 명시하고, (2) 핵심 아키텍처/프로세스 개념도를 도식화한 뒤, (3) 가. MSA 폴리글랏 퍼시스턴스 환경에서 2PC(Two-Phase Commit)의 한계 및 나. 보상 트랜잭션 기반 Saga 패턴의 두 가지 구현 방식 비교 및 CQRS 결합 아키텍처을 비교표와 함께 서술하고, (4) 최신 기술 트렌드 및 거버넌스 관점의 제언으로 마무리해야 고득점이 가능하다.','제120회 핵심 기출 및 연관 도메인 반복 출제 토픽','ITPE 정밀 4단 서브노트');
INSERT INTO "questions" VALUES(653,120,2,1,3,'원인분석/대응전략형','개념, 필요성 및 특징 (바이오정보 분산관리와 관련하여 다음을 설명하시오)','["가. 개념, 필요성 및 특징", "나. 처리과정별 보안위협 및 대책", "다. 적용 사례 및 전망"]','["1. 리드문: 개념, 필요성 및 특징 (바이오정보 분산관리와 관련하여 다음을 설명하시오)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개념, 필요성 및 특징 (바이오정보 분산관리와 관련하여 다음을 설명하시오) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개념, 필요성 및 특징 및 처리과정별 보안위협 및 대책 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','바이오정보, 분산관리, 처리과정별, 보안위협, 기밀성·무결성, 보안통제, 위협모델링','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 개념, 필요성 및 특징", "기밀성·무결성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 처리과정별 보안위협 및 대책", "처리과정별 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 적용 사례 및 전망", "기밀성·무결성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제120회 2교시 1번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''개념, 필요성 및 특징 (바이오정보 분산관리와 관련하여 다음을 설명하시오)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개념, 필요성 및 특징 · 처리과정별 보안위협 및 대책 · 적용 사례 및 전망)을 필수 키워드(바이오정보, 분산관리, 처리과정별, 보안위협)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 2교시 #1 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(654,120,2,2,7,'원인분석/대응전략형','마이데이터(MyData) 산업과 관련하여 다음을 설명하시오.','["가. 마이데이터 및 마이데이터 산업의 개념", "나. 필요성과 특징", "다. 마이데이터 산업 주체별 역할과 처리 흐름", "라. 적용 시 문제점과 해결방안"]','["1. 리드문: 마이데이터(MyData) 산업의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 마이데이터(MyData) 산업 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 마이데이터 및 마이데이터 산업의 개념 및 필요성과 특징 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','MyData, 마이데이터, 산업, 주체별, 처리, 흐름, 거버넌스','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 마이데이터 및 마이데이터 산업의 개념", "마이데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 필요성과 특징", "거버넌스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 마이데이터 산업 주체별 역할과 처리 흐름", "마이데이터 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["라. 적용 시 문제점과 해결방안", "거버넌스 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제120회 2교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''마이데이터(MyData) 산업''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(마이데이터 및 마이데이터 산업의 개념 · 필요성과 특징 · 마이데이터 산업 주체별 역할과 처리 흐름)을 필수 키워드(MyData, 마이데이터, 산업, 주체별)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 2교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(655,120,2,3,2,'비교/대조분석형','모놀리스(Monolith)와 마이크로서비스(Microservice) 아키텍처의 개념을 비교하여 설명하고 데브옵스(DevOps) 구현시의 장·단점에 대하여 설명하시오.','["1. 모놀리스(Monolith)와 마이크로서비스(Microservice) 아키텍처의 개념을 비교하여 설명하고 데브옵스(DevOps) 구현시의 장·단점에 대하여의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 모놀리스(Monolith)와 마이크로서비스(Microservice) 아키텍처의 개념을 비교하여 설명하고 데브옵스(DevOps) 구현시의 장·단점에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 모놀리스(Monolith)와 마이크로서비스(Microservice) 아키텍처의 개념을 비교하여 설명하고 데브옵스(DevOps) 구현시의 장·단점에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 모놀리스(Monolith)와 마이크로서비스(Microservice) 아키텍처의 개념을 비교하여 설명하고 데브옵스(DevOps) 구현시의 장·단점에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Monolith, Microservice, DevOps, 모놀리스, 마이크로서비스, 아키텍처, 비교하여, 설명하고','{"headers": ["비교 항목", "모놀리스(Monolith)", "마이크로서비스(Microservice) 아키텍처의 개념을"], "rows": [["핵심 개념·목적", "모놀리스(Monolith)의 고유 목적 및 적용 영역 정의", "마이크로서비스(Microservice) 아키의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제120회 2교시 3번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''모놀리스(Monolith)와 마이크로서비스(Microservice) 아키텍처의 개념을 비교하여 설명하고 데브옵스(DevOps) 구현시의 장·단점에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(모놀리스(Monolith)와 마이크로서비스(Microservice) 아키텍처의 개념을 비교하여 설명하고 데브옵스(DevOps) 구현시의 장·단점에 대하여의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Monolith, Microservice, DevOps, 모놀리스)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 2교시 #3 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(656,120,2,4,5,'비교/대조분석형','가상머신(Virtual Machine)과 컨테이너(Container)를 비교하여 설명하시오.','["1. 가상머신(Virtual Machine)과 컨테이너(Container)의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 가상머신(Virtual Machine)과 컨테이너(Container)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 가상머신(Virtual Machine)과 컨테이너(Container) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 가상머신(Virtual Machine)과 컨테이너(Container) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Virtual Machine, Container, 가상머신, 컨테이너, 비교하여, 프로토콜 스택, 대역폭·지연시간','{"headers": ["비교 항목", "가상머신(Virtual Machine)", "컨테이너(Container)"], "rows": [["핵심 개념·목적", "가상머신(Virtual Machine)의 고유 목적 및 적용 영역 정의", "컨테이너(Container)의 고유 목적 및 적용 영역 정의"], ["동작 원리·구조", "핵심 메커니즘·프로토콜 및 구성요소", "핵심 메커니즘·프로토콜 및 구성요소"], ["장단점 및 선택 기준", "성능·보안·비용 트레이드오프 기반 실무 적용성", "성능·보안·비용 트레이드오프 기반 실무 적용성"]]}','본 문항은 제120회 2교시 4번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''가상머신(Virtual Machine)과 컨테이너(Container)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(가상머신(Virtual Machine)과 컨테이너(Container)의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Virtual Machine, Container, 가상머신, 컨테이너)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 2교시 #4 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(657,120,2,5,7,'실무/시나리오형','스마트팩토리(Smart Factory)의 정보시스템 구축 사업을 통해 얻을 수 있는 성과측정 항목을 생산성(Productivity), 품질(Quality), 비용(Cost), 납기(Delivery)의 4가지 관점으로 구분하여 설명하고 매출(Revenue), 원가(Cost), 이익(Profit)에 미치는 상관관계를 설명하시오.','["1. 이익(Profit)에 미치는 상관관계의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 이익(Profit)에 미치는 상관관계의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 이익(Profit)에 미치는 상관관계 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 이익(Profit)에 미치는 상관관계 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Smart Factory, Productivity, Quality, Cost, Delivery, Revenue, Profit, 스마트팩토리','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "이익(Profit)에 미치는 상관관계의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "이익(Profit)에 미치는 상관관계의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "이익(Profit)에 미치는 상관관계의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "이익(Profit)에 미치는 상관관계 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 2교시 5번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''이익(Profit)에 미치는 상관관계''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(이익(Profit)에 미치는 상관관계의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Smart Factory, Productivity, Quality, Cost)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 2교시 #5 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(658,120,2,6,5,'법제도/거버넌스형','대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어 설명하시오.','["1. 대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','Queue System, 대기행렬시스템, 설명하고, 처리, 들어, 프로토콜 스택, 대역폭·지연시간','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 2교시 6번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(대기행렬시스템(Queue System)의 개념을 설명하고, 처리 기법을 예를 들어의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Queue System, 대기행렬시스템, 설명하고, 처리)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 2교시 #6 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(659,120,3,1,7,'비교/대조분석형','QR코드 기반의 결제 방식과 관련하여 다음을 설명하시오.','["가. MPM(Merchant Presented Mode)/CPM(Customer Presented Mode) 비교", "나. 도입시 보안 고려사항 및 시사점"]','["1. 리드문: QR코드 기반의 결제 방식의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: QR코드 기반의 결제 방식 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: MPM(Merchant Presented Mode)/CPM(Custo 및 도입시 보안 고려사항 및 시사점 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','QR, MPM, Merchant Presented Mode, CPM, Customer Presented Mode, 코드, 결제, 도입시','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. MPM(Merchant Presented Mode)/CPM(Customer Presented Mode) 비교", "MPM 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 도입시 보안 고려사항 및 시사점", "도입시 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제120회 3교시 1번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''QR코드 기반의 결제 방식''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(MPM(Merchant Presented Mode)/CPM(Customer Presented Mode) 비교 · 도입시 보안 고려사항 및 시사점)을 필수 키워드(QR, MPM, Merchant Presented Mode, CPM)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 3교시 #1 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(660,120,3,2,8,'실무/시나리오형','레그테크(Regtech)와 관련하여 다음을 설명하시오.','["가. 레그테크 정의와 필요성", "나. 주요 특징", "다. 추진동향 및 도입시 고려사항"]','["1. 리드문: 레그테크(Regtech)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 레그테크(Regtech) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 레그테크 정의와 필요성 및 주요 특징 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','Regtech, 레그테크, 추진동향, 도입시, 법적 근거, 컴플라이언스, 관리체계','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 레그테크 정의와 필요성", "레그테크 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 주요 특징", "법적 근거 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 추진동향 및 도입시 고려사항", "추진동향 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제120회 3교시 2번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''레그테크(Regtech)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(레그테크 정의와 필요성 · 주요 특징 · 추진동향 및 도입시 고려사항)을 필수 키워드(Regtech, 레그테크, 추진동향, 도입시)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 3교시 #2 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(661,120,3,3,1,'법제도/거버넌스형','머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법을 설명하시오.','["1. 머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Machine Learning, Ensemble, 머신, 러닝, 활용되, 앙상블, 아키텍처','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 3교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(머신 러닝(Machine Learning)에서 활용되는 앙상블(Ensemble) 기법의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Machine Learning, Ensemble, 머신, 러닝)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 3교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(662,120,3,4,5,'비교/대조분석형','네트워크 가상화 기술인 VLAN(Virtual LAN), VPN(Virtual Private Network), NFV(Network Function Virtualization)를 비교하여 설명하시오.','["1. NFV(Network Function Virtualization)의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: NFV(Network Function Virtualization)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: NFV(Network Function Virtualization) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: NFV(Network Function Virtualization) 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 NW/Cloud 거버넌스 제언"]','VLAN, Virtual LAN, VPN, Virtual Private Network, NFV, Network Function Virtualization, 네트워크, 가상화','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "NFV(Network Function Virtualization)의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "NFV(Network Function Virtualization)의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "NFV(Network Function Virtualization)의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "NFV(Network Function Virtualization) 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 3교시 4번([NW/Cloud] 네트워크 · 클라우드 · 차세대통신) 실제 기출 토픽으로, ''NFV(Network Function Virtualization)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(NFV(Network Function Virtualization)의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(VLAN, Virtual LAN, VPN, Virtual Private Network)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 3교시 #4 실제 기출 · [NW/Cloud] 네트워크 · 클라우드 · 차세대통신 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(663,120,3,5,2,'개념/정의형','소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여 설명하시오.','["1. 소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 SW/Arch 거버넌스 제언"]','Architecture, 소프트웨어, 아키텍처, 모델, 품질속성, 유지보수성, 설계원칙','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 3교시 5번([SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트) 실제 기출 토픽으로, ''소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(소프트웨어 아키텍처(Architecture)의 모델 유형에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(Architecture, 소프트웨어, 아키텍처, 모델)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 3교시 #5 실제 기출 · [SW/Arch] 소프트웨어공학 · 아키텍처 · 테스트 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(664,120,3,6,8,'법제도/거버넌스형','클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도를 설명하시오.','["1. 클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','클라우드, 컴퓨팅서비스, 공공기관, 보안인증제도, 법적 근거, 컴플라이언스, 관리체계','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 3교시 6번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(클라우드 컴퓨팅서비스에 대한 공공기관의 보안인증제도의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(클라우드, 컴퓨팅서비스, 공공기관, 보안인증제도)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 3교시 #6 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(665,120,4,1,3,'절차/설계구현형','정보시스템의 사용자 인증 요소(User Authentication Factor)와 관련하여 다음을 설명하시오.','["가. 사용자 인증의 정의 및 필요성", "나. 사용자 인증의 절차", "다. 사용자 인증 요소별 특징"]','["1. 리드문: 정보시스템의 사용자 인증 요소(User Authentication Factor)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 정보시스템의 사용자 인증 요소(User Authentication Factor) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 사용자 인증의 정의 및 필요성 및 사용자 인증의 절차 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','User Authentication Factor, 정보시스템, 사용자, 인증, 요소별, 기밀성·무결성, 보안통제','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 사용자 인증의 정의 및 필요성", "사용자 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 사용자 인증의 절차", "사용자 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 사용자 인증 요소별 특징", "사용자 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제120회 4교시 1번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''정보시스템의 사용자 인증 요소(User Authentication Factor)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(사용자 인증의 정의 및 필요성 · 사용자 인증의 절차 · 사용자 인증 요소별 특징)을 필수 키워드(User Authentication Factor, 정보시스템, 사용자, 인증)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 4교시 #1 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(666,120,4,2,7,'개념/정의형','오픈 뱅킹(Open Banking)과 관련하여 다음을 설명하시오.','["가. 개념 및 등장 배경", "나. 구성 주체 및 역할", "다. 기대 효과 및 시장 전망"]','["1. 리드문: 오픈 뱅킹(Open Banking)의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 오픈 뱅킹(Open Banking) 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개념 및 등장 배경 및 구성 주체 및 역할 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 ITBiz/PM 거버넌스 제언"]','Open Banking, 오픈, 뱅킹, 등장, 구성, 주체, 기대, 시장','{"headers": ["출제 세부 항목", "핵심 서술 키워드 및 원리", "기술사 답안 가산점 포인트"], "rows": [["가. 개념 및 등장 배경", "등장 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["나. 구성 주체 및 역할", "구성 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"], ["다. 기대 효과 및 시장 전망", "기대 중심 메커니즘·절차 구조화", "개념도/흐름도 도식화 및 정량·정성 비교 근거 제시"]]}','본 문항은 제120회 4교시 2번([ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR) 실제 기출 토픽으로, ''오픈 뱅킹(Open Banking)''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개념 및 등장 배경 · 구성 주체 및 역할 · 기대 효과 및 시장 전망)을 필수 키워드(Open Banking, 오픈, 뱅킹, 등장)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 4교시 #2 실제 기출 · [ITBiz/PM] 프로젝트관리 · IT경영 · 감리 · BPR (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(667,120,4,3,1,'비교/대조분석형','딥러닝(Deep Learning)의 파라미터(Parameter)와 하이퍼파라미터(Hyperparameter)를 비교하고, 하이퍼파라미터의 튜닝 방법을 설명하시오.','["1. 하이퍼파라미터의 튜닝 방법의 핵심 개념 정의 및 등장 배경", "2. 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점", "3. 실무 적용 시 트레이드오프 및 선정·고도화 고려사항"]','["1. 리드문: 하이퍼파라미터의 튜닝 방법의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 하이퍼파라미터의 튜닝 방법 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 하이퍼파라미터의 튜닝 방법 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 AI/Data 거버넌스 제언"]','Deep Learning, Parameter, Hyperparameter, 딥러닝, 파라미터, 하이퍼파라미터, 비교하고, 튜닝','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "하이퍼파라미터의 튜닝 방법의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "하이퍼파라미터의 튜닝 방법의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "하이퍼파라미터의 튜닝 방법의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "하이퍼파라미터의 튜닝 방법 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 4교시 3번([AI/Data] 인공지능 · 빅데이터 · 통계) 실제 기출 토픽으로, ''하이퍼파라미터의 튜닝 방법''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(하이퍼파라미터의 튜닝 방법의 핵심 개념 정의 및 등장 배경 · 주요 구성요소·동작 메커니즘 및 비교 기준별 차이점 · 실무 적용 시 트레이드오프 및 선정·고도화 고려사항)을 필수 키워드(Deep Learning, Parameter, Hyperparameter, 딥러닝)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 4교시 #3 실제 기출 · [AI/Data] 인공지능 · 빅데이터 · 통계 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(668,120,4,4,4,'개념/정의형','웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여 설명하시오.','["1. 웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 DB 거버넌스 제언"]','서비스, 제공하기, 위하여, 여러, 서버, 데이터, 복제하, 복제','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 4교시 4번([DB] 데이터베이스 · 데이터모델링 · 분산데이터) 실제 기출 토픽으로, ''웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(웹 서비스를 제공하기 위하여 여러 서버에 데이터를 복제하는 경우의 복제 유형에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(서비스, 제공하기, 위하여, 여러)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 4교시 #4 실제 기출 · [DB] 데이터베이스 · 데이터모델링 · 분산데이터 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(669,120,4,5,8,'법제도/거버넌스형','개인정보의 비식별조치 가이드라인에 대하여 설명하시오.','["1. 개인정보의 비식별조치 가이드라인에 대하여의 개념 정의 및 필요성", "2. 핵심 구성요소·동작 원리 및 실무 활용 방안"]','["1. 리드문: 개인정보의 비식별조치 가이드라인에 대하여의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 개인정보의 비식별조치 가이드라인에 대하여 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 개인정보의 비식별조치 가이드라인에 대하여 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Law/Gov 거버넌스 제언"]','개인정보, 비식별조치, 가이드라인, 법적 근거, 컴플라이언스, 관리체계, 공공정책','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "개인정보의 비식별조치 가이드라인에 대하여의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "개인정보의 비식별조치 가이드라인에 대하여의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "개인정보의 비식별조치 가이드라인에 대하여의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "개인정보의 비식별조치 가이드라인에 대하여 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 4교시 5번([Law/Gov] IT 법제도 · AI거버넌스 · 공공정책) 실제 기출 토픽으로, ''개인정보의 비식별조치 가이드라인에 대하여''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(개인정보의 비식별조치 가이드라인에 대하여의 개념 정의 및 필요성 · 핵심 구성요소·동작 원리 및 실무 활용 방안)을 필수 키워드(개인정보, 비식별조치, 가이드라인, 법적 근거)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 4교시 #5 실제 기출 · [Law/Gov] IT 법제도 · AI거버넌스 · 공공정책 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
INSERT INTO "questions" VALUES(670,120,4,6,3,'원인분석/대응전략형','블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항을 설명하시오.','["1. 블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항의 개념 및 발생 원인·위협 메커니즘", "2. 기술적·관리적 대응 방안 및 아키텍처 통제 전략"]','["1. 리드문: 블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항의 핵심 정의 및 출제·도입 배경", "2. 구조·원리: 블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항 아키텍처 개념도 및 동작 메커니즘", "3. 핵심 논점: 블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항 핵심 메커니즘·비교 기준 정밀 분석 및 비교표", "4. 제언·고려사항: 실무 적용 한계 극복 및 Sec 거버넌스 제언"]','블록체인, 플랫폼, 구축과정, 성능, 보안, 기밀성·무결성, 보안통제','{"headers": ["4단 답안 구성", "핵심 작성 내용", "채점 강조 포인트"], "rows": [["1단: 정의 및 배경", "블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항의 두괄식 정의와 기술적·비즈니스 등장 배경", "핵심 키워드 2~3개 포함 3~4줄 리드문 압축"], ["2단: 구조 및 메커니즘", "블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항의 구성요소·처리 흐름 개념도 및 핵심 원리", "블록 다이어그램·순서도 시각화"], ["3단: 비교 및 실무 적용", "블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항의 주요 특징, 대안 기술 비교 및 실무 구현 방안", "비교 매트릭스·수치/표준 규격 명시"], ["4단: 한계 및 제언", "블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항 도입 시 제약사항·보안/성능 리스크 및 해결 방안", "현업 아키텍처 개선 및 거버넌스 통찰"]]}','본 문항은 제120회 4교시 6번([Sec] 정보보안 · 암호 · 개인정보보호) 실제 기출 토픽으로, ''블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항''의 핵심 개념과 실무 적용성을 묻는다. 답안 서술 시 (1) 두괄식 리드문으로 정의·배경을 명확히 선언하고, (2) 핵심 아키텍처 또는 처리 절차를 도해로 구조화한 뒤, (3) 세부 요구사항(블록체인 플랫폼 구축과정에서 성능 및 보안 측면의 고려사항의 개념 및 발생 원인·위협 메커니즘 · 기술적·관리적 대응 방안 및 아키텍처 통제 전략)을 필수 키워드(블록체인, 플랫폼, 구축과정, 성능)와 비교표로 논리 전개하며, (4) 실무 적용 시 트레이드오프·보안/성능 고려사항 및 최신 표준 연계 제언으로 마무리해야 고득점이 가능하다.','제120회 4교시 #6 실제 기출 · [Sec] 정보보안 · 암호 · 개인정보보호 (IT위키 / Q-Net 공개 기출)','IT위키 / Q-Net 공개 기출');
